import DeleteAll from "./DeleteAll";

function FileMenu() {
    return (
        <div className="file-menu-wrapper" tabIndex="0">
            <button type="button" className="file-menu-btn" title="Files">
                <i className="fa-light fa-file-alt"></i>
            </button>

            <ul className="dropdown-menu file-menu-dropdown">
                <li>
                    <label htmlFor="fileUpload" className="custom-label">
                        <i className="fa-light fa-upload mr"></i> Upload Files
                    </label>
                </li>
                <li>
                    <label htmlFor="folderUpload" className="custom-label">
                        <i className="fa-light fa-folder-upload mr"></i> Upload Folder
                    </label>
                </li>
                <DeleteAll />
                <li>
                    <label className="custom-label">
                        <i className="fa-light fa-search mr"></i> Quick Search
                    </label>
                </li>
            </ul>
        </div>
    );
}

export default FileMenu;