import { useState } from "react";
import { createPortal } from "react-dom";
import { routes } from "../Constants";
import { toast } from "react-toastify";
import "../proposalpopup.css";

function CreateProjectPopup({ setDisplay }) {
    const [projectData, setProjectData] = useState({
        name: "",
        bid_date: "",
        tax: "",
        oh: "",
        profit: "",
    });

    const [saving, setSaving] = useState(false);

    const handleInputChange = (event) => {
        const { name, value } = event.target;

        setProjectData((previousData) => ({
            ...previousData,
            [name]: value,
        }));
    };

    const handleClose = () => {
        if (saving) {
            return;
        }

        setDisplay(false);
    };

    const handleFormSubmit = async (event) => {
        event.preventDefault();

        if (saving) {
            return;
        }

        try {
            setSaving(true);

            const response = await fetch(routes.newProject, {
                method: "POST",
                headers: {
                    Accept: "application/json",
                    Authorization: `Bearer ${routes.__token}`,
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({
                    name: projectData.name.trim(),
                    bid_date: projectData.bid_date,

                    tax:
                        projectData.tax === ""
                            ? 0
                            : Number(projectData.tax),

                    oh:
                        projectData.oh === ""
                            ? 0
                            : Number(projectData.oh),

                    profit:
                        projectData.profit === ""
                            ? 0
                            : Number(projectData.profit),
                }),
            });

            const responseText = await response.text();

            let responseData = {};

            try {
                responseData = responseText
                    ? JSON.parse(responseText)
                    : {};
            } catch (error) {
                throw new Error(
                    "The server returned an invalid response."
                );
            }

            if (!response.ok || Number(responseData.status) !== 200) {
                const validationErrors =
                    responseData?.errors
                        ? Object.values(responseData.errors)
                              .flat()
                              .join("\n")
                        : "";

                throw new Error(
                    validationErrors ||
                    responseData?.message ||
                    "Unable to create the project."
                );
            }

            toast.success("Project created successfully!", {
                position: "top-right",
                autoClose: 3000,
                hideProgressBar: false,
                closeOnClick: true,
                pauseOnHover: true,
                draggable: true,
            });

            if (responseData.url) {
                window.location.href = responseData.url;
                return;
            }

            setDisplay(false);
        } catch (error) {
            console.error("CREATE PROJECT ERROR:", error);

            toast.error(
                error?.message ||
                "Something went wrong. Please try again.",
                {
                    position: "top-right",
                    autoClose: 5000,
                    hideProgressBar: false,
                    closeOnClick: true,
                    pauseOnHover: true,
                    draggable: true,
                }
            );
        } finally {
            setSaving(false);
        }
    };

    return createPortal(
        <div
            className="create-project-overlay"
            onMouseDown={(event) => {
                if (event.target === event.currentTarget) {
                    handleClose();
                }
            }}
        >
            <div className="create-project-modal">
                <header className="create-project-header">
                    <div>
                        <h3>Create New Project</h3>

                        <span>
                            Add the project details before starting the
                            takeoff.
                        </span>
                    </div>

                    <button
                        type="button"
                        className="create-project-close"
                        onClick={handleClose}
                        disabled={saving}
                    >
                        <i className="fa-light fa-xmark"></i>
                    </button>
                </header>

                <form onSubmit={handleFormSubmit}>
                    <div className="create-project-body">
                        <label className="create-project-field">
                            <span>
                                Project Name <b>*</b>
                            </span>

                            <input
                                type="text"
                                name="name"
                                value={projectData.name}
                                onChange={handleInputChange}
                                placeholder="e.g. Oakridge Commercial Takeoff"
                                required
                                autoFocus
                            />
                        </label>

                        <label className="create-project-field">
                            <span>
                                Bid Date <b>*</b>
                            </span>

                            <input
                                type="date"
                                name="bid_date"
                                value={projectData.bid_date}
                                onChange={handleInputChange}
                                required
                            />
                        </label>

                        <div className="create-project-percentages">
                            <label className="create-project-field">
                                <span>Tax (%)</span>

                                <input
                                    type="number"
                                    name="tax"
                                    min="0"
                                    step="0.01"
                                    value={projectData.tax}
                                    onChange={handleInputChange}
                                    placeholder="0"
                                />
                            </label>

                            <label className="create-project-field">
                                <span>OH (%)</span>

                                <input
                                    type="number"
                                    name="oh"
                                    min="0"
                                    step="0.01"
                                    value={projectData.oh}
                                    onChange={handleInputChange}
                                    placeholder="0"
                                />
                            </label>

                            <label className="create-project-field">
                                <span>Profit (%)</span>

                                <input
                                    type="number"
                                    name="profit"
                                    min="0"
                                    step="0.01"
                                    value={projectData.profit}
                                    onChange={handleInputChange}
                                    placeholder="0"
                                />
                            </label>
                        </div>
                    </div>

                    <footer className="create-project-footer">
                        <button
                            type="button"
                            className="create-project-cancel"
                            onClick={handleClose}
                            disabled={saving}
                        >
                            Cancel
                        </button>

                        <button
                            type="submit"
                            className="create-project-save"
                            disabled={saving}
                        >
                            {saving ? (
                                <>
                                    <i className="fa-light fa-spinner-third fa-spin"></i>
                                    Saving...
                                </>
                            ) : (
                                <>
                                    <i className="fa-light fa-floppy-disk"></i>
                                    Save Project
                                </>
                            )}
                        </button>
                    </footer>
                </form>
            </div>
        </div>,
        document.querySelector("#root")
    );
}

export default CreateProjectPopup;