import { useState } from "react";
import PdfPreviewPopup from "./PdfPreviewPopup";

function FileUpload() {
  const [showPreview, setShowPreview] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);

  // 📂 Cuando se elige archivo desde el botón FILE
  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // solo PDFs
    if (file.type !== "application/pdf") {
      alert("Solo se permiten archivos PDF.");
      return;
    }

    setSelectedFile(file);
    setShowPreview(true);

    // Limpia el input (para permitir seleccionar el mismo archivo otra vez)
    e.target.value = null;
  };

  return (
    <>
      {/* input oculto */}
      <input
        type="file"
        id="fileUpload"
        accept=".pdf"
        onChange={handleFileChange}
        style={{ display: "none" }}
      />

      {/* popup */}
      {showPreview && (
        <PdfPreviewPopup file={selectedFile} setDisplay={setShowPreview} />
      )}
    </>
  );
}

export default FileUpload;
