import { useRef, useEffect, useState, useCallback } from "react";
import { useLocation } from "react-router-dom";
import { routes } from "../Constants";
import useSignal from "../hooks/signals";
import { MapInteractionCSS } from "react-map-interaction";
import FileLoader from "./FileLoader";
import SVGBoard from "./SVGBoard";

// ==========================
//   RENDER PNG/JPG TO CANVAS
// ==========================
async function renderImageToCanvas(url, scaleFactor = 1) {
  const img = new Image();
  img.crossOrigin = "anonymous";

  return new Promise((resolve, reject) => {
    img.onload = () => {
      try {
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");

        canvas.width = Math.round(img.width * scaleFactor);
        canvas.height = Math.round(img.height * scaleFactor);

        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas);
      } catch (e) {
        reject(e);
      }
    };
    img.onerror = reject;
    img.src = url;
  });
}

function Drawing() {
  const containerRef = useRef(null); // contenedor del canvas + SVG overlay
  const wrapperRef = useRef(null); // área visible (para medir)
  const needsFitRef = useRef(false);

  const { pathname } = useLocation();
  const location = useLocation();
  const locationState = location.state;
  const signal = useSignal();

  const [rotate, setRotate] = useState(0);
  const [loading, setLoading] = useState(false);

  // MapInteractionCSS: SOLO pan
  const [view, setView] = useState({
    scale: 0.12,
    translation: { x: 0, y: 0 },
  });

  // zoom REAL (tu control)
  const MIN_ZOOM = 0.12;
  const MAX_ZOOM = 5;
  const [zoom, setZoom] = useState(MIN_ZOOM);

  // tamaño del canvas para alinear overlays
  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });

  const zoomBy = useCallback(
    (direction, point = null) => {
      const wrapper = wrapperRef.current;
      if (!wrapper) return;

      const rect = wrapper.getBoundingClientRect();
      // Si no tenemos punto (ej. botones +/-), usamos el centro del contenedor
      const px = point ? point.x - rect.left : rect.width / 2;
      const py = point ? point.y - rect.top : rect.height / 2;

      const ZOOM_MULT = 1.08; // Incremento del 8% por paso

      setZoom((prevZoom) => {
        const nextZoom = direction > 0 ? prevZoom * ZOOM_MULT : prevZoom / ZOOM_MULT;
        const clampedZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, nextZoom));

        if (clampedZoom === prevZoom) return prevZoom;

        // Calculamos la relación de escala para ajustar la traslación
        const ratio = clampedZoom / prevZoom;

        setView((prevView) => ({
          ...prevView,
          translation: {
            x: px - (px - prevView.translation.x) * ratio,
            y: py - (py - prevView.translation.y) * ratio,
          },
        }));

        return clampedZoom;
      });
    },
    [MIN_ZOOM, MAX_ZOOM]
  );

  // ✅ FIT + CENTER (para que NO se vea “un pedazo”)
  const fitToScreen = useCallback(() => {
    const wrapper = wrapperRef.current;
    const host = containerRef.current;
    if (!wrapper || !host) return;

    const canvas = host.querySelector("canvas");
    if (!canvas) return;

    const wrapRect = wrapper.getBoundingClientRect();
    if (!wrapRect.width || !wrapRect.height) return;

    const cw = canvas.width || canvas.offsetWidth;
    const ch = canvas.height || canvas.offsetHeight;
    if (!cw || !ch) return;

    const pad = 0.75;
    const scaleFit = Math.min((wrapRect.width * pad) / cw, (wrapRect.height * pad) / ch);
    const nextZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, scaleFit));

    setZoom(nextZoom);

    const contentW = cw * nextZoom;
    const contentH = ch * nextZoom;
    const TOP_OFFSET = 60;

    setView((prev) => ({
      ...prev,
      translation: {
        x: ((wrapRect.width - contentW) / 2) - 20,
        y: ((wrapRect.height - contentH) / 2) - TOP_OFFSET,
      },
    }));
  }, [MIN_ZOOM, MAX_ZOOM]);

  // ==========================
  //       ROTATE SIGNAL
  // ==========================
  useEffect(() => {
    const callBack = () => setRotate((a) => a + 90);

    signal.listen("rotate", callBack);
    return () => signal.unsubscribe("rotate", callBack);
  }, []);

  // ============================================================
  //     LOADER PRINCIPAL (PNG/JPG/JPEG)
  // ============================================================
  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        signal.emit("tab.active", { pathname });
      } catch (e) { }

      setLoading(true);

      // reset para no heredar del anterior
      setZoom(MIN_ZOOM);
      setView({ scale: 1, translation: { x: 0, y: 0 } });
      setCanvasSize({ width: 0, height: 0 });

      const fullUrl =
      locationState?.fileUrl
        ? locationState.fileUrl
        : routes.public + pathname;
      const lower = fullUrl.toLowerCase();

      let canvas = null;

      const isRaster =
        lower.endsWith(".png") || lower.endsWith(".jpg") || lower.endsWith(".jpeg");

      if (!isRaster) {
        setLoading(false);
        return;
      }

      canvas = await renderImageToCanvas(fullUrl, 1);

      if (cancelled) return;

      if (canvas && containerRef.current) {
        // limpia SOLO el canvas del contenedor
        const prev = containerRef.current.querySelector("canvas");
        if (prev) prev.remove();

        containerRef.current.appendChild(canvas);

        setCanvasSize({ width: canvas.width, height: canvas.height });

        // ⚠️ NO hacer fit aquí si el contenedor está oculto por loading
        needsFitRef.current = true;
      }

      setLoading(false);
    })().catch((e) => {
      console.error("Error loading image:", e);
      setLoading(false);
    });

    return () => {
      cancelled = true;
      const host = containerRef.current;
      if (host) {
        const prev = host.querySelector("canvas");
        if (prev) prev.remove();
      }
    };
  }, [pathname]);

  // ✅ hacer FIT cuando ya se muestra el contenedor (loading=false)
  useEffect(() => {
    if (loading) return;
    if (!needsFitRef.current) return;

    needsFitRef.current = false;

    // doble RAF para asegurar layout listo
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        fitToScreen();
      });
    });
  }, [loading, fitToScreen]);

  // ✅ Refit al resize
  useEffect(() => {
    const onResize = () => {
      if (!loading) fitToScreen();
    };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [fitToScreen, loading]);

  // ==========================
  //   WHEEL ZOOM (captura)
  // ==========================
  useEffect(() => {
    const el = wrapperRef.current;
    if (!el || loading) return;

    const onWheel = (e) => {
      e.preventDefault();
      e.stopPropagation();
      zoomBy(e.deltaY < 0 ? 1 : -1, { x: e.clientX, y: e.clientY });
    };

    // capture:true para ganarle a listeners del wrapper/lib
    el.addEventListener("wheel", onWheel, { passive: false, capture: true });

    return () => {
      el.removeEventListener("wheel", onWheel, { capture: true });
    };
  }, [loading, zoomBy]);

  return (
    <>
      <div
        ref={wrapperRef}
        className={`drawing-board__container ${loading ? "hidden" : ""}`}
        style={{
          position: "relative",
          overscrollBehavior: "contain",
          touchAction: "none",
        }}
      >
        {/* Controles de zoom */}
        <div
          style={{
            position: "absolute",
            right: 10,
            top: 10,
            zIndex: 20,
            display: "flex",
            flexDirection: "column",
            gap: 6,
          }}
        >
          <button type="button" style={{ width: 30, paddingTop: 5 }} onClick={() => zoomBy(1)}>
            +
          </button>
          <button type="button" style={{ width: 30, paddingTop: 5 }} onClick={() => zoomBy(-1)}>
            -
          </button>
        </div>

        <MapInteractionCSS
          // pan solamente
          minScale={1}
          maxScale={1}
          value={view}
          onChange={setView}
          showControls={false}
        >
          {/* Este contenedor se escala (zoom) y rota, y dentro vive el canvas + overlays */}
          <div
            ref={containerRef}
            style={{
              position: "relative",
              width: canvasSize.width ? `${canvasSize.width}px` : "auto",
              height: canvasSize.height ? `${canvasSize.height}px` : "auto",
              transform: `rotate(${rotate}deg) scale(${zoom})`,
              transformOrigin: "0 0",
            }}
          >
            {/* ✅ SVG solo overlays. NO meter el PNG aquí */}
            <SVGBoard
              transform={{ scale: zoom }}
              canvasWidth={canvasSize.width}
              canvasHeight={canvasSize.height}
            />
          </div>
        </MapInteractionCSS>
      </div>

      {loading ? <FileLoader /> : null}
    </>
  );
}

export default Drawing;
