import React from "react";

function AnnotationContextMenu({ details, onEdit, onDelete }) {
  return (
    <div
      className="annotation-context-menu"
      style={{
        position: "fixed",
        top: details.y,
        left: details.x,
        background: "#ffffff",
        border: "1px solid #dcdcdc",
        borderRadius: "8px",
        boxShadow: "0 8px 24px rgba(0,0,0,0.15)",
        zIndex: 99999,
        minWidth: "160px",
        overflow: "hidden",
      }}
    >
      <button
        type="button"
        onClick={onEdit}
        style={{
          width: "100%",
          border: "none",
          background: "transparent",
          padding: "12px 14px",
          textAlign: "left",
          cursor: "pointer",
        }}
      >
        Edit
      </button>

      <button
        type="button"
        onClick={onDelete}
        style={{
          width: "100%",
          border: "none",
          background: "transparent",
          padding: "12px 14px",
          textAlign: "left",
          cursor: "pointer",
          color: "#dc3545",
        }}
      >
        Delete
      </button>
    </div>
  );
}

export default AnnotationContextMenu;