import React from "react";

const COLOR_OPTIONS = [
  { hex: "#000000", name: "Black" },
  { hex: "#ff0000", name: "Red" },
  { hex: "#00ff00", name: "Green" },
  { hex: "#0000ff", name: "Blue" },
  { hex: "#ffa500", name: "Orange" },
  { hex: "#800080", name: "Purple" },
  { hex: "#ffff00", name: "Yellow" },
  { hex: "#00ffff", name: "Cyan" },
  { hex: "#808080", name: "Gray" },
  { hex: "#e22b88", name: "Pink" },
  { hex: "#008000", name: "Dark Green" },
  { hex: "#ff1493", name: "Deep Pink" },
  { hex: "#1e90ff", name: "Dodger Blue" },
];

function WritePopup({
  setDisplay,
  textValue,
  textColorValue,
  textFontSizeValue,
  onChangeTextValue,
  onChangeTextColorValue,
  onChangeTextFontSizeValue,
  onSaveText,
  onCancelText,
}) {
  const handleClose = () => {
    setDisplay(false);
    onCancelText();
  };

  const handleSave = () => {
    onSaveText();
  };

  const preview_font_size = Math.max(12, textFontSizeValue * 0.25);

  return (
    <div
      className="write-popup-overlay"
      onClick={handleClose}
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0, 0, 0, 0.45)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 99999,
        padding: "20px",
      }}
    >
      <div
        className="write-popup-container"
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "100%",
          maxWidth: "760px",
          background: "#ffffff",
          borderRadius: "12px",
          boxShadow: "0 20px 50px rgba(0,0,0,0.20)",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            padding: "14px 18px",
            borderBottom: "1px solid #e9ecef",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <div>
            <div style={{ fontSize: "18px", fontWeight: 700 }}>Write Text</div>
            <div style={{ fontSize: "12px", color: "#6c757d", marginTop: "2px" }}>
              Choose color and font size, then write your annotation. When you type "=" at the end of an expression, it will be calculated automatically.
            </div>
          </div>

          <button
            type="button"
            onClick={handleClose}
            style={{
              border: "none",
              background: "transparent",
              fontSize: "24px",
              lineHeight: 1,
              cursor: "pointer",
              color: "#6c757d",
            }}
          >
            ×
          </button>
        </div>

        <div style={{ padding: "18px" }}>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "12px",
              marginBottom: "14px",
            }}
          >
            <div>
              <label
                style={{
                  display: "block",
                  fontSize: "13px",
                  marginBottom: "6px",
                  color: "#495057",
                }}
              >
                Text Color
              </label>
              <select
                value={textColorValue}
                onChange={(e) => onChangeTextColorValue(e.target.value)}
                style={{
                  width: "100%",
                  border: "1px solid #ced4da",
                  borderRadius: "8px",
                  padding: "10px 12px",
                  outline: "none",
                  background: "#fff",
                }}
              >
                {COLOR_OPTIONS.map((color) => (
                  <option
                    key={color.hex}
                    value={color.hex}
                    style={{
                      backgroundColor: color.hex,
                      color: ["#ffff00", "#00ff00", "#00ffff"].includes(color.hex)
                        ? "#000"
                        : "#fff",
                      fontWeight: "bold",
                    }}
                  >
                    {color.name}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label
                style={{
                  display: "block",
                  fontSize: "13px",
                  marginBottom: "6px",
                  color: "#495057",
                }}
              >
                Font Size
              </label>
              <input
                type="number"
                min="8"
                max="2000"
                step="1"
                value={textFontSizeValue}
                onChange={(e) => onChangeTextFontSizeValue(e.target.value)}
                style={{
                  width: "100%",
                  border: "1px solid #ced4da",
                  borderRadius: "8px",
                  padding: "10px 12px",
                  outline: "none",
                }}
              />
            </div>
          </div>

          <div style={{ marginBottom: "14px" }}>
            <label
              style={{
                display: "block",
                fontSize: "13px",
                marginBottom: "6px",
                color: "#495057",
              }}
            >
              Text
            </label>
            <textarea
              value={textValue}
              onChange={(e) => onChangeTextValue(e.target.value)}
              placeholder='Example: the required calculation is 5x2='
              autoFocus
              rows={6}
              style={{
                width: "100%",
                border: "1px solid #ced4da",
                borderRadius: "8px",
                padding: "12px 14px",
                resize: "vertical",
                outline: "none",
                fontSize: "15px",
                lineHeight: "1.5",
                color: "#212529",
              }}
            />
          </div>

          <div
            style={{
              padding: "14px",
              borderRadius: "8px",
              background: "#f8f9fa",
              border: "1px solid #e9ecef",
            }}
          >
            <div style={{ fontSize: "12px", color: "#6c757d", marginBottom: "8px" }}>
              Preview
            </div>

            <div
              style={{
                minHeight: "120px",
                maxHeight: "260px",
                overflow: "auto",
                color: textColorValue,
                fontSize: `${preview_font_size}px`,
                wordBreak: "break-word",
                whiteSpace: "pre-wrap",
                lineHeight: "1.25",
              }}
            >
              {textValue || "Your text preview will appear here"}
            </div>
          </div>
        </div>

        <div
          style={{
            padding: "14px 18px",
            borderTop: "1px solid #e9ecef",
            display: "flex",
            justifyContent: "flex-end",
            gap: "10px",
          }}
        >
          <button
            type="button"
            onClick={handleClose}
            style={{
              border: "1px solid #ced4da",
              background: "#ffffff",
              color: "#495057",
              borderRadius: "8px",
              padding: "10px 16px",
              cursor: "pointer",
              fontWeight: 600,
            }}
          >
            Cancel
          </button>

          <button
            type="button"
            onClick={handleSave}
            style={{
              border: "none",
              background: "#0d6efd",
              color: "#ffffff",
              borderRadius: "8px",
              padding: "10px 16px",
              cursor: "pointer",
              fontWeight: 600,
            }}
          >
            Save
          </button>
        </div>
      </div>
    </div>
  );
}

export default WritePopup;