    const handleCreate = async (e) => {
        e.preventDefault();

        try {
            const isUpdate = !!formData.id;

            // ✅ CONFIRMACIÓN SEGÚN ESTADO DE USO
            const confirmMsg = isInUse
                ? "This will be saved only in the takeoff. Do you want to continue?"
                : "This will apply a global modification. Do you want to continue?";

            const confirm = await uiConfirm({
                title: "Confirm Save",
                text: confirmMsg,
                confirmText: "Yes, Save",
                icon: "question",
            });

            if (!confirm) return;

            // ✅ SI ESTÁ EN USO -> GUARDADO LOCAL (JSON)
            if (isInUse) {
                const normalized = {
                    course: {
                        ...formData,
                        id: formData.id, // mantenemos el mismo id
                        id_local: formData.id_local || `loc_${Date.now()}`,
                    },
                };

                try {
                    // 1) Actualizar biblioteca en memoria (opcional, ayuda a la UI)
                    setCourseData?.((prev) => {
                        const list = Array.isArray(prev?.courses) ? [...prev.courses] : [];
                        // Intentar buscar por id o id_local para evitar colisiones
                        let ix = -1;
                        if (normalized.course.id) {
                            ix = list.findIndex((it) => it?.course?.id === normalized.course.id);
                        }
                        if (ix < 0 && normalized.course.id_local) {
                            ix = list.findIndex(
                                (it) => String(it?.course?.id_local) === String(normalized.course.id_local)
                            );
                        }

                        if (ix >= 0) {
                            list[ix] = normalized;
                        } else {
                            list.push(normalized);
                        }
                        return { ...(prev ?? {}), courses: list };
                    });

                    // 2) Actualizar takeoff (formData.courses del padre)
                    if (setParentFormData) {
                        setParentFormData((prev) => {
                            if (!prev) return prev;
                            const nextCourses = Array.isArray(prev.courses) ? [...prev.courses] : [];

                            let idx = -1;
                            if (normalized.course.id) {
                                idx = nextCourses.findIndex(c => String(c.id) === String(normalized.course.id));
                            }
                            if (idx < 0 && normalized.course.id_local) {
                                idx = nextCourses.findIndex(c => String(c.id_local) === String(normalized.course.id_local));
                            }

                            if (idx >= 0) {
                                nextCourses[idx] = normalized.course;
                            } else {
                                nextCourses.push(normalized.course);
                            }
                            return { ...prev, courses: nextCourses };
                        });
                    }

                    setFormData(initialValues);
                    setDisplay(false);
                    uiToast.success("Saved only in this takeoff");
                } catch (err) {
                    console.error("Error updating parent form:", err);
                    uiToast.error("Error updating the takeoff locally.");
                }
                return;
            }

            // ✅ SI NO ESTÁ EN USO -> GUARDADO GLOBAL (API)
            // id_local para crear (si no existe)
            const idLocal = (formData?.id_local != null && formData.id_local !== "")
                ? formData.id_local
                : (typeof crypto.randomUUID === "function"
                    ? crypto.randomUUID()
                    : `loc_${Date.now()}`);

            const payload = {
                id_local: idLocal,
                data: formData,
            };

            const url = isUpdate ? `/api/course-bands/${formData.id}` : `/api/course-bands`;
            const method = isUpdate ? "PUT" : "POST";

            const res = await fetch(url, {
                method,
                headers: {
                    "Content-Type": "application/json",
                    Accept: "application/json",
                    Authorization: `Bearer ${routes.__token}`,
                },
                body: JSON.stringify(payload),
            });

            if (!res.ok) {
                const err = await res.json().catch(() => ({}));
                throw new Error(err?.message || `Error HTTP ${res.status}`);
            }

            const saved = await res.json();

            // Intenta obtener el ID devuelto por el backend
            const savedRow = saved?.result?.items?.[0] || null;
            const savedId = saved?.id ?? savedRow?.id ?? formData?.id ?? null;
            const savedLocal = savedRow?.id_local ?? payload.id_local;

            // Si el backend te devuelve el objeto "data" como string, decodifícalo
            let serverData = saved?.data ?? formData;
            if (typeof serverData === "string") {
                try { serverData = JSON.parse(serverData); } catch { }
            }

            // Normalizamos lo que la tabla necesita
            const normalized = {
                course: {
                    ...(serverData || formData),
                    id: savedId,
                    id_local: savedLocal,
                },
            };

            // ====== UPDATE OPTIMISTA (funciona en create y edit) ======
            setCourseData?.((prev) => {
                const list = Array.isArray(prev?.courses) ? [...prev.courses] : [];

                // 1) intenta reemplazar por id
                let ix = -1;
                if (normalized.course?.id != null) {
                    ix = list.findIndex((it) => it?.course?.id === normalized.course.id);
                }
                // 2) si no, intenta por id_local
                if (ix < 0 && normalized.course?.id_local != null) {
                    ix = list.findIndex(
                        (it) => String(it?.course?.id_local) === String(normalized.course.id_local)
                    );
                }

                if (ix >= 0) {
                    list[ix] = normalized;             // replace
                } else if (Number.isInteger(fila) && fila >= 0 && fila < list.length) {
                    list[fila] = normalized;           // reemplaza por fila (si venía de edición en línea)
                } else {
                    list.unshift(normalized);          // inserta al inicio (CREATE)
                }

                return { ...(prev ?? {}), courses: list };
            });

            // Limpia y cierra modal
            setFormData(initialValues);
            setDisplay(false);

            toast.success(
                isUpdate ? "Band updated successfully" : "Band created successfully",
                { ...toastOptions }
            );
        } catch (error) {
            console.error(error);
            toast.error(`Could not save the band: ${error.message || error}`, { ...toastOptions });
        }
    };
