    const CalculateData = async (updatedFormData) => {
        try {
            console.log("formDataPadre", formDataPadre);
            if (!formDataPadre) return;

            // Asegurar que courses sea un array
            const currentCourses = Array.isArray(formDataPadre.courses) ? [...formDataPadre.courses] : [];

            // Encontrar el índice correcto del curso que estamos editando
            let targetIdx = -1;
            if (updatedFormData.id) {
                targetIdx = currentCourses.findIndex(c => String(c.id) === String(updatedFormData.id));
            }
            if (targetIdx < 0 && updatedFormData.id_local) {
                targetIdx = currentCourses.findIndex(c => String(c.id_local) === String(updatedFormData.id_local));
            }

            if (targetIdx >= 0) {
                currentCourses[targetIdx] = updatedFormData;
            } else if (Number.isInteger(rowCount) && rowCount >= 0) {
                currentCourses[rowCount] = updatedFormData;
                targetIdx = rowCount;
            } else {
                currentCourses.push(updatedFormData);
                targetIdx = currentCourses.length - 1;
            }

            const activePadre = { ...formDataPadre, courses: currentCourses };

            const dataToSend = {
                template_name: activePadre.name,
                trade_name: activePadre.trade,
                formData: activePadre,
                projectId: projectId,
                type: "length",
            };

            const response = await fetch(`/api/CalculateData`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${routes.__token}`,
                },
                body: JSON.stringify(dataToSend),
            }).catch(function (error) {
                console.log('Request failed', error);
                throw error;
            });

            const data = await response.json();
            if (data.status === 200) {
                // Actualizar el formData actual con los resultados del curso correspondiente
                if (data.resultado && Array.isArray(data.resultado.courses) && data.resultado.courses[targetIdx]) {
                    setFormData(data.resultado.courses[targetIdx]);
                }
            } else if (data.status === 400) {
                toast.error("Calculation error", { ...toastOptions });
                console.log(data.resultado);
            }
        } catch (err) {
            console.error("CalculateData Error:", err);
            // toast.error("Error procesando cálculos.");
        }
    };








