import React, { useEffect, useState, useCallback, useRef } from "react";
import { createPortal } from "react-dom";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import { projectId } from "../Constants";

function BulkReportsPopup({ setDisplay, pathname }) {
  const [bulkLoading, setBulkLoading] = useState(false);
  const [bulkReports, setBulkReports] = useState([]);
  const [bulkError, setBulkError] = useState("");
  const [printing, setPrinting] = useState(false);
  const [reportColumns, setReportColumns] = useState([]);
  const [visibleColumns, setVisibleColumns] = useState({});

  const reportRef = useRef(null);

  const fetchBulkReports = useCallback(async () => {
    try {
      setBulkError("");
      setBulkLoading(true);
      setBulkReports([]);

      if (!pathname) {
        setBulkError("Missing path");
        setBulkLoading(false);
        return;
      }

      const payload = { path: pathname, projectId };

      const resp = await fetch("/api/takeoffs/reports/bulk", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        // Si tu auth es por cookie/sanctum, descomenta:
        // credentials: "include",
        body: JSON.stringify(payload),
      });

      const json = await resp.json().catch(() => null);

      if (!resp.ok || !json?.ok) {
        setBulkError(json?.message || "Error generating sheet reports");
        setBulkLoading(false);
        return;
      }

      setBulkReports(Array.isArray(json.reports) ? json.reports : []);
      setBulkLoading(false);
    } catch (e) {
      setBulkError(e?.message || "Unexpected error");
      setBulkLoading(false);
    }
  }, [pathname]);
 
  useEffect(() => {
    fetchBulkReports();
  }, [fetchBulkReports]);

  useEffect(() => {
    if (!bulkReports.length) {
      setReportColumns([]);
      setVisibleColumns({});
      return;
    }

    setTimeout(() => {
      if (!reportRef.current) return;

      const firstTable = reportRef.current.querySelector(".xeon-table");
      if (!firstTable) return;

      const headers = Array.from(firstTable.querySelectorAll("thead th")).map(
        (th, index) => ({
          index: index + 1,
          label: th.innerText.trim() || `Column ${index + 1}`,
        })
      );

      const initialVisible = {};

      headers.forEach((column) => {
        initialVisible[column.index] = true;
      });

      setReportColumns(headers);
      setVisibleColumns(initialVisible);
    }, 100);
  }, [bulkReports]);

  const toggleAllColumns = (checked) => {
    const updatedColumns = {};

    reportColumns.forEach((column) => {
      updatedColumns[column.index] = checked;
    });

    setVisibleColumns(updatedColumns);
  };

  const toggleColumn = (columnIndex, checked) => {
    setVisibleColumns((previousColumns) => ({
      ...previousColumns,
      [columnIndex]: checked,
    }));
  };

  const selectedReportColumns = reportColumns
    .filter((column) => visibleColumns[column.index] !== false)
    .map((column) => column.index);

  const applyColumnVisibilityToTables = useCallback(() => {
    if (!reportRef.current) return;
    if (!reportColumns.length) return;

    const tables = Array.from(reportRef.current.querySelectorAll(".xeon-table"));

    tables.forEach((table) => {
      const rows = Array.from(table.querySelectorAll("tr"));

      rows.forEach((row) => {
        let realColumnIndex = 1;
        const cells = Array.from(row.children).filter((cell) => {
          return cell.tagName === "TD" || cell.tagName === "TH";
        });

        cells.forEach((cell) => {
          if (!cell.dataset.originalColspan) {
            cell.dataset.originalColspan = cell.getAttribute("colspan") || "1";
          }

          const originalColspan = parseInt(cell.dataset.originalColspan, 10) || 1;
          const coveredColumns = [];

          for (let i = 0; i < originalColspan; i++) {
            coveredColumns.push(realColumnIndex + i);
          }

          const visibleCoveredColumns = coveredColumns.filter((columnIndex) => {
            return visibleColumns[columnIndex] !== false;
          });

          if (visibleCoveredColumns.length === 0) {
            cell.style.display = "none";
          } else {
            cell.style.display = "";
            cell.setAttribute("colspan", visibleCoveredColumns.length);
          }

          realColumnIndex += originalColspan;
        });
      });
    });
  }, [reportColumns, visibleColumns]);

  useEffect(() => {
    applyColumnVisibilityToTables();
  }, [applyColumnVisibilityToTables]);

  const handleClose = () => setDisplay(false);

  // ✅ PDF igualito al ReportePopup, pero expandiendo TODOS los .xeon-table-wrap
  const handlePrintPdf = async () => {
    if (printing) return;
    if (!reportRef.current) return;
    if (bulkLoading) return;
    if (!bulkReports.length) return;

    const root = reportRef.current;

    // buscamos TODOS los contenedores con overflow (tu .xeon-table-wrap)
    const scrollWraps = Array.from(root.querySelectorAll(".xeon-table-wrap"));

    // guardamos estilos para restaurar
    const prevList = scrollWraps.map((el) => ({
      el,
      overflow: el.style.overflow,
      width: el.style.width,
      height: el.style.height,
      maxHeight: el.style.maxHeight,
    }));

    try {
      setPrinting(true);

      // ✅ expandir cada tabla scrolleable para capturar TODO
      scrollWraps.forEach((el) => {
        const fullW = el.scrollWidth;
        const fullH = el.scrollHeight;

        el.style.overflow = "visible";
        el.style.width = fullW + "px";
        el.style.height = fullH + "px";
        el.style.maxHeight = "none";
        el.scrollTop = 0;
      });

      const canvas = await html2canvas(root, {
        scale: 2,
        useCORS: true,
        backgroundColor: "#ffffff",
        scrollX: 0,
        scrollY: -window.scrollY,
        windowWidth: document.documentElement.scrollWidth,
      });

      const imgData = canvas.toDataURL("image/png");

      // ✅ landscape letter para tablas anchas
      const pdf = new jsPDF({
        orientation: "landscape",
        unit: "pt",
        format: "letter",
      });

      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();

      const imgWidth = pageWidth;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      let position = 0;
      let heightLeft = imgHeight;

      pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      while (heightLeft > 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      const blobUrl = pdf.output("bloburl");
      const win = window.open(blobUrl, "_blank");
      if (win) {
        win.onload = () => {
          try {
            win.print();
          } catch (e) {}
        };
      }
    } catch (e) {
      console.error("Error generating PDF:", e);
    } finally {
      // ✅ restaurar estilos
      prevList.forEach((p) => {
        p.el.style.overflow = p.overflow;
        p.el.style.width = p.width;
        p.el.style.height = p.height;
        p.el.style.maxHeight = p.maxHeight;
      });

      setPrinting(false);
    }
  };

  const handleExportExcel = async () => {
    if (bulkLoading) return;

    const resp = await fetch("/api/takeoffs/reports/bulk-excel", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: pathname,
        projectId,
        selected_columns: selectedReportColumns,
      }),
    });

    if (!resp.ok) {
      alert("Error generating Excel");
      return;
    }

    const blob = await resp.blob();
    const url = window.URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = "sheet-reports.xlsx";
    document.body.appendChild(a);
    a.click();
    a.remove();

    window.URL.revokeObjectURL(url);
  };

  return createPortal(
    <div
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 999999,
        background: "rgba(0,0,0,0.35)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 20,
      }}
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) handleClose();
      }}
    >
      <div
        style={{
          width: "min(1150px, 96vw)",
          maxHeight: "92vh",
          background: "#fff",
          borderRadius: 10,
          overflow: "hidden",
          boxShadow: "0 20px 60px rgba(0,0,0,0.35)",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {/* Header con mismos estilos que ReportePopup */}
        <div
          style={{
            padding: "10px 14px",
            borderBottom: "1px solid #eaeaea",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 10,
          }}
        >
          <div>
            <div style={{ fontWeight: 800 }}>Sheet Reports</div>
            <div style={{ fontSize: 12, opacity: 0.75 }}>
              {bulkLoading ? "Generating..." : `${bulkReports.length} report(s)`}
            </div>
          </div>

          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <button
              type="button"
              onClick={handleExportExcel}
              disabled={bulkLoading || bulkReports.length === 0}
              style={{
                padding: "6px 10px",
                borderRadius: 6,
                border: "1px solid #ddd",
                background: "#fff",
                cursor: "pointer",
              }}
            >
              Export Excel
            </button>

            <button
              type="button"
              onClick={handleClose}
              style={{
                padding: "6px 10px",
                borderRadius: 6,
                border: "1px solid #ddd",
                background: "#fff",
                cursor: "pointer",
              }}
            >
              Back
            </button>
          </div>
        </div>

        {/* Body */}
        <div style={{ padding: 14, overflow: "auto", background: "#fafafa" }}>
          {bulkError ? <div className="alert alert-danger">{bulkError}</div> : null}
          {bulkLoading ? <div style={{ padding: 12 }}>Loading...</div> : null}

          {!bulkLoading && bulkReports.length === 0 && !bulkError ? (
            <div style={{ padding: 12 }}>No takeoffs found for this sheet.</div>
          ) : null}

          {reportColumns.length > 0 && (
            <div
              style={{
                marginBottom: 14,
                padding: 14,
                border: "1px solid #dbe3ea",
                borderRadius: 12,
                background: "linear-gradient(180deg, #ffffff 0%, #f8fafc 100%)",
                boxShadow: "0 6px 18px rgba(15, 23, 42, 0.06)",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: 12,
                  marginBottom: 12,
                }}
              >
                <div>
                  <div
                    style={{
                      fontWeight: 900,
                      fontSize: 15,
                      color: "#0f172a",
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                    }}
                  >
                    <i className="fas fa-table-columns"></i>
                    Report columns
                  </div>

                  <div style={{ fontSize: 12, color: "#64748b", marginTop: 3 }}>
                    Select the columns you want to show in the report and Excel export.
                  </div>
                </div>

                <label
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: 6,
                    padding: "5px 10px",
                    borderRadius: 7,
                    background: "#eff6ff",
                    border: "1px solid #bfdbfe",
                    color: "#1d4ed8",
                    fontWeight: 700,
                    fontSize: 12,
                    cursor: "pointer",
                    userSelect: "none",
                    whiteSpace: "nowrap",
                    minHeight: 30,
                  }}
                >
                  <input
                    type="checkbox"
                    checked={reportColumns.every(
                      (column) => visibleColumns[column.index] !== false
                    )}
                    onChange={(event) => toggleAllColumns(event.target.checked)}
                    style={{
                      accentColor: "#2563eb",
                      width: 13,
                      height: 13,
                      margin: 0,
                    }}
                  />
                  All
                </label>
              </div>

              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: 6,
                  marginTop: 4,
                }}
              >
                {reportColumns.map((column) => {
                  const isSelected = visibleColumns[column.index] !== false;

                  return (
                    <label
                      key={column.index}
                      style={{
                        display: "inline-flex",
                        alignItems: "center",
                        gap: 5,
                        padding: "4px 8px",
                        borderRadius: 7,
                        border: isSelected
                          ? "1px solid #93c5fd"
                          : "1px solid #e2e8f0",
                        background: isSelected ? "#eff6ff" : "#ffffff",
                        color: isSelected ? "#1d4ed8" : "#475569",
                        fontSize: 11,
                        fontWeight: 600,
                        cursor: "pointer",
                        userSelect: "none",
                        transition: "all .12s ease",
                        lineHeight: 1.1,
                        minHeight: 28,
                      }}
                    >
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={(event) =>
                          toggleColumn(column.index, event.target.checked)
                        }
                        style={{
                          accentColor: "#2563eb",
                          width: 13,
                          height: 13,
                          margin: 0,
                        }}
                      />

                      <span
                        style={{
                          whiteSpace: "nowrap",
                        }}
                      >
                        {column.label}
                      </span>
                    </label>
                  );
                })}
              </div>
            </div>
          )}

          <div ref={reportRef}>
            {!bulkLoading &&
              bulkReports.map((r) => (
                <div
                  key={r.key}
                  style={{
                    background: "#fff",
                    border: "1px solid #e9ecef",
                    borderRadius: 10,
                    marginBottom: 14,
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      padding: "10px 12px",
                      borderBottom: "1px solid #f0f0f0",
                      background: "#fff",
                      fontWeight: 700,
                      fontSize: 13,
                    }}
                  >
                    {r.title}
                  </div>

                  <div style={{ padding: 12 }}>
                    <div dangerouslySetInnerHTML={{ __html: r.html }} />
                  </div>
                </div>
              ))}
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}

export default BulkReportsPopup;
