import { useRef, useState } from "react";
import Draggable from "react-draggable";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";

export default function ReportePopup({
  open,
  title = "Report",
  onClose,
  children,
  enablePdf = true,
}) {
  const reportRef = useRef(null);
  const [printing, setPrinting] = useState(false);

  const handlePrint = async () => {
    if (!enablePdf || printing) return;
    if (!reportRef.current) return;

    const root = reportRef.current;

    // buscamos el contenedor con overflow (tu .xeon-table-wrap)
    const scrollWrap = root.querySelector(".xeon-table-wrap");

    // guardamos estilos para restaurar
    const prev = scrollWrap
      ? {
          overflow: scrollWrap.style.overflow,
          width: scrollWrap.style.width,
          height: scrollWrap.style.height,
          maxHeight: scrollWrap.style.maxHeight,
        }
      : null;

    try {
      setPrinting(true);

      // ✅ expandir el área scrollable para capturar TODO
      if (scrollWrap) {
        const fullW = scrollWrap.scrollWidth;
        const fullH = scrollWrap.scrollHeight;

        scrollWrap.style.overflow = "visible";
        scrollWrap.style.width = fullW + "px";
        scrollWrap.style.height = fullH + "px";
        scrollWrap.style.maxHeight = "none";
      }

      // ✅ también asegúrate de ir al top por si sticky headers
      if (scrollWrap) scrollWrap.scrollTop = 0;

      const canvas = await html2canvas(root, {
        scale: 2,
        useCORS: true,
        backgroundColor: "#ffffff",
        scrollX: 0,
        scrollY: -window.scrollY, // evita offsets raros
        windowWidth: document.documentElement.scrollWidth,
      });

      const imgData = canvas.toDataURL("image/png");

      // ✅ landscape letter para tablas anchas
      const pdf = new jsPDF({
        orientation: "landscape",
        unit: "pt",
        format: "letter",
      });

      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();

      // escala para que quepa al ancho
      const imgWidth = pageWidth;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      let position = 0;
      let heightLeft = imgHeight;

      pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      while (heightLeft > 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      const blobUrl = pdf.output("bloburl");
      const win = window.open(blobUrl, "_blank");
      if (win) {
        win.onload = () => {
          try { win.print(); } catch (e) {}
        };
      }
    } catch (e) {
      console.error("Error generating PDF:", e);
    } finally {
      // ✅ restaurar estilos
      if (scrollWrap && prev) {
        scrollWrap.style.overflow = prev.overflow;
        scrollWrap.style.width = prev.width;
        scrollWrap.style.height = prev.height;
        scrollWrap.style.maxHeight = prev.maxHeight;
      }
      setPrinting(false);
    }
  };

  if (!open) return null;

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 999999,
        background: "rgba(0,0,0,0.35)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 20,
      }}
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose?.();
      }}
    >
      <Draggable handle=".report-popup__header">
        <div
          style={{
            width: "min(1150px, 96vw)",
            maxHeight: "92vh",
            background: "#fff",
            borderRadius: 10,
            overflow: "hidden",
            boxShadow: "0 20px 60px rgba(0,0,0,0.35)",
            display: "flex",
            flexDirection: "column",
          }}
        >
          <div
            className="report-popup__header"
            style={{
              padding: "10px 14px",
              borderBottom: "1px solid #eaeaea",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              cursor: "move",
              gap: 10,
            }}
          >
            <div style={{ fontWeight: 800 }}>{title}</div>

            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>

              <button
                type="button"
                onClick={onClose}
                style={{
                  padding: "6px 10px",
                  borderRadius: 6,
                  border: "1px solid #ddd",
                  background: "#fff",
                  cursor: "pointer",
                }}
              >
                Back
              </button>
            </div>
          </div>

          <div style={{ padding: 14, overflow: "auto" }}>
            <div ref={reportRef}>{children}</div>
          </div>
        </div>
      </Draggable>
    </div>
  );
}
