import { db } from "./db";
import { routes, projectId } from "../Constants";

export async function syncDrawings() {
  try {
    // 1️⃣ Obtener último updated_at local
    const projectRecords = await db.drawings
      .filter((record) => Number(record.project_id) === Number(projectId))
      .toArray();

    const lastRecord = projectRecords.reduce((latest, record) => {
      if (!latest) return record;

      const currentDate = new Date(record.updated_at).getTime();
      const latestDate = new Date(latest.updated_at).getTime();

      return currentDate > latestDate ? record : latest;
    }, null);
    const lastUpdated = lastRecord ? lastRecord.updated_at : "1970-01-01 00:00:00";

    // 2️⃣ Llamar API
    const response = await fetch("/api/pullUpdates/drawings", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${routes.__token}`,
      },
      body: JSON.stringify({
          last_updated_at: lastUpdated,
          project_id: projectId,
      }),
    });

    if (!response.ok) {
      console.error("Error en API:", response.status);
      return;
    }

    const data = await response.json();

    if (!data || !data.records || !data.records.length) {
      console.log("No hay registros nuevos");
      return;
    }

    console.log("Registros recibidos:", data.records.length);

    // 3️⃣ Parsear campos JSON
    let records = data.records
      .filter(r => r && r.id != null && r.path) // seguridad
      .map(r => ({
        ...r,
        scale: typeof r.scale === "string" ? r.scale.replace(/`/g, "") : r.scale,
        area: typeof r.area === "string" ? JSON.parse(r.area) : r.area,
        perimeter: typeof r.perimeter === "string" ? JSON.parse(r.perimeter) : r.perimeter,
        lines: typeof r.line === "string" ? JSON.parse(r.line) : r.line,
        counts: typeof r.counts === "string" ? JSON.parse(r.counts) : r.counts,
        storedLines: typeof r.storedLines === "string" ? JSON.parse(r.storedLines) : r.storedLines,
        storedRectangles: typeof r.storedRectangles === "string" ? JSON.parse(r.storedRectangles) : r.storedRectangles,
        storedEllipses: typeof r.storedEllipses === "string" ? JSON.parse(r.storedEllipses) : r.storedEllipses,
        storedTexts: typeof r.storedTexts === "string" ? JSON.parse(r.storedTexts) : r.storedTexts,
        storedPhotos: typeof r.storedPhotos === "string" ? JSON.parse(r.storedPhotos) : r.storedPhotos,
        storedStickyNotes: typeof r.storedStickyNotes === "string" ? JSON.parse(r.storedStickyNotes) : r.storedStickyNotes,
        storedHyperLinks: typeof r.storedHyperLinks === "string" ? JSON.parse(r.storedHyperLinks) : r.storedHyperLinks,
      }));

    // 4️⃣ Deduplicar por path quedándonos con el más nuevo
    records = dedupeByPathKeepNewest(records);

    console.log("Después de dedupe:", records.length);

    // 5️⃣ Guardar en Dexie
    await db.drawings.bulkPut(records);

    console.log("✅ Drawings sincronizados:", records.length);

  } catch (error) {
    console.error("Error en syncDrawings:", error);
  }
}

function dedupeByPathKeepNewest(records) {
  const map = new Map();

  for (const record of records) {
    if (!record?.path) continue;

    const existing = map.get(record.path);

    if (!existing || record.updated_at >= existing.updated_at) {
      map.set(record.path, record);
    }
  }

  return Array.from(map.values());
}