import ScaleButton from "./ScaleButton";
import ScreenToggle from "./ScreenToggle";
import React, { useState, useEffect } from "react";
import useSignal from "../hooks/signals";
import { useLocation } from "react-router-dom";
import { useLiveQuery } from 'dexie-react-hooks'
import { db } from "../database/db";
import CountPopup from "./CountPopup";
import Details from "./Details";
import LengthPopup from "./LengthPopup";
import LengthPopupDraw from "./LengthPopupDraw";
import LinePopup from "./LinePopup";
import AreaPopup from "./AreaPopup";
import AreaPopupDraw from "./AreaPopupDraw";
import PerimeterPopup from "./PerimeterPopup";
import PerimeterPopupDraw from "./PerimeterPopupDraw";
import OpeningPopup from "./OpeningPopup";
import OpeningPopupDraw from "./OpeningPopupDraw";
import OvalPopupDraw from "./OvalPopupDraw";
import LineAnnotationPopupDraw from "./LineAnnotationPopupDraw";
// import CanvasComponent from "./CanvasComponent";
import GenerateProposalPopup from "./GenerateProposalPopup";
import MaterialQoutePopup from "./MaterialQoutePopup";
import Dexie from "dexie";
import "../pages_css.css";
import "../Css/project-plan.css";
import CreateProjectPopup from "./CreateProjectPopup";
//import ProjectButton from "./ProjectButton";
//import LogoutButton from "./LogoutButton";
import ProjectDetails from "./ProjectDetails";
import { routes } from "../Constants";
import BulkReportsPopup from "./BulkReportsPopup";
import RectanglePopupDraw from "./RectanglePopupDraw";
import WorkspacePanel from "./WorkspacePanel";

function MenuBar() {
    // const [active, setActive] = useState('')
    const [countDisplay, setCountDisplay] = useState(false);
    const [openLengthPopup, setOpenLengthPopup] = useState(false);
    const [openLengthPopupDraw, setOpenLengthPopupDraw] = useState(false);
    const [openAreaPopupDraw, setOpenAreaPopupDraw] = useState(false);
    const [openAreaPopup, setOpenAreaPopup] = useState(false);
    const [openPerimeterPopup, setOpenPerimeterPopup] = useState(false);
    const [openPerimeterPopupDraw, setOpenPerimeterPopupDraw] = useState(false);
    const [openCountPopup, setOpenCountPopup] = useState(false);
    const [openGenerateProposalPopup, setOpenGenerateProposalPopup] = useState(false);
    const [openMaterialQoutePopup, setOpenMaterialQoutePopup] = useState(false);
    // const [showCanvasComponent, setShowCanvasComponent] = useState(false);
    const [showHyperlinkModal, setShowHyperlinkModal] = useState(false);
    const [isCheckbox1Checked, setIsCheckbox1Checked] = useState(true);
    const [isCheckbox2Checked, setIsCheckbox2Checked] = useState(false);
    const [openCreateProject, setOpenCreateProject] = useState(false);
    const [lineDisplay, setLineDisplay] = useState(false)
    const signal = useSignal();
    const [openOpeningPopup, setOpenOpeningPopup] = useState(false);
    const [openOpeningPopupDraw, setOpenOpeningPopupDraw] = useState(false);
    const [openBulkPopup, setOpenBulkPopup] = useState(false);
    const [openOvalPopup, setOpenOvalPopup] = useState(false);
    const [openLineAnnotationPopup, setOpenLineAnnotationPopup] = useState(false);
    const [openRectanglePopup, setOpenRectanglePopup] = useState(false);
    const [showFloatingToolbar, setShowFloatingToolbar] = useState(true);
    const [showWorkspace, setShowWorkspace] = useState(false);
    const [openDropdown, setOpenDropdown] = useState(null);
    // const handleButtonClick = () => {
    //     setShowCanvasComponent(!showCanvasComponent);
    //   };
    const assetPath = routes.assetPath;

    const location = useLocation();
    const pathname = location?.pathname ?? "";

    const currentProjectId = React.useMemo(() => {
        const browserPath = window.location.pathname || pathname;

        const match = browserPath.match(/\/(\d+)\/application(?:\/|$)/);

        if (match) {
            return Number(match[1]);
        }

        const numericSegment = browserPath
            .split("/")
            .filter(Boolean)
            .find((segment) => /^\d+$/.test(segment));

        return numericSegment
            ? Number(numericSegment)
            : null;
    }, [pathname]);

    const drawingData = useLiveQuery(async () => {
        if (!pathname) return null;
        const row = await db.drawings.where({ path: pathname }).first();
        return row || null;
    }, [pathname]);

    // ✅ Para UX: si no hay takeoffs, podrías deshabilitar el botón
    const hasTakeoffs =
        (Array.isArray(drawingData?.lines) && drawingData.lines.length > 0) ||
        (Array.isArray(drawingData?.areas) && drawingData.areas.length > 0) ||
        (Array.isArray(drawingData?.perimeters) && drawingData.perimeters.length > 0);

    var dB = new Dexie('takeoff');
    dB.version(1).stores({
        measurements: 'takeoff, name',
    });
    // useEffect(() => {
    //     if (active !== '') {
    //         try {
    //             signal.emit('takeoff', { ...active })
    //         } catch (e) {
    //             console.log(e)
    //         }
    //     }
    // }, [active, signal])
    useEffect(() => {
            // Set the initial state when the modal is opened
            if (showHyperlinkModal) {
                setIsCheckbox1Checked(true);
                setIsCheckbox2Checked(false);
            }
        }, [showHyperlinkModal]);
        useEffect(() => {
        const closeDropdowns = (event) => {
            if (!event.target.closest(".floating-takeoff-toolbar .dropdown")) {
                setOpenDropdown(null);
            }
        };

        const closeWithEscape = (event) => {
            if (event.key === "Escape") {
                setOpenDropdown(null);
            }
        };

        document.addEventListener("mousedown", closeDropdowns);
        document.addEventListener("keydown", closeWithEscape);

        return () => {
            document.removeEventListener("mousedown", closeDropdowns);
            document.removeEventListener("keydown", closeWithEscape);
        };
    }, []);
    const toggleDropdown = (name) => {
        setOpenDropdown((current) => current === name ? null : name);
    };

    const runDropdownAction = (action) => {
        setOpenDropdown(null);
        action();
    };
    const handleHyperlinkClick = () => {
        // console.log('function called 2nd time');
        setShowHyperlinkModal(true);
        // if(isCheckbox1Checked){
        // console.log('button is clicked');
        signal.emit('takeoff', { type: 'drawHyperlink1' });
        // }
    };
    const handleCheckbox2Click = () => {
        setIsCheckbox2Checked((prevChecked) => !prevChecked);
        signal.emit('takeoff', { type: 'drawHyperlink2' });
        setShowHyperlinkModal(false);
        setIsCheckbox1Checked(false);
        setIsCheckbox2Checked(false);
    };
    const handleLengthTakeoff = async () => {
        await dB.open();
        const dbData = await dB.measurements.toArray();
        if (dbData) {
            await dB.measurements.clear();
        }
        const lineInput = window.prompt('Enter Length Measurement Name:', '');
        const lengthName = lineInput ? lineInput : 'Line Takeoff';
        dB.open();
        dB.measurements.add({ name: lengthName, takeoff: 'length' });
        signal.emit('takeoff', { type: 'length' });
    }
    const startLineMeasurement = () => {
        // if (!data?.scale.length) {
        //     startScale()
        //     return
        // }
        setLineDisplay(true)
    }
    const handleAreaTakeoff = async () => {
        await dB.open();
        const dbData = await dB.measurements.toArray();
        if (dbData) {
            await dB.measurements.clear();
        }
        const lineInput = window.prompt('Enter Area Measurement Name:', '');
        const areaName = lineInput ? lineInput : 'Area Takeoff';
        dB.open();
        dB.measurements.add({ name: areaName, takeoff: 'area' });
        signal.emit('takeoff', { type: 'area' });
    }

    const handlePerimeterTakeoff = async () => {
        await dB.open();
        const dbData = await dB.measurements.toArray();
        if (dbData) {
            await dB.measurements.clear();
        }
        const lineInput = window.prompt('Enter Perimeter Measurement Name:', '');
        const perimeterName = lineInput ? lineInput : 'Perimeter Takeoff';
        dB.open();
        dB.measurements.add({ name: perimeterName, takeoff: 'perimeter' });
        signal.emit('takeoff', { type: 'perimeter' });
    }

    const handleCountTakeoff = async () => {
        await dB.open();
        const dbData = await dB.measurements.toArray();
        if (dbData) {
            await dB.measurements.clear();
        }
        const lineInput = window.prompt('Enter Counts Measurement Name:', '');
        const countName = lineInput ? lineInput : 'Count Takeoff';
        dB.open();
        dB.measurements.add({ name: countName, takeoff: 'count' });
        signal.emit('takeoff', { type: 'count' });
    }
    const openSheetReports = () => {
        setOpenBulkPopup(true);
    };
    const handlePhotoAnnotation = () => {
        console.log("PHOTO MENU CLICK");
        signal.emit("takeoff", {
            type: "drawPhoto",
            color: "#2563eb",
        });
    };

    const handleStickyNoteAnnotation = () => {
        signal.emit("takeoff", {
            type: "drawStickyNote",
            color: "#facc15",
        });
    };

    const handleTextAnnotation = () => {
        signal.emit("takeoff", {
            type: "drawText",
            color: "#E914B7",
            fontSize: 24,
        });
    };

    return (
        <div className="top-menu header-bg">
            <ul className="tool-bar">
                <ProjectDetails />
            </ul>

            <button
                type="button"
                className={`floating-toolbar-toggle ${showFloatingToolbar ? "open" : "closed"}`}
                onClick={() => setShowFloatingToolbar(!showFloatingToolbar)}
                title={showFloatingToolbar ? "Hide tools" : "Show tools"}
            >
                <i className={`fa-light ${showFloatingToolbar ? "fa-chevron-up" : "fa-chevron-down"}`}></i>
            </button>

            {showFloatingToolbar && (
                <ul className="floating-takeoff-toolbar">
                    <li data-tooltip="Rotate" className="dropdown w-65px b-right" tabIndex="0" onClick={() => signal.emit("rotate")}>
                        <div className="text-center">
                            <i className="fa-light fa-rotate"></i>
                            <span className="d-block text-12">ROTATE</span>
                        </div>
                    </li>

                    <li
                        data-tooltip="Length Takeoff"
                        className={`dropdown w-65px b-right ${openDropdown === "length" ? "show" : ""}`}
                    >
                        <div
                            className="text-center"
                            onClick={() => toggleDropdown("length")}
                        >
                            <i className="fa-light fa-arrows-left-right"></i>
                            <span className="d-block text-12">LENGTH</span>
                        </div>
                        <ul className={`dropdown-menu ${openDropdown === "length" ? "show" : ""}`}>
                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenLengthPopup(true))
                                    }
                                >
                                    Create Template
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenLengthPopupDraw(true))
                                    }
                                >
                                    Create Takeoff
                                </label>
                            </li>
                        </ul>
                    </li>

                    <li
                        data-tooltip="Area Takeoff"
                        className={`dropdown w-65px b-right ${openDropdown === "area" ? "show" : ""}`}
                    >
                        <div
                            className="text-center"
                            onClick={() => toggleDropdown("area")}
                        >
                            <i className="fa-solid fa-square"></i>
                            <span className="d-block text-12">AREA</span>
                        </div>

                        <ul className={`dropdown-menu ${openDropdown === "area" ? "show" : ""}`}>
                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenAreaPopup(true))
                                    }
                                >
                                    Create Template
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenAreaPopupDraw(true))
                                    }
                                >
                                    Create Takeoff
                                </label>
                            </li>
                        </ul>
                    </li>

                    <li
                        data-tooltip="Perimeter Takeoff"
                        className={`dropdown w-80px b-right ${openDropdown === "perimeter" ? "show" : ""}`}
                    >
                        <div
                            className="text-center"
                            onClick={() => toggleDropdown("perimeter")}
                        >
                            <i className="fa-light fa-square"></i>
                            <span className="d-block text-12">PERIMETER</span>
                        </div>

                        <ul className={`dropdown-menu ${openDropdown === "perimeter" ? "show" : ""}`}>
                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenPerimeterPopup(true))
                                    }
                                >
                                    Create Template
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenPerimeterPopupDraw(true))
                                    }
                                >
                                    Create Takeoff
                                </label>
                            </li>
                        </ul>
                    </li>

                    <li
                        data-tooltip="Counts"
                        className={`dropdown w-65px b-right ${openDropdown === "counts" ? "show" : ""}`}
                    >
                        <div
                            className="text-center"
                            onClick={() => toggleDropdown("counts")}
                        >
                            <i className="fa-light fa-00"></i>
                            <span className="d-block text-12">Counts</span>
                        </div>

                        <ul className={`dropdown-menu ${openDropdown === "counts" ? "show" : ""}`}>
                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenCountPopup(true))
                                    }
                                >
                                    Full Takeoff
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(handleCountTakeoff)
                                    }
                                >
                                    Only Measurement
                                </label>
                            </li>
                        </ul>
                    </li>

                    <li
                        data-tooltip="Annotations"
                        className={`dropdown w-100px b-right ${openDropdown === "annotations" ? "show" : ""}`}
                    >
                        <div
                            className="text-center"
                            onClick={() => toggleDropdown("annotations")}
                        >
                            <i className="fa-light fa-shapes"></i>
                            <span className="d-block text-12">ANNOTATIONS</span>
                        </div>

                        <ul className={`dropdown-menu ${openDropdown === "annotations" ? "show" : ""}`}>
                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenOvalPopup(true))
                                    }
                                >
                                    <i className="fa-light fa-circle mr" /> Oval
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenRectanglePopup(true))
                                    }
                                >
                                    <i className="fa-light fa-rectangle mr" /> Rectangle
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenLineAnnotationPopup(true))
                                    }
                                >
                                    <i className="fa-light fa-arrows-left-right mr" /> Line
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(handlePhotoAnnotation)
                                    }
                                >
                                    <i className="fa-light fa-image mr" /> Photo
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(handleStickyNoteAnnotation)
                                    }
                                >
                                    <i className="fa-solid fa-note-sticky mr" /> Sticky Note
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(handleTextAnnotation)
                                    }
                                >
                                    <i className="fa-light fa-text mr" /> Text
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(handleHyperlinkClick)
                                    }
                                >
                                    <i className="fa-light fa-link mr" /> Hyperlink
                                </label>
                            </li>
                        </ul>
                    </li>

                    <li
                        data-tooltip="Openings"
                        className={`dropdown w-65px b-right ${openDropdown === "openings" ? "show" : ""}`}
                    >
                        <div
                            className="text-center"
                            onClick={() => toggleDropdown("openings")}
                        >
                            <i className="fa-light fa-window-maximize"></i>
                            <span className="d-block text-12">OPENINGS</span>
                        </div>

                        <ul className={`dropdown-menu ${openDropdown === "openings" ? "show" : ""}`}>
                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenOpeningPopup(true))
                                    }
                                >
                                    Create Template
                                </label>
                            </li>

                            <li>
                                <label
                                    className="custom-label"
                                    onClick={() =>
                                        runDropdownAction(() => setOpenOpeningPopupDraw(true))
                                    }
                                >
                                    Create Takeoff
                                </label>
                            </li>
                        </ul>
                    </li>
                </ul>
            )}
            <ul className="tool-bar ml-auto top-right-actions">
                <li className="top-scale-wrapper">
                    <ScaleButton />
                </li>
                {/*<--li data-tooltip="Print" className="top-icon-btn" tabIndex="0" onClick={() => window.print()}>
                    <div className="text-center text-white"><i className="fa-light fa-print"></i></div>
                </li>*/}
                <li data-tooltip="Sheet Reports" className="top-icon-btn" tabIndex="0" onClick={openSheetReports}>
                    <div className="text-center text-white"><i className="fas fa-layer-group"></i></div>
                </li>
                <li
                    data-tooltip="Workspace"
                    className={`top-icon-btn ${
                        showWorkspace ? "active" : ""
                    }`}
                    tabIndex="0"
                    onClick={() => setShowWorkspace(true)}
                >
                    <div className="text-center text-white">
                        <i className="fa-light fa-cube"></i>
                    </div>
                </li>
                <ScreenToggle />
                {countDisplay ? <CountPopup setDisplay={setCountDisplay} /> : <></>}
            </ul>
            {/* {showCanvasComponent && <CanvasComponent />}  */}

            {openLengthPopup && (
                <LengthPopup
                    setDisplay={(isOpen) => setOpenLengthPopup(isOpen)}
                    takeoff={{ mode: "create" }}
                />
            )}

            {openLengthPopupDraw && (
                <LengthPopupDraw
                    setDisplay={(isOpen) => setOpenLengthPopupDraw(isOpen)}
                />
            )}
            {openAreaPopup && (
                <AreaPopup
                    setDisplay={(isOpen) => setOpenAreaPopup(isOpen)}
                    takeoff={{ mode: "create" }}
                />
            )}
            {openAreaPopupDraw && (
                <AreaPopupDraw
                    setDisplay={(isOpen) => setOpenAreaPopupDraw(isOpen)}
                />
            )}
            {openPerimeterPopup && (
                <PerimeterPopup
                    setDisplay={(isOpen) => setOpenPerimeterPopup(isOpen)}
                    takeoff={{ mode: "create" }}
                />
            )}
            {openPerimeterPopupDraw && (
                <PerimeterPopupDraw
                    setDisplay={(isOpen) => setOpenPerimeterPopupDraw(isOpen)}
                />
            )}
            {openCountPopup && (
                <CountPopup
                    setDisplay={(isOpen) => setOpenCountPopup(isOpen)}
                />
            )}
            {openGenerateProposalPopup && (
                <GenerateProposalPopup
                    setDisplay={(isOpen) => setOpenGenerateProposalPopup(isOpen)}
                />
            )}
            {openMaterialQoutePopup && (
                <MaterialQoutePopup
                    setDisplay={(isOpen) => setOpenMaterialQoutePopup(isOpen)}
                />
            )}
            {/* Render the HyperlinkModal when showHyperlinkModal is true */}
            {showHyperlinkModal && (
                <div
                    className="modal-overlay top-left popup-style"
                >
                    <div className="modal-content hyperlink-modal">
                        <button className="close-button" onClick={() => setShowHyperlinkModal(false)}>
                            X
                        </button>
                        <h3>Add Hyperlink</h3>
                        <h4>Hint</h4>
                        <p>
                            Click to add hyperlink, open second file and click second checkbox and click on file
                        </p>
                        <div className="checkbox-style">
                            <label>First File Select</label>
                            <input
                                type="checkbox"
                                checked={isCheckbox1Checked}
                                onChange={() => setIsCheckbox1Checked(!isCheckbox1Checked)}
                            />
                        </div>
                        <div className="checkbox-style">
                            <label>Second File Select</label>
                            <input
                                type="checkbox"
                                checked={isCheckbox2Checked}
                                onChange={() => setIsCheckbox2Checked(!isCheckbox2Checked)}
                                onClick={handleCheckbox2Click}
                            />
                        </div>
                        {/* <div className="checkbox-style">
                             <button className="popup-submit-btn" onClick={handleSubmit}>Add Hyperlink</button>
                             <button className="popup-cancel-btn"  onClick={() => setShowHyperlinkModal(false)}>Cancel</button>
                         </div> */}
                    </div>
                </div>
            )}
            {/* Conditionally render the ProjectMeasurement component */}
            {/* {openCreateProject && <CreateProjectPopup />} */}
            {openCreateProject && (
                <CreateProjectPopup
                    setDisplay={(isOpen) => setOpenCreateProject(isOpen)}
                />
            )}
            {/* {lineDisplay ? <LinePopup setDisplay={setLineDisplay} /> : <></>} */}
            {/* Popup para "Openings" */}
            {openOpeningPopup && (
                <OpeningPopup
                    setDisplay={(isOpen) => setOpenOpeningPopup(isOpen)}
                    takeoff={{ mode: "create" }}
                />
            )}
            {openOpeningPopupDraw && (
                <OpeningPopupDraw
                    setDisplay={(isOpen) => setOpenOpeningPopupDraw(isOpen)}
                />
            )}
            {openBulkPopup && (
                <BulkReportsPopup
                    setDisplay={(isOpen) => setOpenBulkPopup(isOpen)}
                    pathname={pathname}
                />
            )}
            {openOvalPopup && (
                <OvalPopupDraw
                    setDisplay={(isOpen) => setOpenOvalPopup(isOpen)}
                />
            )}
            {openLineAnnotationPopup && (
                <LineAnnotationPopupDraw
                    setDisplay={(isOpen) => setOpenLineAnnotationPopup(isOpen)}
                />
            )}
            {openRectanglePopup && (
                <RectanglePopupDraw
                    setDisplay={(isOpen) => setOpenRectanglePopup(isOpen)}
                />
            )}
            <WorkspacePanel
                isOpen={showWorkspace}
                projectId={currentProjectId}
                onClose={() => setShowWorkspace(false)}
                onCreateProject={() => {
                    setShowWorkspace(false);
                    setOpenCreateProject(true);
                }}
            />
        </div>
    )
}
export default MenuBar;
