  const [textColorDraft, setTextColorDraft] = useState("#E914B7");
  const [textFontSizeDraft, setTextFontSizeDraft] = useState(24);

  const [photoPopupOpen, setPhotoPopupOpen] = useState(false);
  const [photoDraftFile, setPhotoDraftFile] = useState(null);
  const [photoDraftPreview, setPhotoDraftPreview] = useState("");
  const [photoDescriptionDraft, setPhotoDescriptionDraft] = useState("");
  const [photoCoordinates, setPhotoCoordinates] = useState(null);

  const [photoViewerOpen, setPhotoViewerOpen] = useState(false);
