  const [stickyHtmlDraft, setStickyHtmlDraft] = useState("");
  const [stickyViewerOpen, setStickyViewerOpen] = useState(false);
  const [stickyViewerData, setStickyViewerData] = useState(null);
  const stickyEditorRef = useRef(null);

  //nuevo
  const [openDrawPopup, setOpenDrawPopup] = useState(false);
