import { db } from "../database/db";
import { useLiveQuery } from "dexie-react-hooks";
import { useLocation } from "react-router-dom";
import { toast } from 'react-toastify';
import { routes } from "../Constants";
function PerimeterRowContext({ details }) {
    const { pathname } = useLocation()
    const data = useLiveQuery(async () => {
        let drawingData = await db.drawings.where({
            path: pathname
        }).first();
        return drawingData;
    }, [pathname])
    const syncToBackend = async (table, record) => {
        try {
        const response = await fetch(`/api/sync/${table}`, {
            method: "POST",
            headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${routes.__token}`,
            },
            body: JSON.stringify(record),
        });
        if (!response.ok) {
            throw new Error("Error sincronizando con backend");
        }
        console.log("Registro sincronizado:", record.id);
        } catch (err) {
        console.error("Error al sincronizar:", err);
        }
    };
    const handleHide = async () => {
        const id_unique_objetivo = String(details?.idUnique ?? "").trim();

        let newperimeter = data?.perimeter.map((item, i) => {
            const id_unique_actual = String(item?.meta?.idUnique ?? "").trim();

            const matches =
                id_unique_objetivo !== ""
                    ? id_unique_actual === id_unique_objetivo
                    : details.groupName
                        ? item.meta?.name === details.groupName
                        : i === details.index;

            if (matches) {
                return { ...item, hidden: true };
            }

            return item;
        });

        await db.drawings.update(data?.id, { perimeter: newperimeter });

        toast.success(
            details.displayName
                ? `Group '${details.displayName}' Hidden!`
                : "Perimeter Hidden Successfully!",
            { ...toastOptions }
        );
    };
    const handleShow = async () => {
        const id_unique_objetivo = String(details?.idUnique ?? "").trim();

        let newperimeter = data?.perimeter.map((item, i) => {
            const id_unique_actual = String(item?.meta?.idUnique ?? "").trim();

            const matches =
                id_unique_objetivo !== ""
                    ? id_unique_actual === id_unique_objetivo
                    : details.groupName
                        ? item.meta?.name === details.groupName
                        : i === details.index;

            if (matches) {
                return { ...item, hidden: false };
            }

            return item;
        });

        await db.drawings.update(data?.id, { perimeter: newperimeter });

        toast.success(
            details.displayName
                ? `Group '${details.displayName}' Shown!`
                : "Perimeter Shown Successfully!",
            { ...toastOptions }
        );
    };
    const handleShowAll = async () => {
        let newperimeter = data?.perimeter.map((item, i) => {
            item.hidden = false
                return item;
        })
        await db.drawings.update(data?.id, { perimeter: newperimeter })
        toast.success('All Perimeters Shown Successfully!', {...toastOptions});
    }
    const handleHideAll = async () => {
        let newperimeter = data?.perimeter.map((item, i) => {
            item.hidden = true
                return item;
        })
        await db.drawings.update(data?.id, { perimeter: newperimeter })
        toast.success('All Perimeters Hided Successfully!', {...toastOptions});
    }
    const handleDelete = async () => {
        const id_unique_objetivo = String(details?.idUnique ?? "").trim();

        await db.drawings.where({ id: data?.id }).modify((drawing) => {
            if (!drawing.perimeter) drawing.perimeter = [];

            drawing.perimeter = drawing.perimeter.filter((item, i) => {
                const id_unique_actual = String(item?.meta?.idUnique ?? "").trim();

                if (id_unique_objetivo !== "") {
                    return id_unique_actual !== id_unique_objetivo;
                }

                if (details.groupName) {
                    return item.meta?.name !== details.groupName;
                }

                return i !== details.index;
            });

            drawing.updated_at = new Date().toISOString();
        });

        const updated = await db.drawings.get(data?.id);

        syncToBackend("drawings", {
            id: updated.id,
            path: updated.path,
            perimeter: updated.perimeter,
            scale: String(updated.scale || ""),
            factor: updated.factor,
            updated_at: updated.updated_at,
        });

        toast.success(
            details.displayName
                ? `Group '${details.displayName}' Deleted!`
                : "Perimeter Deleted Successfully!",
            { ...toastOptions }
        );
    };
    const handleDeleteAll = async () => {
        await db.drawings.where({ id: data?.id }).modify((drawing) => {
            drawing.perimeter = [];
            drawing.updated_at = new Date().toISOString();
        });

        const updated = await db.drawings.get(data?.id);
        syncToBackend("drawings", {
            id: updated.id,
            path: updated.path,
            perimeter: updated.perimeter,
            scale: String(updated.scale || ""),
            factor: updated.factor,
            updated_at: updated.updated_at,
        });
        toast.success('All Perimeters Deleted Successfully!', {...toastOptions});
    }
    const toastOptions = {
        position: "top-right",
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: 0,
      };
    return (
        <ul className="context-menu" style={{ left: `${details.x}px`, top: `${details.y}px` }}>
            <li onClick={handleShow}>

                <i className="fa-light fa-eye"></i> Show Trace
            </li>
            <li onClick={handleShowAll}>
                <i className="fa-light fa-eye"></i> Show All
            </li>
            <li onClick={handleHide}>
                <i className="fa-light fa-eye-slash"></i> Hide Trace
            </li>
            <li onClick={handleHideAll}>
                <i className="fa-light fa-eye-slash"></i> Hide All
            </li>
            <li onClick={handleDelete}>
                <i className="fa-light fa-trash"></i> Delete
            </li>
            <li onClick={handleDeleteAll}>
                <i className="fa-light fa-trash"></i> Delete All
            </li>
        </ul>
    )
}
export default PerimeterRowContext;