// src/utils/uiAlerts.js
import Swal from "sweetalert2";

/**
 * Toast style (top-right), non-blocking
 */
export const uiToast = {
  success: (title, text = "") =>
    Swal.fire({
      toast: true,
      position: "top-end",
      icon: "success",
      title,
      text,
      showConfirmButton: false,
      timer: 2200,
      timerProgressBar: true,
    }),

  warning: (title, text = "") =>
    Swal.fire({
      toast: true,
      position: "top-end",
      icon: "warning",
      title,
      text,
      showConfirmButton: false,
      timer: 2600,
      timerProgressBar: true,
    }),

  error: (title, text = "") =>
    Swal.fire({
      toast: true,
      position: "top-end",
      icon: "error",
      title,
      text,
      showConfirmButton: false,
      timer: 3200,
      timerProgressBar: true,
    }),

  info: (title, text = "") =>
    Swal.fire({
      toast: true,
      position: "top-end",
      icon: "info",
      title,
      text,
      showConfirmButton: false,
      timer: 2400,
      timerProgressBar: true,
    }),
};

/**
 * Blocking modal alerts (like alert())
 */
export const uiAlert = {
  success: (title, text = "") =>
    Swal.fire({ icon: "success", title, text, confirmButtonText: "OK" }),

  warning: (title, text = "") =>
    Swal.fire({ icon: "warning", title, text, confirmButtonText: "OK" }),

  error: (title, text = "") =>
    Swal.fire({ icon: "error", title, text, confirmButtonText: "OK" }),

  info: (title, text = "") =>
    Swal.fire({ icon: "info", title, text, confirmButtonText: "OK" }),
};

/**
 * Confirm modal (like window.confirm()) -> returns boolean
 */
export const uiConfirm = async ({
  title = "Are you sure?",
  text = "",
  confirmText = "Yes",
  cancelText = "Cancel",
  icon = "question",
}) => {
  const res = await Swal.fire({
    icon,
    title,
    text,
    showCancelButton: true,
    confirmButtonText: confirmText,
    cancelButtonText: cancelText,
    reverseButtons: true,
    allowOutsideClick: false,
  });
  return !!res.isConfirmed;
};
