import { useEffect, useMemo, useState, useRef } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { routes } from "../Constants";
//import { toast } from "react-toastify";
import { projectId } from "../Constants";
import { db } from "../database/db";
import ProcessingOverlay from "./ProcessingOverlay";
import useSignal from "../hooks/signals";
import { uiToast, uiAlert } from "../utils/uiAlerts";
import ReportPopup from "./ReportePopup";
import "../Css/perimeterpop.css";

function PerimeterPopup({ setDisplay, perimeterData, takeoff = null, pathname = "" }) {
  const signal = useSignal();

  const [formDataPerimeter, setFormDataPerimeter] = useState({
    name: "",
    idUnique: "",
    trade: "",
    note: "",
    lineTemplate: "",
    is_global: 0,
    perimeterFields: [
      {
        perimeter: takeoff?.perimetro ?? "",
        material: "",
        materialQty: "",
        totalLf: "",
        totalUnits: "",
      },
    ],
  });

  const [wallMaterials, setWallMaterials] = useState([]);
  const [trade, setTrade] = useState([]);
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingMesagge, setLoadingMesagge] = useState([""]);
  const hasSyncedMaterials = useRef(false);
  const hasSyncedTrade = useRef(false);

  const popupMode = takeoff?.mode ?? (perimeterData != null ? "viewtakeoff" : "create");
  const isCreate = popupMode === "create";
  const isEditTemplate = popupMode === "editTemplate";
  const headerTitle = isCreate
    ? "Create Template Perimeter"
    : isEditTemplate
      ? "Edit Template Perimeter"
      : "View Line Takeoff Perimeter";
  const [userRole, setUserRole] = useState(null);
  const [openReportPopup, setOpenReportPopup] = useState(false);
  const [reportHtml, setReportHtml] = useState("");
  const [reportTitle, setReportTitle] = useState("Perimeter Report");

  // -------------------------
  // Helpers (igual que Length)
  // -------------------------
  const parseOptionDataset = (target) => {
    const opt = target.selectedOptions?.[0];
    if (!opt) return null;

    const rawItem = opt.dataset?.item;
    if (rawItem) {
      try {
        return JSON.parse(rawItem);
      } catch (e) {
        return null;
      }
    }

    const rawMaterial = opt.dataset?.material;
    if (rawMaterial) {
      try {
        return JSON.parse(rawMaterial);
      } catch (e) {
        return null;
      }
    }

    return null;
  };

  useEffect(() => {
    const fetchCurrentUser = async () => {
      try {
        const response = await fetch(`/api/user`, {
          method: "GET",
          headers: {
            Authorization: `Bearer ${routes.__token}`,
            Accept: "application/json",
          },
        });

        const data = await response.json();
        setUserRole(data?.role ?? data?.user?.role ?? null);
      } catch (error) {
        console.error("Error loading current user:", error);
      }
    };

    fetchCurrentUser();
  }, []);

  const normalizeNumberValue = (target) => {
    // Igual que Length: si escriben 0 en input number, que muestre placeholder
    if (target.type === "number" && target.value === "0") return "";
    return target.value;
  };

  const getIdFromMaybeJson = (val) => {
    if (!val) return "";
    if (val === 0 || val === "0") return "";

    if (typeof val === "object" && val.id != null) return String(val.id);

    if (typeof val === "string") {
      try {
        const parsed = JSON.parse(val);
        if (parsed && parsed.id != null) return String(parsed.id);
      } catch (e) { }
    }
    return "";
  };

  const getUniqueIdFromMaybeJson = (val) => {
    if (!val) return "";
    if (val === 0 || val === "0") return "";

    if (typeof val === "object" && val.unique_id != null) return String(val.unique_id);
    if (typeof val === "object" && val.id != null) return String(val.id); // fallback

    if (typeof val === "string") {
      try {
        const parsed = JSON.parse(val);
        if (parsed && parsed.unique_id != null) return String(parsed.unique_id);
        if (parsed && parsed.id != null) return String(parsed.id);
      } catch (e) { }
    }
    return "";
  };

  const fetchPerimeterTemplateById = async (templateId) => {
    if (!templateId) {
      return null;
    }

    try {
      const response = await fetch(
        `/api/get-perimeter-template-by-id/${templateId}`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${routes.__token}`,
            Accept: "application/json",
          },
        }
      );

      const data = await response.json();

      if (!response.ok || data?.status !== 200 || !data?.template) {
        console.warn(
          "Perimeter template not found:",
          templateId,
          data?.message
        );

        return null;
      }

      return data.template;
    } catch (error) {
      console.error(
        "Error loading perimeter template:",
        error
      );

      return null;
    }
  };

  // -------------------------
  // Templates
  // -------------------------
  useEffect(() => {
    const fetchTemplates = async () => {
      try {
        setLoading(true);
        setLoadingMesagge("Processing templates...");
        const response = await fetch(`${routes.templates}?type_template=perimeter`, {
          method: "GET",
          headers: { Authorization: `Bearer ${routes.__token}` },
        });
        const data = await response.json();
        setTemplates(data.template || []);
      } catch (error) {
        console.error("Error cargando templates:", error);
        uiToast.error("Error loading templates");
      } finally {
        setLoading(false);
      }
    };
    fetchTemplates();
  }, []);

  const set_line_template = async (event) => {
    const templateId = event.target.value;

    if (!templateId) {
      setFormDataPerimeter((prev) => ({
        ...prev,
        lineTemplate: "",
      }));

      return;
    }

    try {
      setLoading(true);
      setLoadingMesagge("Loading template...");

      const template =
        await fetchPerimeterTemplateById(templateId);

      if (!template?.local_db) {
        uiToast.error(
          "The selected template could not be loaded."
        );

        return;
      }

      const localDb =
        typeof template.local_db === "string"
          ? JSON.parse(template.local_db)
          : template.local_db;

      const currentPerimeter =
        takeoff?.perimetro ??
        formDataPerimeter.perimeter ??
        formDataPerimeter.perimeterFields?.[0]?.perimeter ??
        "";

      const next = normalizePerimeterFormData({
        ...formDataPerimeter,
        ...localDb,

        lineTemplate: Number(template.id),

        name:
          takeoff?.name ??
          formDataPerimeter.name ??
          localDb.name ??
          "",

        idUnique:
          takeoff?.idUnique ??
          formDataPerimeter.idUnique ??
          localDb.idUnique ??
          "",

        perimeter: currentPerimeter,

        perimeterFields: Array.isArray(
          localDb.perimeterFields
        )
          ? localDb.perimeterFields.map((field) => ({
              ...field,
              perimeter:
                currentPerimeter !== "" &&
                currentPerimeter !== null &&
                currentPerimeter !== undefined
                  ? currentPerimeter
                  : field?.perimeter ?? "",
            }))
          : [
              {
                perimeter: currentPerimeter,
                material: "",
                materialQty: "",
                totalLf: "",
                totalUnits: "",
              },
            ],
      });

      setFormDataPerimeter(next);
      await CalculateData(next);
    } catch (error) {
      console.error(
        "Error selecting perimeter template:",
        error
      );

      uiToast.error(
        "Error loading the selected template."
      );
    } finally {
      setLoading(false);
      setLoadingMesagge("");
    }
  };

  const toJsonString = (v) => {
    if (v === null || v === undefined) return "";
    if (v === "" || v === "null") return "";
    if (typeof v === "string") return v; // ya es JSON string
    try {
      return JSON.stringify(v); // objeto/array -> JSON string
    } catch (e) {
      return "";
    }
  };

  const normalizePerimeterFormData = (fd) => {
    const safe = { ...(fd || {}) };

    // trade siempre como string JSON (si tu backend lo decodea igual)
    if (safe.trade !== undefined) safe.trade = toJsonString(safe.trade);

    // materials dentro de perimeterFields
    safe.perimeterFields = Array.isArray(safe.perimeterFields) ? safe.perimeterFields.map((row) => {
      const r = { ...(row || {}) };
      if (r.material !== undefined) r.material = toJsonString(r.material);
      return r;
    }) : [];

    return safe;
  };

  // -------------------------
  // Change + Blur (igual que Length)
  // -------------------------
  const handleInputChange = (event) => {
    const target = event.target;
    const { name, tagName } = target;

    // ✅ SELECT: guardamos objeto completo desde data-item
    if (tagName === "SELECT") {
      const value = target.value;

      // placeholder
      if (!value) {
        setFormDataPerimeter((prev) => {
          const match = name ? name.match(/\[(\d+)\]\[(\w+)\]/) : null;
          const index = match ? parseInt(match[1], 10) : null;
          const fieldName = match ? match[2] : null;

          if (index != null && fieldName != null) {
            const updatedFields = [...(prev.perimeterFields || [])];
            if (updatedFields[index]) updatedFields[index][fieldName] = null;
            return { ...prev, perimeterFields: updatedFields };
          }

          return { ...prev, [name]: null };
        });
        return;
      }

      const obj = parseOptionDataset(target);

      setFormDataPerimeter((prev) => {
        const match = name ? name.match(/\[(\d+)\]\[(\w+)\]/) : null;
        const index = match ? parseInt(match[1], 10) : null;
        const fieldName = match ? match[2] : null;

        if (index != null && fieldName != null) {
          const updatedFields = [...(prev.perimeterFields || [])];
          if (updatedFields[index]) {
            updatedFields[index][fieldName] = obj ?? null;
          }
          return { ...prev, perimeterFields: updatedFields };
        }

        return { ...prev, [name]: obj ?? null };
      });
      return;
    }

    // ✅ INPUTS normales (text/number/etc)
    const value = normalizeNumberValue(target);

    setFormDataPerimeter((prev) => {
      const match = name ? name.match(/\[(\d+)\]\[(\w+)\]/) : null;
      const index = match ? parseInt(match[1], 10) : null;
      const fieldName = match ? match[2] : null;

      if (index != null && fieldName != null) {
        const updatedFields = [...(prev.perimeterFields || [])];
        if (updatedFields[index]) updatedFields[index][fieldName] = value;
        return { ...prev, perimeterFields: updatedFields };
      }

      return { ...prev, [name]: value };
    });
  };

  const handleInputBlur = (event) => {
    const target = event.target;
    const { name, tagName } = target;

    let finalValue = null;

    if (tagName === "SELECT") {
      const value = target.value;
      if (!value) finalValue = null;
      else finalValue = parseOptionDataset(target);
    } else {
      finalValue = normalizeNumberValue(target);
    }

    setFormDataPerimeter((prev) => {
      const match = name ? name.match(/\[(\d+)\]\[(\w+)\]/) : null;
      const index = match ? parseInt(match[1], 10) : null;
      const fieldName = match ? match[2] : null;

      let updatedFormData = null;

      if (index != null && fieldName != null) {
        const updatedFields = [...(prev.perimeterFields || [])];
        if (updatedFields[index]) updatedFields[index][fieldName] = finalValue;

        updatedFormData = {
          ...prev,
          perimeterFields: updatedFields,
        };
      } else {
        updatedFormData = {
          ...prev,
          [name]: finalValue,
        };
      }

      // ✅ Igual que Length: calcula SIEMPRE con el estado actualizado
      CalculateData(updatedFormData);

      return updatedFormData;
    });
  };

  const normalizePerimeterState = (data = {}) => {
    const perimetro_actual =
      data?.perimeter ??
      data?.PerimeterValue ??
      takeoff?.perimetro ??
      "";

    return {
      id: data?.id ?? "",
      is_global: Number(data?.is_global ?? 0),
      name: data?.name ?? "",
      idUnique: data?.idUnique ?? data?.id_unique ?? "",
      trade: data?.trade ?? "",
      note: data?.note ?? "",
      lineTemplate: data?.lineTemplate ?? "",
      perimeter: perimetro_actual,
      perimeterFields: Array.isArray(data?.perimeterFields) && data.perimeterFields.length > 0
        ? data.perimeterFields.map((field) => ({
            perimeter: field?.perimeter ?? perimetro_actual,
            material: field?.material ?? "",
            materialQty: field?.materialQty ?? "",
            totalLf: field?.totalLf ?? "",
            totalUnits: field?.totalUnits ?? "",
          }))
        : [
            {
              perimeter: perimetro_actual,
              material: "",
              materialQty: "",
              totalLf: "",
              totalUnits: "",
            },
          ],
    };
  };

  const hasRealWallsData = (data) => {
    if (!data || typeof data !== "object") return false;

    if (Array.isArray(data.perimeterFields) && data.perimeterFields.length > 0) {
      return true;
    }

    if (data.trade) return true;
    if (data.note) return true;
    if (data.lineTemplate) return true;
    if (data.idUnique) return true;

    return false;
  };

  const getTemplateId = (value) => {
    if (!value) {
      return null;
    }

    if (typeof value === "number") {
      return value;
    }

    if (
      typeof value === "string" &&
      /^\d+$/.test(value.trim())
    ) {
      return Number(value);
    }

    if (typeof value === "object" && value?.id) {
      return Number(value.id);
    }

    if (typeof value === "string") {
      try {
        const parsed = JSON.parse(value);

        if (parsed?.id) {
          return Number(parsed.id);
        }
      } catch (error) {
        // No es JSON anterior.
      }
    }

    return null;
  };

  // -------------------------
  // Init (takeoff / template merge)
  // -------------------------
  useEffect(() => {
    let isMounted = true;

    const initializePerimeter = async () => {
      let next = normalizePerimeterState(formDataPerimeter);

      // Editar template.
      if (isEditTemplate && perimeterData?.local_db) {
        try {
          const parsedLocalDb =
            typeof perimeterData.local_db === "string"
              ? JSON.parse(perimeterData.local_db)
              : perimeterData.local_db;

          next = {
            ...next,
            ...normalizePerimeterState(parsedLocalDb),
            id: perimeterData.id,
            name:
              perimeterData.template_name ??
              parsedLocalDb.name ??
              "",
            trade:
              parsedLocalDb.trade ??
              perimeterData.trade_name ??
              "",
            is_global: Number(
              perimeterData.is_global ??
              parsedLocalDb.is_global ??
              0
            ),
            lineTemplate: perimeterData.id,
          };
        } catch (error) {
          console.warn(
            "Error parseando local_db de perimeter template:",
            error
          );
        }

        if (isMounted) {
          setFormDataPerimeter(next);
        }

        return;
      }

      const perimeterTieneDataReal =
        hasRealWallsData(perimeterData);

      // El template ahora se busca solamente por ID.
      const templateId = getTemplateId(
        takeoff?.lineTemplateId ??
        takeoff?.lineTemplate ??
        perimeterData?.template_id ??
        perimeterData?.lineTemplate
      );

      if (templateId) {
        try {
          const template =
            await fetchPerimeterTemplateById(templateId);

          if (template?.local_db) {
            const parsedLocalDb =
              typeof template.local_db === "string"
                ? JSON.parse(template.local_db)
                : template.local_db;

            next = {
              ...next,
              ...normalizePerimeterState(parsedLocalDb),
              lineTemplate: Number(template.id),
            };
          }
        } catch (error) {
          console.warn(
            "Error loading perimeter template:",
            error
          );
        }
      }

      /*
       * El template es solamente la base. Si ObtenData encontró un wall
       * guardado, sus valores deben tener prioridad sobre local_db, igual que
       * en LengthPopup. Antes se aplicaba perimeterData primero y luego el
       * template lo reemplazaba, por eso al abrir siempre se veía la plantilla.
       */
      if (perimeterTieneDataReal) {
        const wallState = normalizePerimeterState(perimeterData);

        next = {
          ...next,
          ...wallState,
          lineTemplate:
            wallState.lineTemplate ||
            next.lineTemplate ||
            templateId ||
            "",
        };
      }

      // Los valores del trazo tienen prioridad.
      if (takeoff?.perimetro != null) {
        next.perimeter = takeoff.perimetro;
      }

      if (takeoff?.name != null) {
        next.name = takeoff.name;
      }

      if (takeoff?.idUnique != null) {
        next.idUnique = takeoff.idUnique;
      }

      next.perimeterFields =
        Array.isArray(next.perimeterFields) &&
        next.perimeterFields.length > 0
          ? next.perimeterFields.map((field) => ({
              ...field,
              perimeter:
                takeoff?.perimetro ??
                field?.perimeter ??
                "",
            }))
          : [
              {
                perimeter: takeoff?.perimetro ?? "",
                material: "",
                materialQty: "",
                totalLf: "",
                totalUnits: "",
              },
            ];

      next = normalizePerimeterFormData(next);

      if (isMounted) {
        setFormDataPerimeter(next);
        await CalculateData(next);
      }
    };

    initializePerimeter();

    return () => {
      isMounted = false;
    };

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [perimeterData, takeoff]);

  const filteredWallMaterials = useMemo(() => {
    const selectedTradeId = getIdFromMaybeJson(formDataPerimeter.trade);
    if (!selectedTradeId) return wallMaterials;
    return wallMaterials.filter((m) => String(m.material_division_id) === String(selectedTradeId));
  }, [wallMaterials, formDataPerimeter.trade]);

  // -------------------------
  // Rows
  // -------------------------
  const handleAddClick = () => {
    const updated = {
      ...formDataPerimeter,
      perimeterFields: [
        ...formDataPerimeter.perimeterFields,
        {
          perimeter: takeoff?.perimetro ?? "",
          material: "",
          materialQty: "",
          totalLf: "",
          totalUnits: "",
        },
      ],
    };

    setFormDataPerimeter(updated);
    CalculateData(updated);
  };

  const handleDeleteClick = (index) => {
    const updatedPerimeterFields = [...formDataPerimeter.perimeterFields];
    updatedPerimeterFields.splice(index, 1);
    const updated = { ...formDataPerimeter, perimeterFields: updatedPerimeterFields };
    setFormDataPerimeter(updated);
    CalculateData(updated);
  };

  const obtenerIdUniqueRespuesta = (respuesta_calculo, form_data_enviada) => {
    const id_unique_resultado =
      respuesta_calculo?.resultado?.idUnique ??
      respuesta_calculo?.resultado?.id_unique ??
      respuesta_calculo?.idUnique ??
      respuesta_calculo?.id_unique ??
      "";

    const id_unique_actual =
      form_data_enviada?.idUnique ??
      form_data_enviada?.id_unique ??
      "";

    return {
      id_unique_actual: String(id_unique_actual || "").trim(),
      id_unique_nuevo: String(id_unique_resultado || "").trim(),
    };
  };

  const sonPathsIguales = (path_a = [], path_b = []) => {
    if (!Array.isArray(path_a) || !Array.isArray(path_b)) {
      return false;
    }

    if (path_a.length !== path_b.length) {
      return false;
    }

    for (let indice = 0; indice < path_a.length; indice++) {
      const punto_a = path_a[indice] || {};
      const punto_b = path_b[indice] || {};

      if (
        Number(punto_a.x) !== Number(punto_b.x) ||
        Number(punto_a.y) !== Number(punto_b.y)
      ) {
        return false;
      }
    }

    return true;
  };

  const actualizarIdUniqueEnColeccion = (
    coleccion = [],
    nombre_takeoff = "",
    id_unique_nuevo = "",
    path_objetivo = []
  ) => {
    if (!Array.isArray(coleccion)) {
      return coleccion;
    }

    let hubo_actualizacion_por_path = false;

    const coleccion_actualizada_por_path = coleccion.map((item) => {
      const nombre_actual = item?.meta?.name ?? "";
      const id_unique_actual = String(item?.meta?.idUnique ?? "").trim();
      const path_actual = item?.path ?? [];

      const coincide_nombre = nombre_actual === nombre_takeoff;
      const coincide_path = sonPathsIguales(path_actual, path_objetivo);

      if (
        coincide_nombre &&
        coincide_path &&
        id_unique_actual === ""
      ) {
        hubo_actualizacion_por_path = true;

        return {
          ...item,
          meta: {
            ...item.meta,
            idUnique: id_unique_nuevo,
          },
        };
      }

      return item;
    });

    // ✅ propagar el mismo idUnique al resto de trazos del mismo takeoff
    return coleccion_actualizada_por_path.map((item) => {
      const nombre_actual = item?.meta?.name ?? "";
      const id_unique_actual = String(item?.meta?.idUnique ?? "").trim();

      if (nombre_actual === nombre_takeoff && id_unique_actual === "") {
        return {
          ...item,
          meta: {
            ...item.meta,
            idUnique: id_unique_nuevo,
          },
        };
      }

      return item;
    });
  };

  const guardarIdUniqueEnDexie = async (
    pathname_actual,
    nombre_takeoff,
    id_unique_nuevo,
    path_takeoff_actual = []
  ) => {
    if (!pathname_actual || !nombre_takeoff || !id_unique_nuevo) {
      return null;
    }

    const drawing_actual = await db.drawings.where({ path: pathname_actual }).first();

    if (!drawing_actual) {
      console.log("No se encontró drawing en Dexie para actualizar idUnique en perimeter");
      return null;
    }

    const drawing_actualizado = { ...drawing_actual };

    const perimeter_base = Array.isArray(drawing_actualizado.perimeter)
      ? drawing_actualizado.perimeter
      : [];

    const perimeter_actualizado = actualizarIdUniqueEnColeccion(
      perimeter_base,
      nombre_takeoff,
      id_unique_nuevo,
      path_takeoff_actual
    );

    drawing_actualizado.perimeter = perimeter_actualizado;
    drawing_actualizado.updated_at = new Date().toISOString();

    await db.drawings.put(drawing_actualizado);

    console.log("Dexie perimeter actualizado con idUnique:", id_unique_nuevo);
    console.log("drawing_actualizado.perimeter", drawing_actualizado.perimeter);

    return drawing_actualizado;
  };

  const syncDrawingToBackend = async (drawing_actualizado) => {
    if (!drawing_actualizado) {
      return null;
    }

    const payload = {
      id: drawing_actualizado.id,
      path: drawing_actualizado.path,
      line: drawing_actualizado.lines ?? [],
      area: drawing_actualizado.area ?? [],
      counts: drawing_actualizado.counts ?? [],
      factor: drawing_actualizado.factor,
      perimeter: drawing_actualizado.perimeter ?? [],
      scale: String(drawing_actualizado.scale || ""),
      storedEllipses: drawing_actualizado.storedEllipses ?? [],
      storedHyperLinks: drawing_actualizado.storedHyperLinks ?? [],
      storedLines: drawing_actualizado.storedLines ?? [],
      storedPhotos: drawing_actualizado.storedPhotos ?? [],
      storedStickyNotes: drawing_actualizado.storedStickyNotes ?? [],
      storedRectangles: drawing_actualizado.storedRectangles ?? [],
      storedTexts: drawing_actualizado.storedTexts ?? [],
      updated_at: drawing_actualizado.updated_at,
    };

    try {
      const response = await fetch(`/api/sync/drawings`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${routes.__token}`,
        },
        body: JSON.stringify(payload),
      });

      const response_text = await response.text();
      console.log("sync drawings perimeter raw response", response_text);

      if (!response.ok) {
        throw new Error(`Error sincronizando drawings perimeter: ${response_text}`);
      }

      let data = null;

      try {
        data = JSON.parse(response_text);
      } catch (error) {
        data = response_text;
      }

      console.log("respuesta sync drawings perimeter", data);
      return data;
    } catch (error) {
      console.log("Error enviando drawing perimeter actualizado por sync", error);
      return null;
    }
  };

  const obtenerIdUniqueExistenteEnDexie = async (
    pathname_actual,
    nombre_takeoff,
    path_takeoff_actual = []
  ) => {
    if (!pathname_actual || !nombre_takeoff) {
      return "";
    }

    const drawing_actual = await db.drawings.where({ path: pathname_actual }).first();

    if (!drawing_actual) {
      return "";
    }

    const perimeter_base = Array.isArray(drawing_actual.perimeter)
      ? drawing_actual.perimeter
      : [];

    if (!Array.isArray(perimeter_base) || perimeter_base.length === 0) {
      return "";
    }

    // 1. primero por path exacto
    const coincidencia_por_path = perimeter_base.find((item) => {
      const nombre_actual = item?.meta?.name ?? "";
      const id_unique_actual = String(item?.meta?.idUnique ?? "").trim();
      const path_actual = item?.path ?? [];

      return (
        nombre_actual === nombre_takeoff &&
        id_unique_actual !== "" &&
        sonPathsIguales(path_actual, path_takeoff_actual)
      );
    });

    if (coincidencia_por_path) {
      return String(coincidencia_por_path.meta.idUnique).trim();
    }

    // 2. fallback por nombre dentro del mismo plano
    const coincidencia_por_nombre = perimeter_base.find((item) => {
      const nombre_actual = item?.meta?.name ?? "";
      const id_unique_actual = String(item?.meta?.idUnique ?? "").trim();

      return nombre_actual === nombre_takeoff && id_unique_actual !== "";
    });

    if (coincidencia_por_nombre) {
      return String(coincidencia_por_nombre.meta.idUnique).trim();
    }

    return "";
  };

  // -------------------------
  // Calculate
  // -------------------------
  const CalculateData = async (updatedFormData) => {
    updatedFormData = updatedFormData ?? formDataPerimeter;

    let id_unique_final = String(updatedFormData?.idUnique ?? "").trim();

    if (id_unique_final === "") {
      const id_unique_existente = await obtenerIdUniqueExistenteEnDexie(
        pathname,
        updatedFormData?.name ?? "",
        takeoff?.path ?? []
      );

      if (id_unique_existente !== "") {
        id_unique_final = id_unique_existente;
      }
    }

    updatedFormData = {
      ...updatedFormData,
      idUnique: id_unique_final,
    };

    //const cleanFormData = { ...updatedFormData };
    //delete cleanFormData.is_global;

    const normalized = normalizePerimeterFormData(updatedFormData);

    const dataToSend = {
      template_name: normalized?.name ?? "",

      template_id: getTemplateId(
        normalized?.lineTemplate ??
        takeoff?.lineTemplateId ??
        takeoff?.lineTemplate
      ),

      idUnique: id_unique_final,
      trade_name: normalized?.trade ?? "",

      formData: {
        ...normalized,
        idUnique: id_unique_final,
      },

      type: "perimeter",
      projectId,
    };

    const response = await fetch(`/api/CalculateData`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${routes.__token}`,
      },
      body: JSON.stringify(dataToSend),
    }).catch(function (error) {
      console.log("Request failed", error);
    });

    if (!response) {
      uiToast.error("Could not connect to the server.");
      return null;
    }

    let data = null;

    try {
      data = await response.json();
    } catch (error) {
      console.error(
        "Invalid CalculateData response:",
        error
      );

      uiToast.error("Invalid server response.");
      return null;
    }

    if (data?.status === 200) {
      const { id_unique_actual, id_unique_nuevo } = obtenerIdUniqueRespuesta(
        data,
        updatedFormData
      );

      const resultado = {
        ...updatedFormData,
        ...data.resultado,

        idUnique: id_unique_nuevo || id_unique_actual || "",

        lineTemplate:
          data.resultado?.lineTemplate ??
          updatedFormData?.lineTemplate ??
          takeoff?.lineTemplateId ??
          takeoff?.lineTemplate ??
          "",
      };

      const el = document.getElementById("totales_div");
      if (el) el.innerHTML = resultado.totales_html || "";

      if (id_unique_actual === "" && id_unique_nuevo !== "") {
        console.log("Nuevo idUnique detectado desde CalculateData perimeter:", id_unique_nuevo);

        const drawing_actualizado = await guardarIdUniqueEnDexie(
          pathname,
          updatedFormData.name,
          id_unique_nuevo,
          takeoff?.path ?? []
        );

        console.log("drawing_actualizado perimeter", drawing_actualizado);

        await syncDrawingToBackend(drawing_actualizado);
      }

      const resultadoNormalizado =
        normalizePerimeterFormData(resultado);

      setFormDataPerimeter(resultadoNormalizado);

      return resultadoNormalizado;
    }

    if (data?.status === 400) {
      uiToast.error("Calculation error!");
    }

    if (response && !response.ok) {
      throw new Error("Error processing");
    }
  };

  // -------------------------
  // Submit (Dexie)
  // -------------------------
  const handleFormSubmit = async (e) => {
    e.preventDefault();
    try {
      const perimeterName = formDataPerimeter.name || "Perimeter Takeoff";

      await db.line_Takeoff.clear(); // igual que length
      const templateId = Number(
        formDataPerimeter.lineTemplate ||
        takeoff?.lineTemplateId ||
        takeoff?.lineTemplate ||
        0
      );

      await db.line_Takeoff.add({
        takeoff_name: perimeterName,
        lineTemplate: templateId || null,
        lineTemplateId: templateId || null,
        updated_at: new Date().toISOString(),
      });

      uiToast.success("Perimeter Takeoff saved locally!");
      setDisplay(false);
    } catch (err) {
      console.error("Error guardando Perimeter en Dexie:", err);
      uiToast.error("Could not save Perimeter Takeoff");
    }
  };

  const handleSaveTemplate = async () => {
    try {
      setLoading(true);
      setLoadingMesagge("Saving template...");
      const dataToSend = {
        id: isEditTemplate ? formDataPerimeter.id : null,
        template_name: formDataPerimeter.name,
        trade_name: formDataPerimeter.trade,
        formData: formDataPerimeter,
        template_type: "perimeter",
        is_global: Number(formDataPerimeter.is_global ?? 0),
      };

      if (!formDataPerimeter.name) {
        uiAlert.warning("Missing name", "Please enter a TakeOff name.");
        setLoading(false);
        return;
      }

      const url = isEditTemplate
        ? `/api/update-line-template`
        : `/api/save-line-template`;

      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${routes.__token}`,
        },
        body: JSON.stringify(dataToSend),
      });

      const data = await response.json();

      if (data.status === 200) {
        uiToast.success("Template added successfully!");
        signal.emit("template.created", {
          template_name: formDataPerimeter.name,
          template_type: "perimeter",
        });
        setTimeout(() => setDisplay(false), 500);
      }

      if (data.status === 400) {
        uiToast.warning("Template already exists!");
      }

      if (!response.ok) {
        throw new Error("Error saving as template");
      }
    } catch (error) {
      console.error("Error saving template:", error);
      uiToast.error("Error saving template, please try again.");
    } finally {
      setLoading(false);
    }
  };

  // -------------------------
  // Fetch Materials + Trades
  // -------------------------
  useEffect(() => {
    const fetchWallMaterials = async () => {
      try {
        const response = await fetch(`/api/materials/${projectId}`, {
          method: "GET",
          headers: { Authorization: `Bearer ${routes.__token}` },
        });
        if (!response.ok) return;

        const data = await response.json();
        setWallMaterials(data);
      } catch (error) {
        console.error("Error fetching wall materials data:", error);
      }
    };

    const fetchTradeData = async () => {
      try {
        const response = await fetch("/api/materials/divisions", {
          method: "GET",
          headers: { Authorization: `Bearer ${routes.__token}` },
        });
        if (!response.ok) return;

        const data = await response.json();
        setTrade(data);
      } catch (error) {
        console.error("Error fetching trade data:", error);
      }
    };

    fetchWallMaterials();
    fetchTradeData();
  }, []);

  useEffect(() => {
    if (!wallMaterials || wallMaterials.length === 0) return;
    if (hasSyncedMaterials.current) return;
    if (popupMode === "create" && perimeterData === null && takeoff === null) return;

    setFormDataPerimeter((prev) => {
      let hasUpdates = false;
      let nextFormData = { ...prev };

      const updateMaterialIfChanged = (val) => {
        if (!val || val === "0" || val === 0) return val;
        let unique_id = getUniqueIdFromMaybeJson(val);
        let id = getIdFromMaybeJson(val);

        if (!unique_id && !id) return val;

        const freshMat = Array.isArray(wallMaterials)
          ? wallMaterials.find(
            (m) =>
              (unique_id && String(m.unique_id) === String(unique_id)) ||
              (id && String(m.id) === String(id))
          )
          : null;

        if (freshMat) {
          const freshJson = JSON.stringify(freshMat);
          const oldJson = typeof val === "string" ? val : JSON.stringify(val);
          if (freshJson !== oldJson) {
            hasUpdates = true;
            return freshJson;
          }
        }
        return val;
      };

      if (nextFormData.perimeterFields && Array.isArray(nextFormData.perimeterFields)) {
        nextFormData.perimeterFields = nextFormData.perimeterFields.map((row) => {
          if (row.material) {
            const updated = updateMaterialIfChanged(row.material);
            if (updated !== row.material) {
              return { ...row, material: updated };
            }
          }
          return row;
        });
      }

      if (hasUpdates) {
        hasSyncedMaterials.current = true;
        return nextFormData;
      }

      hasSyncedMaterials.current = true;
      return prev;
    });
  }, [wallMaterials, popupMode, perimeterData, takeoff]);

  useEffect(() => {
    if (!trade || trade.length === 0) return;
    if (hasSyncedTrade.current) return;
    if (popupMode === "create" && perimeterData === null && takeoff === null) return;

    setFormDataPerimeter((prev) => {
      let hasUpdates = false;
      let nextFormData = { ...prev };

      if (nextFormData.trade) {
        const id = getIdFromMaybeJson(nextFormData.trade);
        if (id) {
          const freshTrade = trade.find((t) => String(t.id) === String(id));
          if (freshTrade) {
            const freshJson = JSON.stringify(freshTrade);
            const oldJson =
              typeof nextFormData.trade === "string"
                ? nextFormData.trade
                : JSON.stringify(nextFormData.trade);

            if (freshJson !== oldJson) {
              hasUpdates = true;
              nextFormData.trade = freshJson;
            }
          }
        }
      }

      if (hasUpdates) {
        hasSyncedTrade.current = true;
        return nextFormData;
      }

      hasSyncedTrade.current = true;
      return prev;
    });
  }, [trade, popupMode, perimeterData, takeoff]);

  const handleCreateReport = async () => {
    try {
      setLoading(true);
      setLoadingMesagge("Generating report...");

      const resultado = await CalculateData({ ...formDataPerimeter });

      const html = (resultado && resultado.totales_html) ? String(resultado.totales_html) : "";

      setReportTitle(
        isCreate
          ? "Perimeter Template Report"
          : "Perimeter Takeoff Report"
      );
      setReportHtml(html);
      setOpenReportPopup(true);
    } catch (e) {
      console.error("Create report error:", e);
      uiAlert.error("Report error", "Could not generate the report.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <ProcessingOverlay visible={loading} message={loadingMesagge} />
      {!openReportPopup && createPortal(
        <Draggable>
          <div className="popup__count popup-perimeter">
            <div className="modal-header">
              {headerTitle}
              <span className="close-btn" onClick={() => setDisplay(false)}>
                &times;
              </span>
            </div>

            <form className="modal-body" onSubmit={handleFormSubmit}>
              <div className="perimeter-form-grid">
                <section className="perimeter-card perimeter-card-full">
                  <h4>Template Setup</h4>

                  {isCreate && (
                    <div className="perimeter-field perimeter-field-full">
                      <label className="label">Select Template</label>
                      <select name="lineTemplate" value={formDataPerimeter.lineTemplate} onChange={set_line_template}>
                        <option value="" hidden>-- Select template --</option>
                        {templates.map((t) => (
                          <option key={t.id} value={String(t.id)}>
                            {t.template_name}
                          </option>
                        ))}
                      </select>
                    </div>
                  )}

                  <div className="perimeter-fields-2">
                    <div className="perimeter-field">
                      <label className="label">
                        {isCreate ? "Template Description" : "Takeoff Description"}
                      </label>
                      <input
                        type="text"
                        placeholder="Takeoff Name"
                        name="name"
                        id="name"
                        value={formDataPerimeter.name}
                        onChange={handleInputChange}
                        onBlur={handleInputBlur}
                      />
                    </div>

                    <div className="perimeter-field">
                      <label className="label">CSI Division / Trade</label>
                      <select
                        name="trade"
                        value={getIdFromMaybeJson(formDataPerimeter.trade)}
                        onChange={handleInputChange}
                        onBlur={handleInputBlur}
                      >
                        <option value="">-- Select Trade --</option>
                        {trade.map((tradeItem) => (
                          <option key={tradeItem.id} value={String(tradeItem.id)} data-item={JSON.stringify(tradeItem)}>
                            {tradeItem.name}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                </section>

                <section className="perimeter-card perimeter-card-full">
                  <h4>Measurements</h4>

                  {(formDataPerimeter.perimeterFields || []).map((field, index) => (
                    <div key={index} className="perimeter-repeat-row">
                      <div className="perimeter-field">
                        <label className="label">Measured Length</label>
                        <input
                          type="number"
                          step="0.0001"
                          name={`perimeterFields[${index}][perimeter]`}
                          value={field.perimeter}
                          placeholder="Measured Length"
                          onChange={handleInputChange}
                          onBlur={handleInputBlur}
                          readOnly={!!takeoff?.perimetro}
                        />
                      </div>

                      <div className="perimeter-field">
                        <label className="label">Material</label>
                        <select
                          name={`perimeterFields[${index}][material]`}
                          value={getUniqueIdFromMaybeJson(field.material)}
                          onChange={handleInputChange}
                          onBlur={handleInputBlur}
                        >
                          <option value="">-- Select Material --</option>
                          {filteredWallMaterials.map((material) => (
                            <option
                              key={material.id}
                              value={String(material.unique_id ?? material.id)}
                              data-item={JSON.stringify(material)}
                            >
                              {material.name}
                            </option>
                          ))}
                        </select>
                      </div>

                      <div className="perimeter-field">
                        <label className="label">Coverage Rate</label>
                        <input
                          type="number"
                          step="0.0001"
                          name={`perimeterFields[${index}][materialQty]`}
                          value={field.materialQty}
                          placeholder="Coverage Rate"
                          onChange={handleInputChange}
                          onBlur={handleInputBlur}
                        />
                      </div>

                      <div className="perimeter-field">
                        <label className="label">Calculated Quantity</label>
                        <input
                          type="number"
                          step="0.0001"
                          name={`perimeterFields[${index}][totalUnits]`}
                          value={field.totalUnits}
                          placeholder="Calculated Quantity"
                          readOnly
                        />
                      </div>

                      <div className="perimeter-row-actions">
                        {formDataPerimeter.perimeterFields.length > 1 && (
                          <button className="btn btn-danger" type="button" onClick={() => handleDeleteClick(index)}>
                            <i className="fa-solid fa-trash" />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}

                  <button className="btn btn-primary perimeter-add-btn" type="button" onClick={handleAddClick}>
                    <i className="fa-light fa-plus"></i> Add Material
                  </button>
                </section>

                <section className="perimeter-card perimeter-card-full">
                  <h4>General Notes</h4>

                  <textarea
                    name="note"
                    rows={10}
                    value={formDataPerimeter.note}
                    onChange={handleInputChange}
                    onBlur={handleInputBlur}
                  />

                  {(isCreate || isEditTemplate) && (
                    <div className="template-save-actions">
                      <button className="btn-save mt-2" onClick={handleSaveTemplate} type="button">
                        {isEditTemplate ? "Save Template" : "Save as Template"}
                      </button>

                      {Number(userRole) === 1 && (
                        <label className="template-global-switch template-global-switch-inline">
                          <input
                            type="checkbox"
                            checked={Number(formDataPerimeter.is_global ?? 0) === 1}
                            onChange={(e) =>
                              setFormDataPerimeter((prev) => ({
                                ...prev,
                                is_global: e.target.checked ? 1 : 0,
                              }))
                            }
                          />
                          <span>Global Template</span>
                        </label>
                      )}
                    </div>
                  )}

                  {!isCreate && !isEditTemplate && (
                    <button type="button" className="btn-save mt-2" onClick={handleCreateReport}>
                      Create report
                    </button>
                  )}
                </section>
              </div>
            </form>
          </div>
        </Draggable>,
        document.querySelector("#root")
      )}
      <ReportPopup
        open={openReportPopup}
        title={reportTitle}
        onClose={() => setOpenReportPopup(false)}
      >
        <div dangerouslySetInnerHTML={{ __html: reportHtml }} />
      </ReportPopup>
    </>
  );
}

export default PerimeterPopup;
