import { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { Document, Page, pdfjs } from "react-pdf";
import Swal from "sweetalert2";

pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.mjs`;

const swalOk = (title, text = "") =>
  Swal.fire({
    icon: "success",
    title,
    text,
    timer: 2200,
    showConfirmButton: false,
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  });

const swalWarn = (title, text = "") =>
  Swal.fire({
    icon: "warning",
    title,
    text,
    confirmButtonText: "OK",
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  });

const swalErr = (title, text = "") =>
  Swal.fire({
    icon: "error",
    title,
    text,
    confirmButtonText: "OK",
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  });

function safeCode(code) {
  return String(code || "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/[^\w\-]/g, "");
}

/* =========================
   Lazy-load & Sub-components
========================= */
function useInView(options) {
  const [inView, setInView] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const obs = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      options || { root: null, rootMargin: "800px", threshold: 0.01 }
    );

    obs.observe(el);
    return () => obs.disconnect();
  }, [options]);

  return { ref, inView };
}

function LazyPageThumb({
  pageNumber,
  selected,
  onToggle,

  // info display
  finalCode,
  codesLocal, // array of scanned codes
  hasManual,
  hasAi,

  // editing
  isEditing,
  editValue,
  onStartEdit,
  onEditChange,
  onEditCommit,
  onEditCancel,
}) {
  const { ref, inView } = useInView({ rootMargin: "800px", threshold: 0.01 });
  const inputRef = useRef(null);

  useEffect(() => {
    if (isEditing) {
      requestAnimationFrame(() => {
        if (inputRef.current) {
          inputRef.current.focus();
          inputRef.current.select();
        }
      });
    }
  }, [isEditing]);

  return (
    <div
      ref={ref}
      style={{
        display: "inline-block",
        margin: "10px",
        textAlign: "center",
        border: selected ? "3px solid #0d6efd" : "1px solid #ccc",
        borderRadius: "8px",
        background: "#fff",
        padding: "8px",
        width: 180,
        minHeight: 250,
        verticalAlign: "top",
      }}
    >
      <div
        style={{
          width: 160,
          height: 210,
          margin: "0 auto",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          background: "#f8f9fa",
          borderRadius: 4,
        }}
      >
        {inView ? (
          <Page
            pageNumber={pageNumber}
            width={160}
            renderTextLayer={false}
            renderAnnotationLayer={false}
            error={<div style={{ fontSize: 10 }}>Error loading page</div>}
            loading={<div style={{ fontSize: 10 }}>Loading...</div>}
          />
        ) : (
          <div style={{ fontSize: 12, color: "#999" }}>Loading...</div>
        )}
      </div>

      <label style={{ fontSize: "12px", display: "block", marginTop: 6, cursor: "pointer" }}>
        <input
          type="checkbox"
          checked={selected}
          onChange={() => onToggle(pageNumber)}
          style={{ marginRight: "4px" }}
        />
        Page {pageNumber}
      </label>

      {/* Editable Code Box */}
      <div
        style={{
          marginTop: 6,
          fontSize: 11,
          background: "#f8f9fa",
          border: "1px dashed #ced4da",
          borderRadius: 6,
          padding: "6px",
          textAlign: "left",
        }}
        title="Double-click to rename"
        onDoubleClick={() => onStartEdit(pageNumber)}
      >
        {isEditing ? (
          <input
            ref={inputRef}
            value={editValue}
            onChange={(e) => onEditChange(e.target.value)}
            onBlur={() => onEditCommit(pageNumber)}
            onKeyDown={(e) => {
              if (e.key === "Enter") onEditCommit(pageNumber);
              if (e.key === "Escape") onEditCancel();
            }}
            placeholder={`PAGE-${pageNumber}`}
            style={{
              width: "100%",
              fontSize: 11,
              padding: "4px 6px",
              borderRadius: 6,
              border: "1px solid #ced4da",
              outline: "none",
              background: "#fff",
            }}
          />
        ) : (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 4, alignItems: "center", marginBottom: 4 }}>
              <strong style={{ fontSize: 11, color: "#343a40", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                {finalCode}
              </strong>
              <div style={{ display: "flex", gap: 2 }}>
                {hasManual && <span style={{ fontSize: 9, padding: "1px 4px", borderRadius: 4, background: "#0d6efd", color: "#fff" }}>M</span>}
                {!hasManual && hasAi && <span style={{ fontSize: 9, padding: "1px 4px", borderRadius: 4, background: "#198754", color: "#fff" }}>AI</span>}
                {!hasManual && !hasAi && codesLocal?.length > 0 && <span style={{ fontSize: 9, padding: "1px 4px", borderRadius: 4, background: "#6c757d", color: "#fff" }}>S</span>}
              </div>
            </div>

            {codesLocal.length > 0 ? (
              <div style={{ fontSize: 10, color: "#6c757d", lineHeight: 1.2 }}>
                {codesLocal.slice(0, 3).map((c, i) => (
                  <span key={i} style={{ marginRight: 4 }}>{c}</span>
                ))}
                {codesLocal.length > 3 && <span>...</span>}
              </div>
            ) : (
              <div style={{ fontSize: 10, color: "#adb5bd" }}>(No scan)</div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

export default function PageSelectorPopup({
  file,
  onClose,
  onSave,

  // Debe devolver: { codes: { [pageNumber]: "CODE" } }
  onAnalyzeCodes,

  // para localStorage único por proyecto
  projectId,
}) {
  const [numPages, setNumPages] = useState(null);
  const [selectedPages, setSelectedPages] = useState([]);

  // local scan (regex)
  const [pageMeta, setPageMeta] = useState([]);
  const [scanningLocal, setScanningLocal] = useState(false);

  // AI codes
  const [aiCodes, setAiCodes] = useState({});
  const [scanningAi, setScanningAi] = useState(false);

  // manual overrides
  const [manualCodes, setManualCodes] = useState({});

  // edit UI
  const [editingPage, setEditingPage] = useState(null);
  const [editingValue, setEditingValue] = useState("");

  // ✅ igual que PdfPreviewPopup: decisión inicial
  const [shouldAnalyze, setShouldAnalyze] = useState(null);
  const askedRef = useRef(false);

  const fileKey = useMemo(() => {
    const pid = projectId !== undefined && projectId !== null ? String(projectId) : "no_project";
    return `folder_page_codes__${pid}__${file?.name || "no_file"}`;
  }, [projectId, file?.name]);

  // load manual overrides
  useEffect(() => {
    try {
      const raw = localStorage.getItem(fileKey);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === "object") setManualCodes(parsed);
      }
    } catch (e) { }
  }, [fileKey]);

  // persist manual overrides
  useEffect(() => {
    try {
      localStorage.setItem(fileKey, JSON.stringify(manualCodes || {}));
    } catch (e) { }
  }, [manualCodes, fileKey]);

  const togglePage = (page) => {
    setSelectedPages((prev) =>
      prev.includes(page) ? prev.filter((p) => p !== page) : [...prev, page]
    );
  };

  const selectAll = () => {
    if (!numPages) return;
    if (selectedPages.length === numPages) setSelectedPages([]); // vacío = ALL
    else setSelectedPages(Array.from({ length: numPages }, (_, i) => i + 1));
  };

  // Agrupa texto por líneas
  const itemsToLines = (items) => {
    const lines = [];
    let currentY = null;
    let buffer = [];
    for (const it of items) {
      const y = Math.round(it.transform?.[5] ?? 0);
      if (currentY === null) {
        currentY = y;
        buffer.push(it.str);
      } else if (Math.abs(y - currentY) <= 2) {
        buffer.push(it.str);
      } else {
        lines.push(buffer.join(" ").trim());
        buffer = [it.str];
        currentY = y;
      }
    }
    if (buffer.length) lines.push(buffer.join(" ").trim());
    return lines;
  };

  // Local scan (regex)
  useEffect(() => {
    let cancelled = false;

    const scan = async () => {
      if (!file?.url) return;
      setScanningLocal(true);

      try {
        const task = pdfjs.getDocument(file.url);
        const pdf = await task.promise;

        const meta = [];
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const tc = await page.getTextContent();
          const lines = itemsToLines(tc.items);

          const regex = /\b([A-Z]{1,4}[-.]?\d{1,4})\b/g;
          const codes = [];
          const joined = lines.join("\n");
          let m;

          while ((m = regex.exec(joined)) !== null) {
            const code = m[1];
            if (!codes.includes(code)) codes.push(code);
          }

          meta.push({ page: i, codes });
          if (cancelled) break;
        }

        if (!cancelled) setPageMeta(meta);
      } catch (e) {
        console.error("Error escaneando PDF:", e);
      } finally {
        if (!cancelled) setScanningLocal(false);
      }
    };

    scan();
    return () => {
      cancelled = true;
    };
  }, [file]);

  const getCodesFor = (page) => pageMeta.find((p) => p.page === page)?.codes ?? [];

  const finalCodeForPage = (page) => {
    const manual = manualCodes?.[page];
    if (manual && String(manual).trim() !== "") return safeCode(manual);

    const ai = aiCodes?.[page];
    if (ai && String(ai).trim() !== "") return safeCode(ai);

    const local = getCodesFor(page)?.[0];
    if (local) return safeCode(local);

    return `PAGE-${page}`;
  };

  const pagesArray = useMemo(() => {
    const n = Number(numPages || 0);
    return Array.from({ length: n }, (_, i) => i + 1);
  }, [numPages]);

  const pageCodesFinal = useMemo(() => {
    const out = {};
    pagesArray.forEach((p) => {
      out[p] = finalCodeForPage(p);
    });
  }, [pagesArray, manualCodes, aiCodes, pageMeta]);
  // OJO aquí: el bloque original tenía un bug sutil en dependencias o return, 
  // pero arriba lo copié del original. 
  // Revisando el original: "return out;" estaba.

  /* =========================================================
     ✅ SweetAlert inicial (igual PdfPreviewPopup)
  ========================================================= */
  useEffect(() => {
    if (!file?.name) return;
    if (askedRef.current) return;

    askedRef.current = true;

    Swal.fire({
      title: "What do you want to do?",
      html:
        "<div style='text-align:left;font-size:14px;line-height:1.4'>" +
        "<b>Find code (AI)</b>: detects a code per page (may take a bit).<br/>" +
        "<b>Just select and upload</b>: no analysis, pages will be named PAGE-n if no code exists." +
        "</div>",
      icon: "question",
      showCancelButton: true,
      confirmButtonText: "Find code",
      cancelButtonText: "Just upload",
      reverseButtons: true,
      allowOutsideClick: false,
      allowEscapeKey: false,
      didOpen: () => {
        const el = document.querySelector(".swal2-container");
        if (el) el.style.zIndex = "250000";
      },
    }).then((res) => {
      if (res.isConfirmed) setShouldAnalyze(true);
      else setShouldAnalyze(false);
    });
  }, [file]);

  /* =========================================================
     ✅ AI analysis automático
  ========================================================= */
  useEffect(() => {
    let cancelled = false;

    const runAi = async () => {
      if (shouldAnalyze !== true) return;

      if (!onAnalyzeCodes) {
        await swalWarn("No analyzer configured", "onAnalyzeCodes is missing.");
        return;
      }

      setScanningAi(true);
      try {
        const r = await onAnalyzeCodes(file); // { codes: { [page]: "CODE" } }
        if (cancelled) return;

        const codes = r?.codes || {};
        setAiCodes(codes);

        await swalOk("✅ Done", "AI codes loaded. You can still edit them manually per page.");
      } catch (e) {
        console.error(e);
        await swalErr("Could not analyze page codes.", e?.message || "");
      } finally {
        if (!cancelled) setScanningAi(false);
      }
    };

    runAi();
    return () => {
      cancelled = true;
    };
  }, [shouldAnalyze, onAnalyzeCodes, file]);

  /* ===== Manual edit ===== */
  const startEdit = (page) => {
    setEditingPage(page);
    setEditingValue(manualCodes?.[page] ?? pageCodesFinal?.[page] ?? "");
  };

  const saveEdit = () => {
    const page = editingPage;
    if (!page) return;

    const clean = safeCode(editingValue);

    setManualCodes((prev) => {
      const next = { ...(prev || {}) };
      if (!clean) delete next[page];
      else next[page] = clean;
      return next;
    });

    setEditingPage(null);
    setEditingValue("");
  };

  const cancelEdit = () => {
    setEditingPage(null);
    setEditingValue("");
  };

  const upload_all_pages = selectedPages.length === 0;

  return createPortal(
    <>
      <Draggable handle=".modal-header">
        <div
          className="popup__count"
          style={{
            zIndex: 99999,
            position: "fixed",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: "90%",
            maxWidth: "1100px",
            background: "#fff",
            borderRadius: "8px",
            boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
            overflow: "hidden",
          }}
        >
          <div
            className="modal-header"
            style={{
              background: "#343a40",
              color: "#fff",
              cursor: "move",
              padding: "10px 15px",
              fontWeight: "bold",
            }}
          >
            Seleccionar páginas — {file.name}
            <span
              onClick={onClose}
              style={{ cursor: "pointer", float: "right", fontSize: "18px", fontWeight: "bold" }}
            >
              ×
            </span>
          </div>

          <div
            className="modal-body"
            style={{
              maxHeight: "70vh",
              overflowY: "auto",
              background: "#f8f9fa",
              padding: "15px",
            }}
          >
            {(scanningAi && shouldAnalyze === true) && (
              <div
                style={{
                  background: "#fff3cd",
                  border: "1px solid #ffeeba",
                  color: "#856404",
                  padding: 10,
                  borderRadius: 8,
                  marginBottom: 10,
                  textAlign: "center",
                  fontSize: 13,
                }}
              >
                Analyzing the full PDF to detect a code per page…
                <br />
                (You can still select pages; if AI fails, it will use PAGE-n)
              </div>
            )}

            <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <button
                onClick={selectAll}
                style={{
                  background: "transparent",
                  border: "1px solid #0d6efd",
                  color: "#0d6efd",
                  padding: "6px 12px",
                  borderRadius: "4px",
                  cursor: "pointer",
                  marginBottom: "10px",
                }}
              >
                {selectedPages.length === numPages ? "Deseleccionar todas" : "Seleccionar todas"}
              </button>

              {scanningLocal && (
                <span style={{ fontSize: 12, color: "#6c757d" }}>
                  Analizando páginas para detectar códigos…
                </span>
              )}
            </div>

            <div style={{ fontSize: 12, color: "#6c757d", marginBottom: 10 }}>
              Tip: si no seleccionas páginas, se subirá el archivo completo.
              Doble click en el código para editarlo manualmente.
            </div>

            <Document
              file={file.url}
              onLoadSuccess={({ numPages }) => setNumPages(numPages)}
              loading={<p>Cargando PDF...</p>}
            >
              <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center" }}>
                {Array.from(new Array(numPages), (el, index) => {
                  const pageNo = index + 1;
                  const codesLocal = getCodesFor(pageNo);
                  const finalCode = pageCodesFinal?.[pageNo] || `PAGE-${pageNo}`;
                  const hasManual = !!manualCodes?.[pageNo];
                  const hasAi = !!aiCodes?.[pageNo];

                  const isEditing = editingPage === pageNo;
                  const editVal = isEditing ? editingValue : "";

                  return (
                    <LazyPageThumb
                      key={`page_${pageNo}`}
                      pageNumber={pageNo}
                      selected={selectedPages.includes(pageNo)}
                      onToggle={togglePage}

                      finalCode={finalCode}
                      codesLocal={codesLocal}
                      hasManual={hasManual}
                      hasAi={hasAi}

                      isEditing={isEditing}
                      editValue={editVal}
                      onStartEdit={startEdit}
                      onEditChange={setEditingValue}
                      onEditCommit={saveEdit}
                      onEditCancel={cancelEdit}
                    />
                  );
                })}
              </div>
            </Document>
          </div>

          <div
            className="modal-footer"
            style={{
              display: "flex",
              justifyContent: "flex-end",
              gap: "10px",
              background: "#f1f1f1",
              borderTop: "1px solid #ccc",
              padding: "10px 15px",
            }}
          >
            <button
              onClick={onClose}
              style={{
                background: "#6c757d",
                border: "none",
                color: "#fff",
                padding: "6px 12px",
                borderRadius: "4px",
                cursor: "pointer",
              }}
            >
              Cancelar
            </button>

            <button
              onClick={() =>
                onSave({
                  selectedPages,
                  upload_all_pages,
                  pageCodes: pageCodesFinal,
                })
              }
              style={{
                background: "#0d6efd",
                border: "none",
                color: "#fff",
                padding: "6px 12px",
                borderRadius: "4px",
                cursor: "pointer",
              }}
            >
              Guardar ({selectedPages.length === 0 ? "Todas" : selectedPages.length})
            </button>
          </div>
        </div>
      </Draggable>
    </>,
    document.getElementById("root")
  );
}
