import { routes, projectId } from "../Constants";
import { db } from "../database/db";
import useSignal from "../hooks/signals";
import Swal from "sweetalert2";

function DeleteAll() {
  const signal = useSignal();

  const swalBase = {
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  };

  const deleteAll = async () => {
    // ✅ Confirmación antes de borrar
    const confirm = await Swal.fire({
      ...swalBase,
      icon: "warning",
      title: "Delete all files?",
      html: `
        <div style="text-align:left; font-size:14px; line-height:1.45;">
          This will permanently delete <b>all files</b> for this project and remove related local drawings.<br/>
          <br/>
          <b>This action cannot be undone.</b>
        </div>
      `,
      showCancelButton: true,
      confirmButtonText: "Yes, delete all",
      cancelButtonText: "Cancel",
      reverseButtons: true,
      allowOutsideClick: false,
      allowEscapeKey: true,
    });

    if (!confirm.isConfirmed) return;

    // ✅ Loading
    Swal.fire({
      ...swalBase,
      title: "Deleting…",
      text: "Please wait while we delete the files.",
      allowOutsideClick: false,
      allowEscapeKey: false,
      showConfirmButton: false,
      didOpen: () => {
        swalBase.didOpen();
        Swal.showLoading();
      },
    });

    try {
      const url = routes.deleteAll + projectId;

      const response = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${routes.__token}`,
        },
      });

      const data = await response.json().catch(() => ({}));

      // ✅ Limpia Dexie usando filter robusto
      // MainBoard guarda: "/projects/project123/..."
      // Backend devuelve: "uploads/projects/project123/..."
      // Solución: borrar todo lo que contenga "project{id}/"
      const targetStr = `projects/project${projectId}/`;

      const dbProject = await db.drawings
        .filter((r) => r.path && r.path.includes(targetStr))
        .toArray();

      if (dbProject.length > 0) {
        await Promise.all(dbProject.map((record) => db.drawings.delete(record.id)));
      }

      if (data?.status === 200) {
        await Swal.fire({
          ...swalBase,
          icon: "success",
          title: "Deleted!",
          text: "All files were deleted successfully.",
          confirmButtonText: "OK",
        });

        signal.emit("refresh");
        return;
      }

      await Swal.fire({
        ...swalBase,
        icon: "info",
        title: "Nothing to delete",
        text: "No files were found for this project.",
        confirmButtonText: "OK",
      });
    } catch (error) {
      console.error("DeleteAll error:", error);

      await Swal.fire({
        ...swalBase,
        icon: "error",
        title: "Delete failed",
        text: error?.message || "An unexpected error occurred while deleting files.",
        confirmButtonText: "OK",
      });
    }
  };

  return (
    <>
      <li>
        <label className="custom-label" onClick={deleteAll}>
          Delete All
        </label>
      </li>
    </>
  );
}

export default DeleteAll;
