import React, { useEffect, useMemo, useState } from "react";
import { routes } from "../Constants";
import "../Css/workspace-panel.css";

function WorkspacePanel({
    isOpen,
    projectId,
    onClose,
    onCreateProject,
}) {

    const [activeTab, setActiveTab] = useState("projects");
    const [search, setSearch] = useState("");
    const [loading, setLoading] = useState(false);
    const [workspaceError, setWorkspaceError] = useState("");
    const [loggingOut, setLoggingOut] = useState(false);

    const [phpModal, setPhpModal] = useState({
        open: false,
        title: "",
        url: "",
    });

    const [workspace, setWorkspace] = useState({
        current_project: null,
        projects: [],
        equipments: [],
        materials: [],
        crews: [],
    });

    const apiUrl = routes.apiUrl || "/api";

    const getApiHeaders = (withJson = false) => {
        const headers = {
            Accept: "application/json",
            Authorization: `Bearer ${routes.__token}`,
        };

        if (withJson) {
            headers["Content-Type"] = "application/json";
        }

        return headers;
    };

    const phpFormRoutes = useMemo(() => {
        if (!projectId) {
            return {};
        }

        const materialReturnUrl = encodeURIComponent(
            `${routes.webUrl}/material/${projectId}`
        );

        return {
            equipments: {
                create:
                    `${routes.webUrl}/equipment/create` +
                    `?project_id=${projectId}` +
                    `&return_url=${materialReturnUrl}` +
                    `&popup=1`,

                edit: (id) =>
                    `${routes.webUrl}/equipment/edit/${id}` +
                    `?project_id=${projectId}` +
                    `&return_url=${materialReturnUrl}` +
                    `&popup=1`,
            },

            materials: {
                create:
                    `${routes.webUrl}/material/add` +
                    `?project_id=${projectId}` +
                    `&return_url=${materialReturnUrl}` +
                    `&popup=1`,

                edit: (id) =>
                    `${routes.webUrl}/material/edit/${id}` +
                    `?project_id=${projectId}` +
                    `&return_url=${materialReturnUrl}` +
                    `&popup=1`,
            },

            crews: {
                create:
                    `${routes.webUrl}/crew/create` +
                    `?project_id=${projectId}` +
                    `&return_url=${materialReturnUrl}` +
                    `&popup=1`,

                edit: (id) =>
                    `${routes.webUrl}/crew/edit/${id}` +
                    `?project_id=${projectId}` +
                    `&return_url=${materialReturnUrl}` +
                    `&popup=1`,
            },
        };
    }, [projectId]);

    const tabs = [
        {
            key: "projects",
            label: "Projects",
            icon: "fa-folder",
        },
        {
            key: "equipments",
            label: "Equipment",
            icon: "fa-screwdriver-wrench",
        },
        {
            key: "materials",
            label: "Materials",
            icon: "fa-boxes-stacked",
        },
        {
            key: "crews",
            label: "Crews",
            icon: "fa-people-group",
        },
    ];

    const openPhpModal = (title, url) => {
        setPhpModal({
            open: true,
            title,
            url,
        });
    };

    const closePhpModal = (reload = false) => {
        setPhpModal({
            open: false,
            title: "",
            url: "",
        });

        if (reload) {
            loadWorkspace();
        }
    };

    useEffect(() => {
        if (!isOpen) {
            return;
        }

        loadWorkspace();
    }, [isOpen, projectId]);

    useEffect(() => {
        setSearch("");
    }, [activeTab]);

    const loadWorkspace = async () => {
        if (!projectId) {
            setWorkspaceError(
                "The current project ID could not be detected."
            );

            console.error(
                "Workspace: invalid projectId",
                projectId,
                window.location.pathname
            );

            return;
        }

        try {
            setLoading(true);
            setWorkspaceError("");

            const url = `/api/workspace/${projectId}`;

            console.log("LOADING WORKSPACE:", {
                projectId,
                url,
                tokenExists: Boolean(routes.__token),
            });

            const response = await fetch(url, {
                method: "GET",
                headers: {
                    Accept: "application/json",
                    Authorization: `Bearer ${routes.__token}`,
                },
            });

            const responseText = await response.text();

            let result = null;

            try {
                result = responseText
                    ? JSON.parse(responseText)
                    : {};
            } catch (jsonError) {
                console.error(
                    "Workspace returned non-JSON content:",
                    responseText
                );

                throw new Error(
                    `The workspace endpoint returned invalid content. HTTP ${response.status}`
                );
            }

            console.log("WORKSPACE RESPONSE:", {
                status: response.status,
                ok: response.ok,
                result,
            });

            if (!response.ok) {
                throw new Error(
                    result?.message ||
                    result?.error ||
                    `Workspace request failed with HTTP ${response.status}`
                );
            }

            setWorkspace({
                current_project:
                    result.current_project || null,

                projects:
                    Array.isArray(result.projects)
                        ? result.projects
                        : [],

                equipments:
                    Array.isArray(result.equipments)
                        ? result.equipments
                        : [],

                materials:
                    Array.isArray(result.materials)
                        ? result.materials
                        : [],

                crews:
                    Array.isArray(result.crews)
                        ? result.crews
                        : [],
            });
        } catch (error) {
            console.error("WORKSPACE ERROR:", error);

            setWorkspaceError(
                error?.message ||
                "Unable to load the workspace."
            );
        } finally {
            setLoading(false);
        }
    };

    const currentItems = useMemo(() => {
        const items = workspace[activeTab] || [];
        const value = search.trim().toLowerCase();

        if (!value) {
            return items;
        }

        return items.filter((item) => {
            const name = String(item?.name || "").toLowerCase();
            const description = String(
                item?.description || ""
            ).toLowerCase();

            return (
                name.includes(value) ||
                description.includes(value)
            );
        });
    }, [workspace, activeTab, search]);

    const singularLabel = {
        equipments: "Equipment",
        materials: "Material",
        crews: "Crew",
    };

    const handleProjectClick = (project) => {
        if (!project?.id) {
            return;
        }

        window.location.href =
            `${routes.webUrl}/${project.id}/application`;
    };

    const handleLogout = async () => {
        const confirmed = window.confirm(
            "Are you sure you want to log out?"
        );

        if (!confirmed || loggingOut) {
            return;
        }

        try {
            setLoggingOut(true);

            const response = await fetch("/api/logout", {
                method: "GET",
                headers: {
                    Accept: "application/json",
                    Authorization: `Bearer ${routes.__token}`,
                },
            });

            if (!response.ok) {
                throw new Error("Unable to log out");
            }

            /*
            * Cambia /login si tu ruta real de inicio
            * de sesión utiliza otro nombre.
            */
            window.location.href = `${routes.webUrl}/login`;
        } catch (error) {
            console.error("LOGOUT ERROR:", error);

            alert(
                error?.message ||
                "Unable to log out. Please try again."
            );
        } finally {
            setLoggingOut(false);
        }
    };

    const renderProjectItem = (project) => {
        const isCurrent =
            Number(project.id) ===
            Number(workspace.current_project?.id);

        return (
            <button
                type="button"
                key={project.id}
                className={`workspace-list-card ${
                    isCurrent ? "is-current" : ""
                }`}
                onClick={() => handleProjectClick(project)}
            >
                <div className="workspace-card-icon">
                    <i className="fa-light fa-folder"></i>
                </div>

                <div className="workspace-card-content">
                    <div className="workspace-card-title-row">
                        <strong>{project.name}</strong>

                        {isCurrent && (
                            <span className="workspace-current-badge">
                                Current
                            </span>
                        )}
                    </div>

                    <span className="workspace-card-description">
                        {project.plans_count || 0} plans
                    </span>
                </div>

                <i className="fa-light fa-chevron-right"></i>
            </button>
        );
    };

    const renderWorkspaceItem = (item) => {
        let detail = "";

        if (activeTab === "equipments") {
            detail = item.cost_per_day
                ? `$${Number(item.cost_per_day).toFixed(2)} / day`
                : "No daily cost";
        }

        if (activeTab === "materials") {
            detail =
                item.description ||
                item.default_unit ||
                "No description";
        }

        if (activeTab === "crews") {
            detail = item.description || "Project crew";
        }

        return (
            <button
                type="button"
                key={item.id}
                className="workspace-list-card"
                onClick={() => {
                    const formRoute = phpFormRoutes[activeTab];

                    if (!formRoute || !item?.id) {
                        return;
                    }

                    openPhpModal(
                        `Edit ${singularLabel[activeTab]}`,
                        formRoute.edit(item.id)
                    );
                }}
            >
                <div className="workspace-card-icon">
                    <i
                        className={`fa-light ${
                            tabs.find(
                                (tab) => tab.key === activeTab
                            )?.icon
                        }`}
                    ></i>
                </div>

                <div className="workspace-card-content">
                    <strong>{item.name}</strong>

                    <span className="workspace-card-description">
                        {detail}
                    </span>
                </div>

                <i className="fa-light fa-pen"></i>
            </button>
        );
    };

    if (!isOpen) {
        return null;
    }

    return (
        <>
            <div
                className="workspace-backdrop"
                onClick={onClose}
            ></div>

            <aside className="workspace-panel">
                <header className="workspace-header">
                    <div>
                        <h3>Workspace</h3>

                        <span>
                            Manage project resources
                        </span>
                    </div>

                    <button
                        type="button"
                        className="workspace-close"
                        onClick={onClose}
                    >
                        <i className="fa-light fa-xmark"></i>
                    </button>
                </header>

                <section className="workspace-current-project">
                    <span>Current project</span>

                    <strong>
                        {workspace.current_project?.name ||
                            "No project selected"}
                    </strong>
                </section>

                <nav className="workspace-tabs">
                    {tabs.map((tab) => (
                        <button
                            type="button"
                            key={tab.key}
                            className={
                                activeTab === tab.key
                                    ? "active"
                                    : ""
                            }
                            onClick={() => setActiveTab(tab.key)}
                        >
                            <i
                                className={`fa-light ${tab.icon}`}
                            ></i>

                            <span className="workspace-tab-label">
                                {tab.label}

                                <small>
                                    {Array.isArray(workspace[tab.key])
                                        ? workspace[tab.key].length
                                        : 0}
                                </small>
                            </span>
                        </button>
                    ))}
                </nav>

                <section className="workspace-body">
                    <div className="workspace-toolbar">
                        <div className="workspace-search">
                            <i className="fa-light fa-magnifying-glass"></i>

                            <input
                                type="text"
                                value={search}
                                onChange={(event) =>
                                    setSearch(event.target.value)
                                }
                                placeholder={`Search ${
                                    tabs
                                        .find(
                                            (tab) =>
                                                tab.key === activeTab
                                        )
                                        ?.label.toLowerCase() || ""
                                }...`}
                            />
                        </div>

                        <button
                            type="button"
                            className="workspace-add-button"
                            onClick={() => {
                                if (activeTab === "projects") {
                                    onCreateProject();
                                    return;
                                }

                                const formRoute = phpFormRoutes[activeTab];

                                if (!formRoute) {
                                    return;
                                }

                                openPhpModal(
                                    `Create ${singularLabel[activeTab]}`,
                                    formRoute.create
                                );
                            }}
                        >
                            <i className="fa-light fa-plus"></i>

                            <span>
                                {activeTab === "projects"
                                    ? "New Project"
                                    : `New ${
                                          singularLabel[activeTab]
                                      }`}
                            </span>
                        </button>
                    </div>

                    <div className="workspace-list">
                        {workspaceError ? (
                        <div className="workspace-state workspace-error-state">
                            <i className="fa-light fa-triangle-exclamation"></i>

                            <strong>Unable to load workspace</strong>

                            <span>{workspaceError}</span>

                            <button
                                type="button"
                                className="workspace-retry-button"
                                onClick={loadWorkspace}
                            >
                                <i className="fa-light fa-rotate-right"></i>
                                Retry
                            </button>
                        </div>
                    ) :loading ? (
                            <div className="workspace-state">
                                <i className="fa-light fa-spinner-third fa-spin"></i>
                                <strong>Loading...</strong>
                            </div>
                        ) : currentItems.length === 0 ? (
                            <div className="workspace-state">
                                <i
                                    className={`fa-light ${
                                        tabs.find(
                                            (tab) =>
                                                tab.key === activeTab
                                        )?.icon
                                    }`}
                                ></i>

                                <strong>
                                    No{" "}
                                    {tabs
                                        .find(
                                            (tab) =>
                                                tab.key === activeTab
                                        )
                                        ?.label.toLowerCase()}{" "}
                                    found
                                </strong>

                                <span>
                                    No {tabs
                                        .find((tab) => tab.key === activeTab)
                                        ?.label.toLowerCase()} are assigned to this project.
                                </span>
                            </div>
                        ) : activeTab === "projects" ? (
                            currentItems.map(renderProjectItem)
                        ) : (
                            currentItems.map(renderWorkspaceItem)
                        )}
                    </div>
                </section>

                <footer className="workspace-footer">
                    <div className="workspace-footer-info">
                        <i className="fa-light fa-circle-info"></i>

                        <span>
                            Equipment, materials and crews affect only
                            the current project.
                        </span>
                    </div>

                    <button
                        type="button"
                        className="workspace-logout-button"
                        onClick={handleLogout}
                        disabled={loggingOut}
                    >
                        <i
                            className={
                                loggingOut
                                    ? "fa-light fa-spinner-third fa-spin"
                                    : "fa-light fa-arrow-right-from-bracket"
                            }
                        ></i>

                        <span>
                            {loggingOut ? "Logging out..." : "Logout"}
                        </span>
                    </button>
                </footer>
            </aside>
        
        {phpModal.open && (
            <div
                className="workspace-php-modal-backdrop"
                onMouseDown={(event) => {
                    if (event.target === event.currentTarget) {
                        closePhpModal(true);
                    }
                }}
            >
                <div className="workspace-php-modal">
                    <header className="workspace-php-modal-header">
                        <div>
                            <h4>{phpModal.title}</h4>

                            <span>
                                Current project:{" "}
                                {workspace.current_project?.name || ""}
                            </span>
                        </div>

                        <button
                            type="button"
                            onClick={() => closePhpModal(true)}
                        >
                            <i className="fa-light fa-xmark"></i>
                        </button>
                    </header>

                    <div className="workspace-php-modal-body">
                        <iframe
                            key={phpModal.url}
                            src={phpModal.url}
                            title={phpModal.title}
                            className="workspace-php-iframe"
                            onLoad={(event) => {
                                try {
                                    const iframeWindow =
                                        event.currentTarget.contentWindow;

                                    const iframePath =
                                        iframeWindow.location.pathname;

                                    /*
                                    * Si create/edit redirecciona al index
                                    * después de guardar, recargamos la lista.
                                    */
                                    const isFormPage =
                                        iframePath.includes("/create") ||
                                        iframePath.includes("/edit") ||
                                        iframePath.includes("/add");

                                    if (iframePath && !isFormPage) {
                                        closePhpModal(true);
                                    }
                                } catch (error) {
                                    /*
                                    * Ignorar si el navegador restringe
                                    * el acceso al iframe.
                                    */
                                }
                            }}
                        ></iframe>
                    </div>
                </div>
            </div>
        )}
        </>
    );
}

export default WorkspacePanel;