import { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { Document, Page, pdfjs } from "react-pdf";
import Swal from "sweetalert2";
import PageSelectorPopup from "./PageSelectorPopup";

import { routes, projectId, MAX_FILE_SIZE, MAX_FILE_SIZE_MB } from "../Constants";
import axios from "axios";
import useSignal from "../hooks/signals";
import { PDFDocument } from "pdf-lib";

// PDF.js worker
pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.mjs`;

const swalOk = (title, text = "") =>
  Swal.fire({
    icon: "success",
    title,
    text,
    timer: 2200,
    showConfirmButton: false,
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  });

const swalWarn = (title, text = "") =>
  Swal.fire({
    icon: "warning",
    title,
    text,
    confirmButtonText: "OK",
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  });

const swalErr = (title, text = "") =>
  Swal.fire({
    icon: "error",
    title,
    text,
    confirmButtonText: "OK",
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  });

/* =========================
   Lazy-load thumb
========================= */
function useInView(options) {
  const [inView, setInView] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const obs = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      options || { root: null, rootMargin: "800px", threshold: 0.01 }
    );

    obs.observe(el);
    return () => obs.disconnect();
  }, [options]);

  return { ref, inView };
}

function LazyFileThumb({ item, selected, onToggle, onClickInfo, onLoadSuccess }) {
  const { ref, inView } = useInView({ rootMargin: "800px", threshold: 0.01 });
  const pagesInfo = item.pages?.length ? `${item.pages.length} pages selected` : "Full file";

  return (
    <div
      ref={ref}
      style={{
        width: 180,
        border: selected ? "2px solid #0d6efd" : "1px solid #ccc",
        borderRadius: 8,
        background: "#fff",
        boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
        padding: 10,
        textAlign: "center",
        cursor: "pointer",
        position: "relative",
        opacity: item.disabled ? 0.55 : 1,
        pointerEvents: item.disabled ? "none" : "auto",
      }}
      onClick={onClickInfo}
      title="Click to select pages"
    >
      <h6
        style={{
          fontSize: 12,
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
          marginBottom: 6,
        }}
        title={item.name}
      >
        {item.name}
      </h6>

      <p style={{ fontSize: 11, color: "#666", margin: 0 }}>{item.size}</p>

      <div
        style={{
          height: 160,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          margin: "6px 0",
          background: "#f8f9fa",
        }}
      >
        {inView ? (
          <Document
            file={item.url}
            loading={<p style={{ fontSize: 11 }}>Loading…</p>}
            error={<p style={{ fontSize: 11 }}>Failed to load PDF.</p>}
            onLoadSuccess={({ numPages }) => onLoadSuccess(numPages)}
          >
            <Page
              pageNumber={1}
              width={140}
              renderTextLayer={false}
              renderAnnotationLayer={false}
            />
          </Document>
        ) : (
          <span style={{ fontSize: 11, color: "#999" }}>Loading preview...</span>
        )}
      </div>

      <div style={{ marginTop: 6, fontSize: 11, color: item.pages?.length ? "#0d6efd" : "#6c757d" }}>
        {pagesInfo}
      </div>

      <label
        style={{ fontSize: 12, cursor: "pointer", display: "inline-block", marginTop: 6 }}
        onClick={(e) => e.stopPropagation()}
      >
        <input
          type="checkbox"
          checked={selected}
          onChange={() => onToggle(item.name)}
          style={{ marginRight: 4 }}
        />
        Select
      </label>
    </div>
  );
}

/* =========================
   Upload helpers (MISMO FLOW que PdfPreviewPopup)
========================= */
const sanitizeForFilename = (s) =>
  String(s || "")
    .replace(/[\\/:*?"<>|]/g, "-")
    .replace(/\s+/g, " ")
    .trim();

const getPdfBaseName = (pdfName) => {
  const safe = sanitizeForFilename(pdfName || "document.pdf");
  return safe.replace(/\.pdf$/i, "");
};

const getFinalCodeFor = (pageNumber, pageCodes) => {
  const override = pageCodes?.[pageNumber];
  if (override && String(override).trim()) return String(override).trim();
  return `PAGE-${pageNumber}`;
};

const buildPdfWithSelectedPages = async (inputFile, pages1based) => {
  const srcBytes = await inputFile.arrayBuffer();
  const srcDoc = await PDFDocument.load(srcBytes);
  const total = srcDoc.getPageCount();

  const indices = pages1based
    .map((p) => parseInt(p, 10) - 1)
    .filter((i) => Number.isInteger(i) && i >= 0 && i < total);

  if (!indices.length) throw new Error("No valid pages selected.");

  const newDoc = await PDFDocument.create();
  const copied = await newDoc.copyPages(srcDoc, indices);
  copied.forEach((p) => newDoc.addPage(p));

  const outBytes = await newDoc.save();
  return new File([outBytes], inputFile.name || "document.pdf", { type: "application/pdf" });
};

const getAllPages1Based = async (pdfFile) => {
  const bytes = await pdfFile.arrayBuffer();
  const doc = await PDFDocument.load(bytes);
  const n = doc.getPageCount();
  return Array.from({ length: n }, (_, i) => i + 1);
};

const generateAndUploadPngBlocks = async ({
  pdfFile,
  pages1based,
  pageCodes,
  setWorkLabel,
  setDoneCount,
  setTotalCount,
  chunkSize = 20,
}) => {
  const buf = await pdfFile.arrayBuffer();
  const task = pdfjs.getDocument({ data: buf });
  const pdf = await task.promise;

  const pdfBase = getPdfBaseName(pdfFile.name);
  const SCALE = 1.15;

  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d", { alpha: false });

  const total = pages1based.length;
  setTotalCount(total);
  setDoneCount(0);

  // renumeración: si seleccionas páginas, que queden P1..Pn (MISMO QUE PdfPreviewPopup)
  const newIndexByOriginal = new Map(
    pages1based.map((originalPage, idx) => [originalPage, idx + 1])
  );

  for (let start = 0; start < total; start += chunkSize) {
    const chunk = pages1based.slice(start, start + chunkSize);

    setWorkLabel(`Generating PNGs ${start + 1}-${start + chunk.length} of ${total}…`);

    const formData = new FormData();
    formData.append("project_id", projectId);
    formData.append("pdf_name", pdfFile.name || "document.pdf");
    formData.append("pages", JSON.stringify(chunk));

    formData.append(
      "page_codes",
      JSON.stringify(
        chunk.map((p) => ({
          page: p,
          code: getFinalCodeFor(p, pageCodes),
        }))
      )
    );

    for (const pageNum of chunk) {
      const page = await pdf.getPage(pageNum);
      const viewport = page.getViewport({ scale: SCALE });

      canvas.width = Math.floor(viewport.width);
      canvas.height = Math.floor(viewport.height);

      await page.render({ canvasContext: ctx, viewport }).promise;

      const finalCode = getFinalCodeFor(pageNum, pageCodes);
      const safeCode = sanitizeForFilename(finalCode);

      const newP = newIndexByOriginal.get(pageNum) || pageNum;
      const filename = `${pdfBase}__${safeCode}__P${newP}.webp`;

      const thumbCanvas = document.createElement("canvas");
      const thumbCtx = thumbCanvas.getContext("2d");

      thumbCanvas.width = 500;
      thumbCanvas.height = 500;

      thumbCtx.fillStyle = "#ffffff";
      thumbCtx.fillRect(0, 0, 500, 500);

      const scale = Math.min(
          500 / canvas.width,
          500 / canvas.height
      );

      const drawWidth = canvas.width * scale;
      const drawHeight = canvas.height * scale;

      thumbCtx.drawImage(
          canvas,
          (500 - drawWidth) / 2,
          (500 - drawHeight) / 2,
          drawWidth,
          drawHeight
      );

      const blob = await new Promise((resolve, reject) => {
          thumbCanvas.toBlob(
              (b) => (b ? resolve(b) : reject(new Error("Could not generate WEBP"))),
              "image/webp",
              4
          );
      });

      formData.append("pngs[]", new File([blob], filename, { type: "image/webp" }));
      setDoneCount((prev) => prev + 1);
    }

    setWorkLabel(`Uploading block ${start + 1}-${start + chunk.length}…`);

    await axios.post(routes.upload_png_chunk, formData, {
      headers: { Authorization: `Bearer ${routes.__token}` },
    });

    await new Promise((r) => setTimeout(r, 0));
  }

  canvas.width = 1;
  canvas.height = 1;
};

export default function FolderPreviewPopup({ files, onClose }) {
  const signal = useSignal();

  const [selectedFiles, setSelectedFiles] = useState([]); // names
  const [previews, setPreviews] = useState([]); // items
  const [activeFile, setActiveFile] = useState(null);

  // opcional AI global (lo tienes ya, lo dejo igual)
  const [shouldAnalyze, setShouldAnalyze] = useState(null);
  const askedRef = useRef(false);

  // ✅ estilo PdfPreviewPopup (banner de trabajo dentro del popup)
  const [working, setWorking] = useState(false);
  const [workLabel, setWorkLabel] = useState("");
  const [doneCount, setDoneCount] = useState(0);
  const [totalCount, setTotalCount] = useState(0);

  // progress por archivo (barra 0-100 durante upload PDF)
  const [pdfPercent, setPdfPercent] = useState(0);

  useEffect(() => {
    if (!files?.length) return;

    const mapped = files.map((f) => ({
      name: f.name,
      size: (f.size / 1024 / 1024).toFixed(2) + " MB",
      file: f,
      url: URL.createObjectURL(f),

      pages: [],           // vacío = ALL
      upload_all_pages: true,
      numPages: null,
      pageCodes: {},
      analyzedCodes: null,

      disabled: false, // UI lock individual if needed
    }));

    setPreviews(mapped);
    setSelectedFiles(files.map((f) => f.name));
  }, [files]);

  // cleanup URLs
  useEffect(() => {
    return () => {
      previews.forEach((p) => {
        try { URL.revokeObjectURL(p.url); } catch (e) { }
      });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // (si quieres reactivar el SweetAlert “Find code / Just upload”, descomenta)
  /*
  useEffect(() => {
    if (!files?.length) return;
    if (askedRef.current) return;

    askedRef.current = true;

    Swal.fire({
      title: "What do you want to do?",
      html:
        "<div style='text-align:left;font-size:14px;line-height:1.4'>" +
        "<b>Find code (AI)</b>: detects a code per page (may take a bit).<br/>" +
        "<b>Just select and upload</b>: no analysis, pages will be named PAGE-n if no code exists." +
        "</div>",
      icon: "question",
      showCancelButton: true,
      confirmButtonText: "Find code",
      cancelButtonText: "Just upload",
      reverseButtons: true,
      allowOutsideClick: false,
      allowEscapeKey: false,
      didOpen: () => {
        const el = document.querySelector(".swal2-container");
        if (el) el.style.zIndex = "250000";
      },
    }).then((res) => {
      if (res.isConfirmed) setShouldAnalyze(true);
      else setShouldAnalyze(false);
    });
  }, [files]);
  */

  // AI analysis (opcional)
  useEffect(() => {
    if (!files?.length) return;
    if (shouldAnalyze !== true) return;

    let cancelled = false;

    const run = async () => {
      try {
        setWorking(true);
        setWorkLabel("Analyzing PDFs to detect codes per page…");
        setDoneCount(0);
        setTotalCount(previews.length);

        const next = [...previews];

        for (let i = 0; i < next.length; i++) {
          if (cancelled) break;
          const item = next[i];

          setWorkLabel(`Analyzing: ${item.name} (${i + 1}/${next.length})…`);

          try {
            const formData = new FormData();
            formData.append("file", item.file);
            formData.append("project_id", projectId);

            const resp = await axios.post(routes.analyze_pdf, formData, {
              headers: { Authorization: `Bearer ${routes.__token}` },
            });

            const arr = Array.isArray(resp.data) ? resp.data : [];
            const codes = {};
            arr.forEach((x) => {
              if (x?.page && x?.code) codes[Number(x.page)] = String(x.code);
            });

            next[i] = {
              ...item,
              analyzedCodes: codes,
              pageCodes: Object.keys(item.pageCodes || {}).length ? item.pageCodes : codes,
            };
          } catch (e) {
            console.error("AI analyze error:", item.name, e);
          }

          setDoneCount((c) => c + 1);
          await new Promise((r) => setTimeout(r, 0));
        }

        if (!cancelled) {
          setPreviews(next);
          await swalOk("✅ Done", "AI scan completed. You can still edit codes manually per page.");
        }
      } catch (e) {
        console.error(e);
        await swalErr("Could not analyze the folder PDFs.");
      } finally {
        if (!cancelled) {
          setWorking(false);
          setWorkLabel("");
          setDoneCount(0);
          setTotalCount(0);
        }
      }
    };

    run();
    return () => (cancelled = true);
  }, [shouldAnalyze, previews, files]);

  const toggleFile = (name) => {
    setSelectedFiles((prev) =>
      prev.includes(name) ? prev.filter((n) => n !== name) : [...prev, name]
    );
  };

  const selectAll = () => {
    if (selectedFiles.length === previews.length) setSelectedFiles([]);
    else setSelectedFiles(previews.map((p) => p.name));
  };

  const handleOpenPageSelector = (previewItem) => setActiveFile(previewItem);

  const handleSavePages = async (result) => {
    const selectedPages = Array.isArray(result?.selectedPages) ? result.selectedPages : [];
    const upload_all_pages = !!result?.upload_all_pages || selectedPages.length === 0;
    const pageCodes = result?.pageCodes || {};

    setPreviews((prev) =>
      prev.map((p) => {
        if (p.name !== activeFile.name) return p;
        return { ...p, pages: selectedPages, upload_all_pages, pageCodes };
      })
    );

    if (upload_all_pages) await swalOk("✅ Listo", "No seleccionaste páginas: se subirán TODAS.");
    else await swalOk("✅ Páginas guardadas", `Se subirán ${selectedPages.length} páginas de este archivo.`);

    setActiveFile(null);
  };

  const selectedPreviewItems = useMemo(
    () => previews.filter((p) => selectedFiles.includes(p.name)),
    [previews, selectedFiles]
  );

  // ✅ UPLOAD DENTRO DEL POPUP (MISMO UX QUE PdfPreviewPopup)
  const handleUploadSelectedInsidePopup = async () => {
    try {
      if (!selectedPreviewItems.length) {
        await swalWarn("Select at least one file.", "No files selected for upload.");
        return;
      }

      const totalFiles = selectedPreviewItems.length;
      const filesAllPages = selectedPreviewItems.filter((p) => !p.pages?.length).length;

      const html =
        "<div style='text-align:left;font-size:14px;line-height:1.4'>" +
        `<b>Files:</b> ${totalFiles}<br/>` +
        `<b>Files without selected pages:</b> ${filesAllPages} <span style='color:#6c757d'>(will be uploaded completely)</span><br/>` +
        "<hr style='margin:10px 0'/>" +
        "The PDF will be uploaded first and then PNGs in blocks of 20 (like PdfPreviewPopup).<br/>" +
        "Do you want to continue?" +
        "</div>";

      const res = await Swal.fire({
        title: "Confirm upload",
        html,
        icon: "question",
        showCancelButton: true,
        confirmButtonText: "Yes, upload",
        cancelButtonText: "Cancel",
        reverseButtons: true,
        allowOutsideClick: false,
        allowEscapeKey: false,
        didOpen: () => {
          const el = document.querySelector(".swal2-container");
          if (el) el.style.zIndex = "250000";
        },
      });

      if (!res.isConfirmed) return;

      setWorking(true);
      setPdfPercent(0);
      setDoneCount(0);
      setTotalCount(0);

      // bloquea UI de cards
      setPreviews((prev) => prev.map((p) => ({ ...p, disabled: true })));

      for (let i = 0; i < selectedPreviewItems.length; i++) {
        const item = selectedPreviewItems[i];
        const fileIndex = i + 1;

        if (item.file.size > MAX_FILE_SIZE) {
          await swalWarn(
            "File too large",
            `"${item.name}" exceeds the maximum allowed size (${MAX_FILE_SIZE_MB} MB). It will be skipped.`
          );
          continue;
        }

        // pages to upload:
        let pagesToUpload = Array.isArray(item.pages) ? item.pages : [];
        const uploadAll = !pagesToUpload.length;

        if (uploadAll) {
          setWorkLabel(`Reading pages: ${item.name} (${fileIndex}/${selectedPreviewItems.length})…`);
          pagesToUpload = await getAllPages1Based(item.file);
        }

        // 1) Trim PDF si NO es all (igual que PdfPreviewPopup)
        let pdfToSend = item.file;
        if (!uploadAll) {
          setWorkLabel(`Trimming PDF: ${item.name} (${fileIndex}/${selectedPreviewItems.length})…`);
          pdfToSend = await buildPdfWithSelectedPages(item.file, pagesToUpload);
        }

        // 2) Upload PDF
        setWorkLabel(`Uploading PDF: ${item.name} (${fileIndex}/${selectedPreviewItems.length})…`);
        setPdfPercent(0);

        const pdfForm = new FormData();
        pdfForm.append("file", pdfToSend);
        pdfForm.append("project_id", projectId);

        await axios.post(routes.upload, pdfForm, {
          headers: { Authorization: `Bearer ${routes.__token}` },
          onUploadProgress: (e) => {
            const p = Math.round((e.loaded * 100) / e.total);
            setPdfPercent(p);
          },
        });

        // 3) PNG blocks (20) + upload blocks (igual que PdfPreviewPopup)
        setWorkLabel(`Generating PNGs: ${item.name} (${fileIndex}/${selectedPreviewItems.length})…`);

        await generateAndUploadPngBlocks({
          pdfFile: item.file,                 // generamos del ORIGINAL
          pages1based: pagesToUpload,
          pageCodes: item.pageCodes || {},
          setWorkLabel,
          setDoneCount,
          setTotalCount,
          chunkSize: 20,
        });

        // pequeño respiro (UX)
        await new Promise((r) => setTimeout(r, 0));
      }

      await swalOk("✅ Done", "PDF(s) and PNG(s) uploaded in blocks.");
      signal.emit("refresh");
      onClose();
    } catch (e) {
      console.error(e);
      await swalErr(e?.message || "Upload failed.");
    } finally {
      setWorking(false);
      setWorkLabel("");
      setDoneCount(0);
      setTotalCount(0);
      setPdfPercent(0);

      setPreviews((prev) => prev.map((p) => ({ ...p, disabled: false })));
    }
  };

  return createPortal(
    <>
      <Draggable handle=".modal-header">
        <div
          className="popup__count"
          style={{
            zIndex: 9999,
            position: "fixed",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: "90%",
            maxWidth: "1000px",
            background: "#fff",
            borderRadius: "8px",
            boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
            overflow: "hidden",
          }}
        >
          <div
            className="modal-header"
            style={{
              background: "#343a40",
              color: "#fff",
              cursor: "move",
              padding: "10px 15px",
              fontWeight: "bold",
            }}
          >
            Folder Preview
            <span
              onClick={() => {
                if (!working) onClose();
              }}
              style={{
                cursor: working ? "not-allowed" : "pointer",
                float: "right",
                fontSize: "18px",
                fontWeight: "bold",
                opacity: working ? 0.4 : 1,
              }}
              title={working ? "Uploading… please wait" : "Close"}
            >
              ×
            </span>
          </div>

          <div
            className="modal-body"
            style={{
              maxHeight: "70vh",
              overflowY: "auto",
              background: "#f8f9fa",
              padding: "15px",
            }}
          >
            {working && (
              <div
                style={{
                  background: "#e7f1ff",
                  border: "1px solid #cfe2ff",
                  color: "#084298",
                  padding: 10,
                  borderRadius: 8,
                  marginBottom: 10,
                  textAlign: "center",
                  fontSize: 13,
                }}
              >
                <div>
                  <b>{workLabel || "Working…"}</b>
                </div>

                {pdfPercent > 0 && pdfPercent < 100 && (
                  <div style={{ marginTop: 8 }}>
                    <div style={{ fontSize: 12, marginBottom: 6 }}>PDF upload: {pdfPercent}%</div>
                    <progress
                      value={pdfPercent}
                      max={100}
                      style={{ width: 360, height: 14, borderRadius: 8, overflow: "hidden" }}
                    />
                  </div>
                )}

                {totalCount > 0 && (
                  <div style={{ marginTop: 8 }}>
                    PNG progress: {doneCount} / {totalCount}
                  </div>
                )}
              </div>
            )}

            <div style={{ textAlign: "center", marginBottom: 10 }}>
              <button
                onClick={selectAll}
                disabled={working}
                style={{
                  background: "transparent",
                  border: "1px solid #0d6efd",
                  color: "#0d6efd",
                  padding: "6px 12px",
                  borderRadius: "4px",
                  cursor: working ? "not-allowed" : "pointer",
                  opacity: working ? 0.6 : 1,
                }}
              >
                {selectedFiles.length === previews.length ? "Deselect all" : "Select all"}
              </button>

              <div style={{ marginTop: 8, fontSize: 12, color: "#6c757d" }}>
                Tip: Click on a card to choose pages + codes. If you select no pages → file uploads complete.
              </div>
            </div>

            <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: 15 }}>
              {previews.map((p, idx) => {
                const isSelected = selectedFiles.includes(p.name);
                return (
                  <LazyFileThumb
                    key={idx}
                    item={p}
                    selected={isSelected}
                    onToggle={toggleFile}
                    onClickInfo={() => handleOpenPageSelector(p)}
                    onLoadSuccess={(num) => {
                      setPreviews((prev) =>
                        prev.map((x) => (x.name === p.name ? { ...x, numPages: num } : x))
                      );
                    }}
                  />
                );
              })}
            </div>
          </div>

          <div
            className="modal-footer"
            style={{
              display: "flex",
              justifyContent: "flex-end",
              gap: 10,
              background: "#f1f1f1",
              borderTop: "1px solid #ccc",
              padding: "10px 15px",
            }}
          >
            <button
              onClick={onClose}
              className="btn btn-secondary"
              disabled={working}
              style={{ pointerEvents: working ? "none" : "auto" }}
            >
              Cancel
            </button>

            <button
              onClick={handleUploadSelectedInsidePopup}
              className="btn btn-primary"
              disabled={working}
              style={{ pointerEvents: working ? "none" : "auto" }}
            >
              Upload selected ({selectedFiles.length})
            </button>
          </div>
        </div>
      </Draggable>

      {activeFile && (
        <PageSelectorPopup
          file={activeFile}
          projectId={projectId}
          onAnalyzeCodes={async (f) => {
            const formData = new FormData();
            formData.append("file", f.file || f);
            formData.append("project_id", projectId);

            const resp = await axios.post(routes.analyze_pdf, formData, {
              headers: { Authorization: `Bearer ${routes.__token}` },
            });

            const arr = Array.isArray(resp.data) ? resp.data : [];
            const codes = {};
            arr.forEach((x) => {
              if (x?.page && x?.code) codes[Number(x.page)] = String(x.code);
            });

            return { codes };
          }}
          onClose={() => setActiveFile(null)}
          onSave={handleSavePages}
        />
      )}
    </>,
    document.getElementById("root")
  );
}
