  useEffect(() => {
    let abort = false;

    async function fetchAllCourses() {
      setLoadingCourses(true);
      setErrorCourses(null);

      try {
        let url = `/api/course-bands?per_page=200`; // ajusta per_page si lo necesitas
        const all = [];

        while (url && !abort) {
          const res = await fetch(url, {
            headers: {
              Accept: "application/json",
              Authorization: `Bearer ${routes.__token}`, // si tu API lo requiere
            },
          });
          if (!res.ok) throw new Error(`HTTP ${res.status}`);

          const page = await res.json();

          // Si tu endpoint usa paginate() de Laravel => items en page.data
          // Si devuelve un array plano => Ãºsalo tal cual.
          const items = Array.isArray(page?.data)
            ? page.data
            : Array.isArray(page)
              ? page
              : [];

          // Normaliza: mezcla metacampos con el JSON "data"
          const normalized = items.map((row) => {
            // Parseo seguro de row.data (string JSON)
            let payload = {};
            try {
              payload = typeof row?.data === 'string' ? JSON.parse(row.data) : (row?.data ?? {});
            } catch (e) {
              payload = {};
            }

            // Normaliza tipos (opcional, pero Ãºtil)
            const toNum = (v) => {
              const n = Number(v);
              return Number.isFinite(n) ? n : 0;
            };

            return {
              // datos del curso (ya parseados)
              ...payload,
              // normaliza nÃºmeros que usarÃ¡s en la UI/cÃ¡lculos
              top_elevation: toNum(payload?.top_elevation),
              band_height: toNum(payload?.band_height),

              // metadatos
              id: row.id,                        // o String(row.id) si comparas como string
              id_local: String(row.id_local ?? ''), // viene como "1"
              id_user: row.id_user,
              is_global: row.is_global,
              created_at: row.created_at,
              updated_at: row.updated_at,
            };
          });

          all.push(...normalized);

          // Siguiente pÃ¡gina si usas paginate()
          url = page?.next_page_url || null;
        }

        if (!abort) {
          setCourses(all);
          setCourseData((prev) => ({
            ...prev,
            courses: all.map((c) => ({ course: c })),
          }));
        }
      } catch (e) {
        if (!abort) setErrorCourses(e);
      } finally {
        if (!abort) setLoadingCourses(false);
      }
    }

    fetchAllCourses();
    return () => {
      abort = true;
    };
  }, []);

