  const resolverTemplateLength = (value) => {
    if (!value) {
      return null;
    }

    if (typeof value === "object") {
      return value;
    }

    if (typeof value === "string" && value.trim().startsWith("{")) {
      try {
        return JSON.parse(value);
      } catch (error) {
        return null;
      }
    }

    const templateEncontrado = lineTemplate.find((template) => {
      return String(template.id) === String(value);
    });

    return templateEncontrado || null;
  };

  // Update the form inputs to capture user input and update formData
  async function update_line_template(value) {
    if (!value) {
      return null;
    }

    let template = null;

    /*
    * Compatibilidad con datos anteriores:
    * puede venir el objeto completo, JSON o solamente el ID.
    */
    if (typeof value === "object") {
      template = value;
    } else if (
      typeof value === "string" &&
      value.trim().startsWith("{")
    ) {
      try {
        template = JSON.parse(value);
      } catch (error) {
        console.error("Invalid line template JSON:", error);
        return null;
      }
    } else {
      /*
      * Actualmente los dibujos nuevos guardan únicamente el ID.
      * Primero buscamos en los templates que ya están cargados.
      */
      template = lineTemplate.find(
        (item) => String(item.id) === String(value)
      );

      /*
      * En modo takeoff la lista puede no estar cargada,
      * así que obtenemos el template completo desde la API.
      */
      if (!template) {
        try {
          const response = await fetch(
            `/api/get-line-template-by-id/${value}`,
            {
              method: "GET",
              headers: {
                Authorization: `Bearer ${routes.__token}`,
                Accept: "application/json",
              },
            }
          );

          const data = await response.json();

          if (!response.ok || data?.status !== 200 || !data?.template) {
            console.error("Line template could not be loaded:", data);
            return null;
          }

          template = data.template;
        } catch (error) {
          console.error("Error loading line template:", error);
          return null;
        }
      }
    }

    let localDb = template?.local_db ?? {};
    console.log(localDb);
    console.log(typeof localDb);
    
    try {
      if (typeof localDb === "string") {
        localDb = JSON.parse(localDb);
      }
    } catch (error) {
      console.error("Invalid template local_db:", error);
      return null;
    }

    /*
    * Compatibilidad por si local_db fue guardado como:
    * { formData: {...} }
    */
    let templateFormData = localDb?.formData ?? localDb;
    console.log(typeof templateFormData);
    try {
        if (typeof templateFormData === "string") {
            templateFormData = JSON.parse(templateFormData);
        }
    } catch (error) {
        console.error("Invalid template formData:", error);
        return null;
    }

    if (
      !templateFormData ||
      typeof templateFormData !== "object" ||
      Array.isArray(templateFormData)
    ) {
      console.error("Template does not contain valid formData:", template);
      return null;
    }

    const currentSelectedLength = takeoff?.length ?? null;
    const currentSelectedName = takeoff?.name ?? null;
    const currentSelectedIdUnique = takeoff?.idUnique ?? "";
    const lineTemplateId =
      template?.id ??
      takeoff?.lineTemplateId ??
      value;

    const completeFormData = {
      ...templateFormData,
      lineTemplate: lineTemplateId,
      idUnique: currentSelectedIdUnique,
    };

    if (currentSelectedLength !== null) {
      completeFormData.wall_length = currentSelectedLength;
      completeFormData.total_wall_length = currentSelectedLength;
    }

    if (currentSelectedName !== null) {
      completeFormData.name = currentSelectedName;
    }

    setFormData(completeFormData);

    return CalculateData(completeFormData);
  }

  const parseOptionDataset = (target) => {
    const opt = target.selectedOptions?.[0];
    if (!opt) return null;

    // Prioridad: data-item (genÃ©rico)
    const rawItem = opt.dataset?.item;
    if (rawItem) {
      try { return JSON.parse(rawItem); } catch (e) { return null; }
    }

    // Compatibilidad: data-material si lo estÃ¡s usando en algunos
    const rawMaterial = opt.dataset?.material;
    if (rawMaterial) {
      try { return JSON.parse(rawMaterial); } catch (e) { return null; }
    }

    return null;
  };

  const normalizeNumberValue = (target) => {
    // Si quieres que el 0 NO se quede como "0" para que muestre placeholder
    // SOLO aplicamos cuando sea type number y sea exactamente "0"
    if (target.type === "number" && target.value === "0") return "";
    return target.value;
  };

  const handleInputChange = (event) => {
    const target = event.target;
    const { name, tagName } = target;

    // âœ… SELECT: guardamos objeto completo (desde data-item / data-material)
    if (tagName === "SELECT") {
      const value = target.value;

      // placeholder
      if (!value) {
        setFormData((prev) => ({ ...prev, [name]: null }));
        return;
      }

      const obj = parseOptionDataset(target);

      setFormData((prev) => ({
        ...prev,
        [name]: obj ? JSON.stringify(obj) : value,
      }));
      return;
    }

    // âœ… INPUTS normales (text/number/etc)
    const value = normalizeNumberValue(target);

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleInputBlur = (event) => {
    const target = event.target;
    const { name, tagName } = target;

    // ⚠️ Armamos el valor “final” que se debe usar en CalculateData
    let finalValue = null;

    if (tagName === "SELECT") {
      const value = target.value;

      if (!value) {
        finalValue = null; // placeholder
      } else {
        const obj = parseOptionDataset(target);
        finalValue = obj ? JSON.stringify(obj) : value; // objeto completo o valor simple (fallback)
      }
    } else {
      finalValue = normalizeNumberValue(target);
    }

    // ðŸ”¥ IMPORTANTE: Calcula con el formData actualizado (sin estado viejo)
    setFormData((prev) => {
      const updatedFormData = {
        ...prev,
        [name]: finalValue,
      };

      // âœ… AquÃ­ se manda SIEMPRE (como quieres)
      CalculateData(updatedFormData);

      return updatedFormData;
    });
  };


