import { useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { toast } from "react-toastify";
import { projectId, routes } from "../Constants";

const emptyRule = () => ({ material: "", description: "", factor: 1 });

const initialOpening = {
  name: "",
  description: "",
  category: "",
  applicable_to: "wall",
  shape: "Rectangular",
  width: "",
  length: "",
  height: "",
  diameter: "",
  bottom_elevation: "",
  top_elevation: "",
  quantity: 1,
  header_bearing_each_side: 0,
  deduction_material: "",
  header_materials: [],
  perimeter_materials: [],
  adjustmentDatas: [],
  sq_area: 0,
  perimeter: 0,
  total_sq_ft: 0,
  total_perimeter: 0,
  total_header_length: 0,
  totalsDatas: [],
  totales_html: "",
  type: "opening",
};

function parseOpeningTemplate(openingData) {
  if (!openingData) return null;

  let localDb = openingData.local_db ?? openingData;
  if (typeof localDb === "string") {
    try {
      localDb = JSON.parse(localDb);
    } catch (error) {
      console.error("Invalid opening template local_db:", error);
      localDb = {};
    }
  }

  return {
    ...initialOpening,
    ...localDb,
    name: localDb.name ?? openingData.template_name ?? "",
    template_id: openingData.id ?? localDb.template_id ?? null,
    is_global: openingData.is_global ?? localDb.is_global ?? 0,
    width: localDb.width ?? localDb.length ?? "",
    header_materials: localDb.header_materials ?? [],
    perimeter_materials: localDb.perimeter_materials ?? [],
  };
}

function OpeningPopup({ setDisplay, openingData, OpeningValue, takeoff = null }) {
  const [formDataOpening, setFormDataOpening] = useState(initialOpening);
  const [wallMaterials, setWallMaterials] = useState([]);
  const [library, setLibrary] = useState([]);
  const [selectedTemplateId, setSelectedTemplateId] = useState("");
  const [isCalculating, setIsCalculating] = useState(false);

  useEffect(() => {
    const parsed = parseOpeningTemplate(openingData);
    if (parsed) {
      setFormDataOpening(parsed);
      setSelectedTemplateId(parsed.template_id ?? "");
    }
  }, [openingData]);

  const materialOptions = useMemo(
    () =>
      wallMaterials.map((material) => ({
        value: JSON.stringify(material),
        label: material.name,
      })),
    [wallMaterials]
  );

  const loadMaterials = async () => {
    const response = await fetch(`/api/materials/${projectId}`, {
      headers: { Authorization: `Bearer ${routes.__token}` },
    });
    if (response.ok) setWallMaterials(await response.json());
  };

  const loadLibrary = async () => {
    const response = await fetch("/api/get-line-template?type_template=opening", {
      headers: { Authorization: `Bearer ${routes.__token}` },
    });
    if (!response.ok) return;
    const data = await response.json();
    setLibrary(data.template ?? []);
  };

  useEffect(() => {
    loadMaterials().catch((error) => console.error("Opening materials:", error));
    loadLibrary().catch((error) => console.error("Opening library:", error));
  }, []);

  const updateField = (name, value) => {
    setFormDataOpening((current) => ({
      ...current,
      [name]: value,
      ...(name === "width" ? { length: value } : {}),
      ...(name === "applicable_to" && value !== "wall"
        ? { bottom_elevation: "", top_elevation: "" }
        : {}),
    }));
  };

  const updateRule = (collection, index, field, value) => {
    setFormDataOpening((current) => ({
      ...current,
      [collection]: current[collection].map((rule, ruleIndex) =>
        ruleIndex === index ? { ...rule, [field]: value } : rule
      ),
    }));
  };

  const addRule = (collection) => {
    setFormDataOpening((current) => ({
      ...current,
      [collection]: [...current[collection], emptyRule()],
    }));
  };

  const removeRule = (collection, index) => {
    setFormDataOpening((current) => ({
      ...current,
      [collection]: current[collection].filter((_, ruleIndex) => ruleIndex !== index),
    }));
  };

  const calculateData = async (formData = formDataOpening) => {
    if (!formData.name.trim()) {
      toast.warning("Enter an opening name.");
      return null;
    }

    if (formData.applicable_to === "wall" && formData.bottom_elevation === "") {
      toast.warning("Sill Height is required for wall openings.");
      return null;
    }

    setIsCalculating(true);
    try {
      const response = await fetch("/api/CalculateData", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${routes.__token}`,
        },
        body: JSON.stringify({
          template_name: formData.name,
          trade_name: formData.category || "Openings",
          formData,
          type: "opening",
          projectId,
        }),
      });
      const data = await response.json();
      if (!response.ok || data.status !== 200) {
        throw new Error(data.message || "Calculation error");
      }
      setFormDataOpening((current) => ({ ...current, ...data.resultado }));
      return data.resultado;
    } catch (error) {
      toast.error(error.message);
      return null;
    } finally {
      setIsCalculating(false);
    }
  };

  const saveToLibrary = async () => {
    const calculated = await calculateData();
    if (!calculated) return;

    const response = await fetch("/api/save-opening-template", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${routes.__token}`,
      },
      body: JSON.stringify({
        template_id:
          formDataOpening.template_id ??
          takeoff?.templateId ??
          selectedTemplateId ??
          null,
        template_name: calculated.name,
        formData: calculated,
        is_global:
          formDataOpening.is_global ??
          takeoff?.is_global ??
          false,
      }),
    });

    if (!response.ok) {
      toast.error("The opening could not be saved.");
      return;
    }

    await loadLibrary();
    toast.success(
      formDataOpening.template_id
        ? "Opening template updated."
        : "Opening saved in the library."
    );
  };

  const selectLibraryOpening = async (templateId) => {
    setSelectedTemplateId(templateId);
    if (!templateId) return;

    const response = await fetch(`/api/get-opening-template-by-id/${templateId}`, {
      headers: { Authorization: `Bearer ${routes.__token}` },
    });
    if (!response.ok) return;

    const data = await response.json();
    const localDb =
      typeof data.template.local_db === "string"
        ? JSON.parse(data.template.local_db)
        : data.template.local_db;

    setFormDataOpening({ ...initialOpening, ...localDb });
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    const calculated = await calculateData();
    if (!calculated) return;
    localStorage.setItem("savedFormDataOpening", JSON.stringify(calculated));
    toast.success("Opening data saved.");
    setDisplay(false);
  };

  const renderMaterialSelect = (value, onChange) => (
    <select value={value || ""} onChange={(event) => onChange(event.target.value)}>
      <option value="">-- Select Material --</option>
      {materialOptions.map((material) => (
        <option key={material.value} value={material.value}>
          {material.label}
        </option>
      ))}
    </select>
  );

  const renderRules = (collection, title) => (
    <fieldset>
      <legend>{title}</legend>
      {formDataOpening[collection].map((rule, index) => (
        <div className="opening-material-rule" key={`${collection}-${index}`}>
          {renderMaterialSelect(rule.material, (value) =>
            updateRule(collection, index, "material", value)
          )}
          <input
            type="text"
            placeholder="Description"
            value={rule.description}
            onChange={(event) =>
              updateRule(collection, index, "description", event.target.value)
            }
          />
          <input
            type="number"
            min="0"
            step="0.01"
            title="Quantity factor"
            value={rule.factor}
            onChange={(event) => updateRule(collection, index, "factor", event.target.value)}
          />
          <button type="button" onClick={() => removeRule(collection, index)}>
            Remove
          </button>
        </div>
      ))}
      <button type="button" onClick={() => addRule(collection)}>
        Add Material
      </button>
    </fieldset>
  );

  return createPortal(
    <Draggable handle=".modal-header">
      <div className="popup__count opening-popup">
        <div className="modal-header">
          Opening Library
          <span className="close-btn" onClick={() => setDisplay(false)}>
            &times;
          </span>
        </div>

        <form className="modal-body" onSubmit={handleSubmit}>
          <label>Library</label>
          <select
            value={selectedTemplateId}
            onChange={(event) => selectLibraryOpening(event.target.value)}
          >
            <option value="">New Opening</option>
            {library.map((template) => (
              <option key={template.id} value={template.id}>
                {template.template_name}
              </option>
            ))}
          </select>

          <label>Name</label>
          <input
            required
            value={formDataOpening.name}
            onChange={(event) => updateField("name", event.target.value)}
          />

          <label>Description</label>
          <textarea
            value={formDataOpening.description}
            onChange={(event) => updateField("description", event.target.value)}
          />

          <label>Category</label>
          <input
            value={formDataOpening.category}
            onChange={(event) => updateField("category", event.target.value)}
          />

          <label>Applicable To</label>
          <select
            value={formDataOpening.applicable_to}
            onChange={(event) => updateField("applicable_to", event.target.value)}
          >
            <option value="wall">Wall</option>
            <option value="slab">Slab</option>
            <option value="roof">Roof</option>
          </select>

          <label>Shape</label>
          <select
            value={formDataOpening.shape}
            onChange={(event) => updateField("shape", event.target.value)}
          >
            <option value="Rectangular">Rectangular</option>
            <option value="Round">Round</option>
            <option value="Other">Other</option>
          </select>

          {formDataOpening.shape === "Round" ? (
            <>
              <label>Diameter</label>
              <input
                required
                type="number"
                min="0"
                step="0.0001"
                value={formDataOpening.diameter}
                onChange={(event) => updateField("diameter", event.target.value)}
              />
            </>
          ) : (
            <>
              <label>Width</label>
              <input
                required
                type="number"
                min="0"
                step="0.0001"
                value={formDataOpening.width}
                onChange={(event) => updateField("width", event.target.value)}
              />
              <label>Height</label>
              <input
                required
                type="number"
                min="0"
                step="0.0001"
                value={formDataOpening.height}
                onChange={(event) => updateField("height", event.target.value)}
              />
            </>
          )}

          {formDataOpening.applicable_to === "wall" && (
            <>
              <label>Finished Floor / Sill Height</label>
              <input
                required
                type="number"
                step="0.0001"
                value={formDataOpening.bottom_elevation}
                onChange={(event) => updateField("bottom_elevation", event.target.value)}
              />
              <label>Head Height</label>
              <input readOnly value={formDataOpening.top_elevation ?? ""} />
            </>
          )}

          <label>Quantity</label>
          <input
            type="number"
            min="1"
            step="1"
            value={formDataOpening.quantity}
            onChange={(event) => updateField("quantity", event.target.value)}
          />

          <label>Main Material to Deduct</label>
          {renderMaterialSelect(formDataOpening.deduction_material, (value) =>
            updateField("deduction_material", value)
          )}

          <label>Header Bearing Each Side</label>
          <input
            type="number"
            min="0"
            step="0.0001"
            value={formDataOpening.header_bearing_each_side}
            onChange={(event) =>
              updateField("header_bearing_each_side", event.target.value)
            }
          />

          {renderRules("header_materials", "Header Materials")}
          {renderRules("perimeter_materials", "Perimeter Materials")}

          <div className="opening-results">
            <span>Area: {formDataOpening.total_sq_ft || 0} sq ft</span>
            <span>Perimeter: {formDataOpening.total_perimeter || 0} ft</span>
            <span>Header: {formDataOpening.total_header_length || 0} ft</span>
          </div>

          <div id="totales_div" dangerouslySetInnerHTML={{ __html: formDataOpening.totales_html || "" }} />

          <div className="opening-actions">
            <button type="button" disabled={isCalculating} onClick={() => calculateData()}>
              Calculate
            </button>
            <button type="button" disabled={isCalculating} onClick={saveToLibrary}>
              Save
            </button>
            {/*<button type="submit" disabled={isCalculating}>
              Apply
            </button>*/}
          </div>
        </form>
      </div>
    </Draggable>,
    document.querySelector("#root")
  );
}

export default OpeningPopup;
