import { useNavigate } from "react-router-dom";
import { routes } from "../Constants";
import { useEffect } from "react";
import useSignal from "../hooks/signals";
import { db } from "../database/db";
function FileContext({ details, setActive, onClose }) {
  const navigate = useNavigate();
  const signal = useSignal();
  const openFile = () => {
    navigate(`/${details.plan}`);
  };

  const downloadFile = () => {
    let download = routes.public + "/" + details.plan;
    let anchor = document.createElement("a");
    anchor.href = download;
    anchor.download = "document.pdf";
    anchor.target = "_blank";
    anchor.click();
  };
  const deleteFile = async () => {
    let formData = new FormData();
    formData.append("path", details.plan);
    let response = await fetch(routes.delete, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${routes.__token}`,
      },
      body: formData,
    });

    const databaseName = db.name;
    const databaseVersion = db.verno;
    const tables = [];

    // ✅ FIX: Match robusto (igual que DeleteAll)
    // Dexie guarda: /projects/projectX/file.pdf
    // Backend/props traen: uploads/projects/projectX/file.pdf
    // Solución: Buscar por substring único "projectX/dir/file.pdf" o leaf

    // extraemos la parte "projects/..." del original
    const rawPlan = String(details.plan || "");
    const parts = rawPlan.split("/");
    const pIdx = parts.indexOf("projects");

    if (pIdx !== -1) {
      // "projects/project123/..."
      const suffix = parts.slice(pIdx).join("/");
      // y nos aseguramos que sea esa
      const dbFiles = await db.drawings
        .filter(d => d.path && d.path.includes(suffix))
        .toArray();

      if (dbFiles.length > 0) {
        await Promise.all(dbFiles.map(r => db.drawings.delete(r.id)));
      }
    } else {
      // Fallback: intentar borrar por nombre de archivo si no hay estructura conocida
      const fName = parts.pop();
      if (fName) {
        const dbFiles = await db.drawings
          .filter(d => d.path && d.path.includes(fName))
          .toArray();
        if (dbFiles.length > 0) await Promise.all(dbFiles.map(r => db.drawings.delete(r.id)));
      }
    }
    const drawings = await db.drawings.toArray();
    tables.push({
      name: "drawings",
      rowCount: drawings.length,
      //   data: drawings,
      data: drawings.map((drawing) => ({
        area: drawing.area,
        counts: drawing.counts,
        factor: drawing.factor,
        id: drawing.id,
        lines: drawing.lines,
        path: drawing.path,
        perimeter: drawing.perimeter,
        scale: drawing.scale,
        storedEllipses: drawing.storedEllipses,
        storedHyperLinks: drawing.storedHyperLinks,
        storedLines: drawing.storedLines,
        storedRectangles: drawing.storedRectangles,
        storedTexts: drawing.storedTexts,
      })),
    });
    const exportData = {
      data: {
        databaseName,
        databaseVersion,
        tables,
      },
    };
    // saveDataToBackend(exportData);
    let data = await response.json();
    if (data.status === 200) signal.emit("refresh");
    if (setActive) {
      setActive((prevValue) => {
        return prevValue.filter((item) => {
          return item !== details.plan;
        });
      });
    }
  };
  useEffect(() => {

      const close = (e) => {

          if (e.target.closest(".context-menu")) return;

          onClose?.();

      };

      const esc = (e) => {

          if (e.key === "Escape") {

              onClose?.();

          }

      };

      const scroll = () => {

          onClose?.();

      };

      document.addEventListener("mousedown", close);

      document.addEventListener("keydown", esc);

      window.addEventListener("scroll", scroll, true);

      return () => {

          document.removeEventListener("mousedown", close);

          document.removeEventListener("keydown", esc);

          window.removeEventListener("scroll", scroll, true);

      };

  }, []);
  const deleteFolder = async () => {
    let formData = new FormData();
    formData.append("path", details.plan);
    let response = await fetch(routes.deleteFolder, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${routes.__token}`,
      },
      body: formData,
    });

    let data = await response.json();
    const databaseName = db.name;
    const databaseVersion = db.verno;
    const tables = [];

    // ✅ FIX: Folder delete robusto
    const rawPath = String(data.folder_path || "");
    // folder_path: "uploads/projects/projectX/MyFolder"
    const fParts = rawPath.split("/");
    const fpIdx = fParts.indexOf("projects");

    if (fpIdx !== -1) {
      // "projects/projectX/MyFolder"
      const suffix = fParts.slice(fpIdx).join("/");

      const dbFolder = await db.drawings
        .filter(d => d.path && d.path.includes(suffix))
        .toArray();

      if (dbFolder.length > 0) {
        await Promise.all(dbFolder.map(record => db.drawings.delete(record.id)));
      }
    }
    const drawings = await db.drawings.toArray();
    tables.push({
      name: "drawings",
      rowCount: drawings.length,
      //   data: drawings,
      data: drawings.map((drawing) => ({
        area: drawing.area,
        counts: drawing.counts,
        factor: drawing.factor,
        id: drawing.id,
        lines: drawing.lines,
        path: drawing.path,
        perimeter: drawing.perimeter,
        scale: drawing.scale,
        storedEllipses: drawing.storedEllipses,
        storedHyperLinks: drawing.storedHyperLinks,
        storedLines: drawing.storedLines,
        storedRectangles: drawing.storedRectangles,
        storedTexts: drawing.storedTexts,
      })),
    });
    const exportData = {
      data: {
        databaseName,
        databaseVersion,
        tables,
      },
    };
    // saveDataToBackend(exportData);
    if (data.status === 200) signal.emit("refresh");
    if (setActive) {
      setActive((prevValue) => {
        return prevValue.filter((item) => {
          return item !== details.plan;
        });
      });
    }
  };
  const saveDataToBackend = async (data) => {
    try {
      const response = await fetch(`/api/sync_local_db`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${routes.__token}`,
        },
        body: JSON.stringify(data),
      });
      if (!response.ok) {
        throw new Error("Error generating proposal");
      }
      console.log("Database Synchronized");
      // const responseData = await response.json();
      // console.log('check result',responseData);
    } catch (error) {
      console.error("Error saving data to the Laravel backend:", error);
    }
  };
  return (
    <ul
      className="context-menu"
      style={{ left: `${details.x}px`, top: `${details.y}px` }}
    >
      <li onClick={() => {openFile(); onClose?.();}}>Open File</li>
      <li onClick={() => {deleteFile(); onClose?.();}}>Delete File</li>
      <li onClick={() => {deleteFolder(); onClose?.();}}>Delete Folder</li>
      <li onClick={() => {downloadFile(); onClose?.();}}>Download File</li>
    </ul>
  );
}
export default FileContext;
