import { useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { toast } from "react-toastify";
import { routes } from "../Constants";
import useSignal from "../hooks/signals";
import ProcessingOverlay from "./ProcessingOverlay";
import "../Css/lengthpop.css";

const COLORS = [
  { hex: "#7c3aed", name: "Purple" },
  { hex: "#000000", name: "Black" },
  { hex: "#ff0000", name: "Red" },
  { hex: "#0000ff", name: "Blue" },
  { hex: "#008000", name: "Dark Green" },
  { hex: "#ffa500", name: "Orange" },
  { hex: "#e22b88", name: "Pink" },
  { hex: "#00ffff", name: "Cyan" },
  { hex: "#808080", name: "Gray" },
];

function parseLocalDb(value) {
  if (!value) return {};
  if (typeof value === "object") return value;

  try {
    return JSON.parse(value);
  } catch (error) {
    console.error("Invalid opening template local_db:", error);
    return {};
  }
}

function OpeningPopupDraw({ setDisplay, current_data = null }) {
  const signal = useSignal();
  const [openingTemplates, setOpeningTemplates] = useState([]);
  const [availableTakeoffs, setAvailableTakeoffs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [formData, setFormData] = useState({
    opening_template_id: "",
    affected_takeoff_key: "",
    takeoff_name: "",
    color: "#7c3aed",
  });
  const [errors, setErrors] = useState({});

  useEffect(() => {
    let mounted = true;

    (async () => {
      try {
        setLoading(true);
        const response = await fetch(
          "/api/get-line-template?type_template=opening",
          {
            headers: { Authorization: `Bearer ${routes.__token}` },
          }
        );
        const data = await response.json();
        if (!response.ok) {
          throw new Error(data.message || "Error loading opening templates.");
        }
        if (mounted) setOpeningTemplates(data.template ?? []);
      } catch (error) {
        toast.error(error.message);
      } finally {
        if (mounted) setLoading(false);
      }
    })();

    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    const receiveAvailableTakeoffs = (event) => {
      setAvailableTakeoffs(Array.isArray(event?.detail) ? event.detail : []);
    };

    window.addEventListener(
      "me3co:available-takeoffs",
      receiveAvailableTakeoffs
    );
    window.dispatchEvent(new CustomEvent("me3co:request-available-takeoffs"));

    return () => {
      window.removeEventListener(
        "me3co:available-takeoffs",
        receiveAvailableTakeoffs
      );
    };
  }, []);

  useEffect(() => {
    if (!current_data) return;

    setFormData((current) => ({
      ...current,
      opening_template_id:
        current_data.opening_template_id ?? current_data.id ?? "",
      affected_takeoff_key: current_data.affected_takeoff_id_unique
        ? `${current_data.affected_takeoff_type}:${current_data.affected_takeoff_id_unique}`
        : "",
      takeoff_name: current_data.takeoff_name ?? current_data.name ?? "",
      color: current_data.color ?? "#7c3aed",
    }));
  }, [current_data]);

  const selectedTemplate = useMemo(
    () =>
      openingTemplates.find(
        (template) => String(template.id) === String(formData.opening_template_id)
      ),
    [openingTemplates, formData.opening_template_id]
  );

  const selectedTakeoff = useMemo(
    () =>
      availableTakeoffs.find(
        (takeoff) =>
          `${takeoff.type}:${takeoff.id_unique}` === formData.affected_takeoff_key
      ),
    [availableTakeoffs, formData.affected_takeoff_key]
  );

  const updateField = (name, value) => {
    setFormData((current) => ({ ...current, [name]: value }));
    setErrors((current) => ({ ...current, [name]: false }));
  };

  const handleTemplateChange = (templateId) => {
    const template = openingTemplates.find(
      (item) => String(item.id) === String(templateId)
    );

    setFormData((current) => ({
      ...current,
      opening_template_id: templateId,
      takeoff_name:
        current.takeoff_name || template?.template_name || "Opening",
    }));
    setErrors((current) => ({ ...current, opening_template_id: false }));
  };

  const startOpeningTakeoff = () => {
    const nextErrors = {
      opening_template_id: !selectedTemplate,
      affected_takeoff_key: !selectedTakeoff,
      takeoff_name: !formData.takeoff_name.trim(),
    };

    if (Object.values(nextErrors).some(Boolean)) {
      setErrors(nextErrors);
      toast.warning("Select an opening, an affected takeoff and enter a name.");
      return;
    }

    const openingData = parseLocalDb(selectedTemplate.local_db);

    if (current_data?.opening_match_key) {
      signal.emit("opening.takeoff.updated", {
        opening_match_key: current_data.opening_match_key,
        previous_name: current_data.takeoff_name ?? current_data.name ?? "",
        name: formData.takeoff_name.trim(),
        color: formData.color,
        lineTemplate: selectedTemplate.id,
        opening_template_id: selectedTemplate.id,
        opening_template_name: selectedTemplate.template_name,
        openingData: {
          ...openingData,
          affected_takeoff_id_unique: selectedTakeoff.id_unique,
          affected_takeoff_name: selectedTakeoff.name,
          affected_takeoff_type: selectedTakeoff.type,
        },
      });
      setDisplay(false);
      return;
    }

    signal.emit("takeoff", {
      type: "opening",
      openPopup: true,
      name: formData.takeoff_name.trim(),
      color: formData.color,
      lineTemplate: selectedTemplate.id,
      opening_template_id: selectedTemplate.id,
      opening_template_name: selectedTemplate.template_name,
      openingData: {
        ...openingData,
        affected_takeoff_id_unique: selectedTakeoff.id_unique,
        affected_takeoff_name: selectedTakeoff.name,
        affected_takeoff_type: selectedTakeoff.type,
      },
      affected_takeoff_id_unique: selectedTakeoff.id_unique,
      affected_takeoff_name: selectedTakeoff.name,
      affected_takeoff_type: selectedTakeoff.type,
    });

    setDisplay(false);
  };

  return (
    <>
      <ProcessingOverlay
        visible={loading}
        message="Processing Opening Templates..."
      />
      {createPortal(
        <Draggable handle=".modal-header">
          <div className="popup__count popup-length-takeoffDraw">
            <div className="modal-header">
              {current_data?.opening_match_key
                ? "Edit Opening Takeoff"
                : "Opening Takeoff"}
              <span className="close-btn" onClick={() => setDisplay(false)}>
                &times;
              </span>
            </div>

            <form
              className="modal-body"
              onSubmit={(event) => {
                event.preventDefault();
                startOpeningTakeoff();
              }}
            >
              <div className="takeoff-name-mainDraw">
                <div className="takeoff-nameDraw">
                  <label className="label">Select Opening</label>
                  <select
                    className={
                      errors.opening_template_id ? "border-red" : "border-blue"
                    }
                    value={formData.opening_template_id}
                    onChange={(event) =>
                      handleTemplateChange(event.target.value)
                    }
                  >
                    <option value="">-- Select opening --</option>
                    {openingTemplates.map((template) => (
                      <option key={template.id} value={template.id}>
                        {template.template_name}
                      </option>
                    ))}
                  </select>
                  {errors.opening_template_id && (
                    <span className="error-text">
                      Please select an opening.
                    </span>
                  )}
                </div>

                <div className="takeoff-nameDraw">
                  <label className="label">Affected Takeoff</label>
                  <select
                    className={
                      errors.affected_takeoff_key
                        ? "border-red"
                        : "border-blue"
                    }
                    value={formData.affected_takeoff_key}
                    onChange={(event) =>
                      updateField("affected_takeoff_key", event.target.value)
                    }
                  >
                    <option value="">-- Select takeoff --</option>
                    {availableTakeoffs.map((takeoff) => (
                      <option
                        key={`${takeoff.type}:${takeoff.id_unique}`}
                        value={`${takeoff.type}:${takeoff.id_unique}`}
                      >
                        {takeoff.name} ({takeoff.type})
                      </option>
                    ))}
                  </select>
                  {availableTakeoffs.length === 0 && (
                    <span className="error-text">
                      This drawing has no compatible takeoffs.
                    </span>
                  )}
                </div>

                <div className="takeoff-nameDraw">
                  <label className="label">TakeOff Name</label>
                  <input
                    className={
                      errors.takeoff_name ? "border-red" : "border-blue"
                    }
                    value={formData.takeoff_name}
                    onChange={(event) =>
                      updateField("takeoff_name", event.target.value)
                    }
                  />
                </div>

                <div className="takeoff-nameDraw">
                  <label className="label">Opening Color</label>
                  <select
                    className="border-blue"
                    value={formData.color}
                    onChange={(event) => updateField("color", event.target.value)}
                  >
                    {COLORS.map((color) => (
                      <option key={color.hex} value={color.hex}>
                        {color.name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="template-save-actions">
                <button className="btn-save mt-2" type="submit">
                  Start Opening TakeOff
                </button>
              </div>
            </form>
          </div>
        </Draggable>,
        document.querySelector("#root")
      )}
    </>
  );
}

export default OpeningPopupDraw;
