import { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { routes, projectId } from "../Constants";
import useSignal from "../hooks/signals";
import Details from "./Details";
// import ActiveTab from "./ActiveTab";
import FileView from "./FileView";
import "../Css/sidebar_v2.css";

function SideBar() {
  const [plans, setPlans] = useState([]);
  const [copy, setCopy] = useState([]);
  const [search, setSearch] = useState("");
  const [refresh, setRefresh] = useState({});
  const [active, setActive] = useState([]);
  const [openFile, setOpenFile] = useState(null);
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const signal = useSignal();
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [hoveredPage, setHoveredPage] = useState(null);

  useEffect(() => {
    let refreshCallBack = () => {
      setRefresh({});
    };
    let activeCallBack = (e) => {
      let pathname = decodeURIComponent(e.detail.pathname);
      if (!active.includes(pathname)) {
        setActive([...active, pathname]);
      }
    };
    let hoverCallBack = (e) => {
      setHoveredPage(e.detail);
    };

    signal.listen("refresh", refreshCallBack);
    signal.listen("tab.active", activeCallBack);
    signal.listen("sidebar_hover_page", hoverCallBack);

    return () => {
      signal.unsubscribe("refresh", refreshCallBack);
      signal.unsubscribe("tab.active", activeCallBack);
      signal.unsubscribe("sidebar_hover_page", hoverCallBack);
    };
  }, [pathname]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    (async () => {
      let url = routes.plans + projectId;
      let response = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${routes.__token}`,
        },
      });
      let data = await response.json();
      setPlans(data);
      if (data.length === 0) {
        setActive([]);
        setOpenFile(null);
        navigate("/");
      }
    })();
  }, [refresh]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    let result = plans.filter((value) =>
      value.toLocaleLowerCase().includes(search.toLocaleLowerCase())
    );
    setCopy(result);
  }, [search, plans]);
  const activeFile = pathname.split("/").pop();

  return (
    <div className={`sidebar__left ${isSidebarOpen ? "open" : "closed"}`}>
      {/* Floating Toggle Chevron Button */}
      <div
        className="toggle-sidebar-btn"
        onClick={() => setSidebarOpen(!isSidebarOpen)}
      >
        {isSidebarOpen ? (
          <i className="fa-light fa-chevron-left" style={{ fontSize: "12px" }}></i>
        ) : (
          <i className="fa-light fa-chevron-right" style={{ fontSize: "12px" }}></i>
        )}
      </div>

      {/* Expanded Only: Project Details */}
      <div className="expanded-only" style={{ padding: "15px 12px 5px 12px" }}>
        <Details />
      </div>

      {/* Expanded Only: Search Box */}
      <div className="left-bar-content expanded-only" style={{ padding: "0 12px" }}>
        <div className="search__box" style={{ marginBlock: "8px" }}>
          <input
            type="text"
            placeholder="Search plans..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <i className="fa-light fa-search search-icon"></i>
        </div>
      </div>

      {/* FileView handles both Expanded and Collapsed list views internally */}
      <FileView
        plans={copy}
        activeFiles={active}
        setActiveFiles={setActive}
        activeFile={activeFile}
        openFile={openFile}
        isSidebarOpen={isSidebarOpen}
        setSidebarOpen={setSidebarOpen}
      />

      {/* Floating Hover Card for Compact View */}
      {!isSidebarOpen && hoveredPage && (
        <div
          className="sidebar-hover-card"
          style={{
            left: `${hoveredPage.x}px`,
            top: `${hoveredPage.y}px`,
          }}
        >
          <img src={hoveredPage.thumbnail} alt="" />
          <div className="hover-card-info">
            <div className="hover-card-title">{hoveredPage.name}</div>
            <div className="hover-card-page">Page {hoveredPage.pageIndex + 1}</div>
          </div>
        </div>
      )}
    </div>
  );
}

export default SideBar;
