import { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { Document, Page, pdfjs } from "react-pdf";
import { routes, projectId } from "../Constants";
//import { toast } from "react-toastify";
import useSignal from "../hooks/signals";
import axios from "axios";
import "../pages_css.css";
import { PDFDocument } from "pdf-lib";
import Swal from "sweetalert2";

// PDF.js worker
pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.mjs`;

const swalOk = (title, text = "") =>
  Swal.fire({
    icon: "success",
    title,
    text,
    timer: 2200,
    showConfirmButton: false,
  });

const swalWarn = (title, text = "") =>
  Swal.fire({
    icon: "warning",
    title,
    text,
    confirmButtonText: "OK",
  });

const swalErr = (title, text = "") =>
  Swal.fire({
    icon: "error",
    title,
    text,
    confirmButtonText: "OK",
  });

/* =========================
   Lazy-load
========================= */
function useInView(options) {
  const [inView, setInView] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const obs = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      options || { root: null, rootMargin: "800px", threshold: 0.01 }
    );

    obs.observe(el);
    return () => obs.disconnect();
  }, [options]);

  return { ref, inView };
}

function LazyPageThumb({
  pageNumber,
  selected,
  onToggle,
  code,
  scanning,

  // name/code editing
  displayCode,
  isEditing,
  editValue,
  onStartEdit,
  onEditChange,
  onEditCommit,
  onEditCancel,
}) {
  const { ref, inView } = useInView({ rootMargin: "800px", threshold: 0.01 });
  const inputRef = useRef(null);

  useEffect(() => {
    if (isEditing) {
      requestAnimationFrame(() => {
        if (inputRef.current) {
          inputRef.current.focus();
          inputRef.current.select();
        }
      });
    }
  }, [isEditing]);

  return (
    <div
      ref={ref}
      style={{
        border: selected ? "3px solid #0d6efd" : "1px solid #ccc",
        borderRadius: "6px",
        background: "#fff",
        padding: "8px",
        textAlign: "center",
        width: "140px",
        minHeight: 225,
      }}
    >
      <div style={{ width: 120, height: 160, margin: "0 auto" }}>
        {inView ? (
          <Page
            pageNumber={pageNumber}
            width={120}
            renderTextLayer={false}
            renderAnnotationLayer={false}
          />
        ) : (
          <div
            style={{
              width: 120,
              height: 160,
              background: "#f1f1f1",
              borderRadius: 6,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: "#999",
              fontSize: 12,
            }}
          >
            Loading…
          </div>
        )}
      </div>

      <div style={{ marginTop: "6px" }}>
        <label style={{ fontSize: "12px" }}>
          <input
            type="checkbox"
            checked={selected}
            onChange={() => onToggle(pageNumber)}
            style={{ marginRight: "4px" }}
          />
          Page {pageNumber}
        </label>
      </div>

      {/* Editable code/name (double click) */}
      <div
        style={{
          marginTop: 6,
          fontSize: 11,
          textAlign: "left",
          background: "#f8f9fa",
          border: "1px dashed #ced4da",
          borderRadius: 6,
          padding: "6px",
          userSelect: "none",
          cursor: "text",
        }}
        title="Double-click to rename"
        onDoubleClick={() => onStartEdit(pageNumber)}
      >
        {isEditing ? (
          <input
            ref={inputRef}
            value={editValue}
            onChange={(e) => onEditChange(e.target.value)}
            onBlur={() => onEditCommit(pageNumber)}
            onKeyDown={(e) => {
              if (e.key === "Enter") onEditCommit(pageNumber);
              if (e.key === "Escape") onEditCancel();
            }}
            placeholder={`PAGE-${pageNumber}`}
            style={{
              width: "100%",
              fontSize: 11,
              padding: "4px 6px",
              borderRadius: 6,
              border: "1px solid #ced4da",
              outline: "none",
              background: "#fff",
            }}
          />
        ) : (
          <>
            <div>— {displayCode}</div>
            {!code && !displayCode?.trim() ? (
              <div style={{ marginTop: 4, color: "#6c757d" }}>
                {scanning ? "(Analyzing…)" : "(No code → will use PAGE-n)"}
              </div>
            ) : null}
          </>
        )}
      </div>
    </div>
  );
}

function PdfPreviewPopup({ setDisplay, file }) {
  const signal = useSignal();

  const [numPages, setNumPages] = useState(0);
  const [selectedPages, setSelectedPages] = useState([]);
  const [selectAll, setSelectAll] = useState(false);

  const [pageMeta, setPageMeta] = useState([]);
  const [scanning, setScanning] = useState(false);
  const [shouldAnalyze, setShouldAnalyze] = useState(null);
  const askedRef = useRef(false);

  // progress
  const [working, setWorking] = useState(false);
  const [workLabel, setWorkLabel] = useState("");
  const [doneCount, setDoneCount] = useState(0);
  const [totalCount, setTotalCount] = useState(0);

  // overrides by page number
  const [pageNameOverrides, setPageNameOverrides] = useState({});

  // edit mode
  const [editingPage, setEditingPage] = useState(null);
  const [editingValue, setEditingValue] = useState("");

  const getStorageKey = (pdfFile) => {
    const pdfName = pdfFile?.name || "document.pdf";
    return `me3co:pdf_page_names:${projectId}:${pdfName}`;
  };

  useEffect(() => {
    if (!file) return;
    try {
      const raw = localStorage.getItem(getStorageKey(file));
      const parsed = raw ? JSON.parse(raw) : {};
      if (parsed && typeof parsed === "object") setPageNameOverrides(parsed);
    } catch (e) {
      console.warn("Could not read page name overrides from localStorage:", e);
    }
  }, [file]);

  useEffect(() => {
    if (!file) return;
    try {
      localStorage.setItem(getStorageKey(file), JSON.stringify(pageNameOverrides || {}));
    } catch (e) {
      // ignore
    }
  }, [pageNameOverrides, file]);

  const onDocumentLoadSuccess = ({ numPages }) => setNumPages(numPages);

  const togglePage = (num) => {
    setSelectedPages((prev) =>
      prev.includes(num) ? prev.filter((n) => n !== num) : [...prev, num]
    );
  };

  const handleSelectAll = () => {
    if (selectAll) {
      setSelectedPages([]);
      setSelectAll(false);
      return;
    }
    const all = Array.from({ length: numPages }, (_, i) => i + 1);
    setSelectedPages(all);
    setSelectAll(true);
  };

  /* ========= SweetAlert ========= */
  useEffect(() => {
    if (!file) return;
    if (askedRef.current) return;

    askedRef.current = true;

    Swal.fire({
      title: "What do you want to do?",
      html:
        "<div style='text-align:left;font-size:14px;line-height:1.4'>" +
        "<b>Find code (AI)</b>: detects a code per page (may take a bit).<br/>" +
        "<b>Just select and upload</b>: no analysis, pages will be named PAGE-n if no code exists." +
        "</div>",
      icon: "question",
      showCancelButton: true,
      confirmButtonText: "Find code",
      cancelButtonText: "Just upload",
      reverseButtons: true,
      allowOutsideClick: false,
      allowEscapeKey: false,
    }).then((res) => {
      if (res.isConfirmed) {
        setShouldAnalyze(true);
      } else {
        setShouldAnalyze(false);
        setScanning(false);
        setPageMeta([]);
      }
    });
  }, [file]);

  /* ========= AI analysis (optional) ========= */
  useEffect(() => {
    if (!file) return;
    if (shouldAnalyze !== true) return;

    let cancelled = false;

    const analyzeFullPdf = async () => {
      try {
        setScanning(true);
        setPageMeta([]);

        const formData = new FormData();
        formData.append("file", file);
        formData.append("project_id", projectId);

        const resp = await axios.post(routes.analyze_pdf, formData, {
          headers: { Authorization: `Bearer ${routes.__token}` },
        });

        if (cancelled) return;

        const data = Array.isArray(resp.data) ? resp.data : [];
        setPageMeta(data);
      } catch (err) {
        console.error("❌ PDF analysis error:", err);
        await swalErr("Could not analyze the PDF (page codes).");
      } finally {
        if (!cancelled) setScanning(false);
      }
    };

    analyzeFullPdf();
    return () => (cancelled = true);
  }, [file, shouldAnalyze]);

  const getCodeFor = (pageNumber) =>
    pageMeta.find((x) => x.page === pageNumber)?.code ?? null;

  const getFinalCodeFor = (pageNumber) => {
    const override = pageNameOverrides?.[pageNumber];
    if (override && String(override).trim()) return String(override).trim();

    const ai = getCodeFor(pageNumber);
    if (ai && String(ai).trim()) return String(ai).trim();

    return `PAGE-${pageNumber}`;
  };

  /* ========= utils ========= */
  const sanitizeForFilename = (s) =>
    String(s || "")
      .replace(/[\\/:*?"<>|]/g, "-")
      .replace(/\s+/g, " ")
      .trim();

  const getPdfBaseName = (pdfName) => {
    const safe = sanitizeForFilename(pdfName || "document.pdf");
    return safe.replace(/\.pdf$/i, "");
  };

  const buildPdfWithSelectedPages = async (inputFile, pages1based) => {
    const srcBytes = await inputFile.arrayBuffer();

    const srcDoc = await PDFDocument.load(srcBytes);
    const total = srcDoc.getPageCount();

    const indices = pages1based
      .map((p) => parseInt(p, 10) - 1)
      .filter((i) => Number.isInteger(i) && i >= 0 && i < total);

    if (!indices.length) throw new Error("No valid pages selected.");

    const newDoc = await PDFDocument.create();
    const copied = await newDoc.copyPages(srcDoc, indices);
    copied.forEach((p) => newDoc.addPage(p));

    const outBytes = await newDoc.save();
    return new File([outBytes], inputFile.name || "document.pdf", { type: "application/pdf" });
  };

  /* ========= generate+upload PNG blocks ========= */
  const generateAndUploadPngBlocks = async ({ pdfFile, pages1based, chunkSize = 20 }) => {
    const buf = await pdfFile.arrayBuffer();
    const task = pdfjs.getDocument({ data: buf });
    const pdf = await task.promise;

    const pdfBase = getPdfBaseName(pdfFile.name);
    const SCALE = 1.15;
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d", { alpha: false });

    const total = pages1based.length;
    setTotalCount(total);
    setDoneCount(0);

    const newIndexByOriginal = new Map(
      pages1based.map((originalPage, idx) => [originalPage, idx + 1])
    );

    for (let start = 0; start < total; start += chunkSize) {
      const chunk = pages1based.slice(start, start + chunkSize);

      setWorkLabel(`Generating PNGs ${start + 1}-${start + chunk.length} of ${total}…`);

      const formData = new FormData();
      formData.append("project_id", projectId);
      formData.append("pdf_name", pdfFile.name || "document.pdf");
      formData.append("pages", JSON.stringify(chunk));

      formData.append(
        "page_codes",
        JSON.stringify(
          chunk.map((p) => ({
            page: p,
            code: getFinalCodeFor(p),
          }))
        )
      );

      for (const pageNum of chunk) {
        const page = await pdf.getPage(pageNum);
        const viewport = page.getViewport({ scale: SCALE });

        canvas.width = Math.floor(viewport.width);
        canvas.height = Math.floor(viewport.height);

        await page.render({ canvasContext: ctx, viewport }).promise;

        const finalCode = getFinalCodeFor(pageNum);
        const safeCode = sanitizeForFilename(finalCode);

        const newP = newIndexByOriginal.get(pageNum) || pageNum;
        const filename = `${pdfBase}__${safeCode}__P${newP}.webp`;

        const thumbCanvas = document.createElement("canvas");
        const thumbCtx = thumbCanvas.getContext("2d");

        thumbCanvas.width = 500;
        thumbCanvas.height = 500;

        thumbCtx.fillStyle = "#ffffff";
        thumbCtx.fillRect(0, 0, 500, 500);

        const scale = Math.min(
            500 / canvas.width,
            500 / canvas.height
        );

        const drawWidth = canvas.width * scale;
        const drawHeight = canvas.height * scale;

        thumbCtx.drawImage(
            canvas,
            (500 - drawWidth) / 2,
            (500 - drawHeight) / 2,
            drawWidth,
            drawHeight
        );

        const blob = await new Promise((resolve, reject) => {
            thumbCanvas.toBlob(
                (b) => (b ? resolve(b) : reject(new Error("Could not generate WEBP"))),
                "image/webp",
                4
            );
        });

        formData.append("pngs[]", new File([blob], filename, { type: "image/webp" }));

        setDoneCount((prev) => prev + 1);
      }

      setWorkLabel(`Uploading block ${start + 1}-${start + chunk.length}…`);

      await axios.post(routes.upload_png_chunk, formData, {
        headers: { Authorization: `Bearer ${routes.__token}` },
      });

      await new Promise((r) => setTimeout(r, 0));
    }

    canvas.width = 1;
    canvas.height = 1;
  };

  /* ========= upload flow ========= */
  const handleUpload = async () => {
    if (!file) return;

    if (selectedPages.length === 0) {
      await swalWarn("Select at least one page before uploading.");
      return;
    }

    if (selectedPages.length > 40) {
      const ok = window.confirm(
        `You are about to upload ${selectedPages.length} pages.\n\nThe PDF will be uploaded first, then PNGs in blocks of 20.\nContinue?`
      );
      if (!ok) return;
    }

    try {
      setWorking(true);
      setWorkLabel("Trimming PDF…");

      const trimmedPdf = await buildPdfWithSelectedPages(file, selectedPages);

      setWorkLabel("Uploading PDF…");
      const pdfForm = new FormData();
      pdfForm.append("file", trimmedPdf);
      pdfForm.append("project_id", projectId);

      await axios.post(routes.upload, pdfForm, {
        headers: { Authorization: `Bearer ${routes.__token}` },
      });

      await swalOk("✅ PDF uploaded. Generating PNGs in blocks…");

      await generateAndUploadPngBlocks({
        pdfFile: file,
        pages1based: selectedPages,
        chunkSize: 20,
      });

      await swalOk("✅ PNGs uploaded successfully (blocks)");
      setDisplay(false);
      signal.emit("refresh");
    } catch (e) {
      console.error(e);
      await swalErr(e?.message || "Block upload failed.");
    } finally {
      setWorking(false);
      setWorkLabel("");
      setDoneCount(0);
      setTotalCount(0);
    }
  };

  const pageNumbers = useMemo(
    () => Array.from({ length: numPages }, (_, i) => i + 1),
    [numPages]
  );

  /* ========= edit handlers ========= */
  const startEdit = (pageNumber) => {
    const current = getFinalCodeFor(pageNumber);
    setEditingPage(pageNumber);
    setEditingValue(current);
  };

  const cancelEdit = () => {
    setEditingPage(null);
    setEditingValue("");
  };

  const commitEdit = (pageNumber) => {
    const value = String(editingValue || "").trim();

    setPageNameOverrides((prev) => {
      const next = { ...(prev || {}) };
      if (!value) {
        delete next[pageNumber];
      } else {
        next[pageNumber] = value;
      }
      return next;
    });

    setEditingPage(null);
    setEditingValue("");
  };

  return createPortal(
    <Draggable handle=".modal-header">
      <div className="popup__count">
        <div className="modal-header">
          PDF Preview
          <span
            className="close-btn"
            onClick={() => setDisplay(false)}
            style={{ cursor: "pointer" }}
            aria-label="Close"
            title="Close"
          >
            &times;
          </span>
        </div>

        <div
          className="modal-body"
          style={{ background: "#f3f3f3", maxHeight: "80vh", overflowY: "auto" }}
        >
          {scanning && shouldAnalyze === true && (
            <div
              style={{
                background: "#fff3cd",
                border: "1px solid #ffeeba",
                color: "#856404",
                padding: 10,
                borderRadius: 8,
                marginBottom: 10,
                textAlign: "center",
                fontSize: 13,
              }}
            >
              Analyzing the full PDF to detect a code per page…
              <br />
              (Upload is not blocked: if you upload now, it will use PAGE-n)
            </div>
          )}

          {working && (
            <div
              style={{
                background: "#e7f1ff",
                border: "1px solid #cfe2ff",
                color: "#084298",
                padding: 10,
                borderRadius: 8,
                marginBottom: 10,
                textAlign: "center",
                fontSize: 13,
              }}
            >
              <div>
                <b>{workLabel}</b>
              </div>
              {totalCount > 0 && (
                <div style={{ marginTop: 6 }}>
                  Progress: {doneCount} / {totalCount}
                </div>
              )}
            </div>
          )}

          {file ? (
            <Document
              file={file}
              onLoadSuccess={onDocumentLoadSuccess}
              loading={<p>Loading PDF...</p>}
              onLoadError={(err) => console.error("PDF load error:", err)}
            >
              <div style={{ display: "flex", flexWrap: "wrap", gap: 10, justifyContent: "center" }}>
                {pageNumbers.map((pageNumber) => (
                  <LazyPageThumb
                    key={`page_${pageNumber}`}
                    pageNumber={pageNumber}
                    selected={selectedPages.includes(pageNumber)}
                    onToggle={togglePage}
                    code={getCodeFor(pageNumber)}
                    scanning={scanning && shouldAnalyze === true}
                    displayCode={getFinalCodeFor(pageNumber)}
                    isEditing={editingPage === pageNumber}
                    editValue={editingPage === pageNumber ? editingValue : ""}
                    onStartEdit={startEdit}
                    onEditChange={setEditingValue}
                    onEditCommit={commitEdit}
                    onEditCancel={cancelEdit}
                  />
                ))}
              </div>
            </Document>
          ) : (
            <p>No PDF file loaded.</p>
          )}
        </div>

        <div
          className="modal-footer"
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            background: "#f1f1f1",
            padding: "10px 15px",
            borderTop: "1px solid #ccc",
          }}
        >
          <label style={{ margin: 0, fontWeight: "bold" }}>
            <input
              type="checkbox"
              checked={selectAll}
              onChange={handleSelectAll}
              style={{ marginRight: 6 }}
            />
            Select all
          </label>

          <div>
            <button className="btn btn-secondary me-2" onClick={() => setDisplay(false)} disabled={working}>
              Cancel
            </button>
            <button className="btn btn-primary" onClick={handleUpload} disabled={working}>
              {working ? "Processing..." : "Upload selected pages"}
            </button>
          </div>
        </div>
      </div>
    </Draggable>,
    document.querySelector("#root")
  );
}

export default PdfPreviewPopup;
