import React, { useEffect, useRef, useState } from "react";
import FolderPreviewPopup from "./FolderPreviewPopup";
import Swal from "sweetalert2";

/* ============================================================
   SweetAlert Confirm (Browser-like message but custom)
============================================================ */
export async function confirmFolderUploadSwal({ folderName = "Selected folder" }) {
  const res = await Swal.fire({
    icon: "question",
    title: "Do you want to upload files to this site?",
    html: `
      <div style="text-align:left; font-size:14px; line-height:1.45;">
        This action will upload all files from "<b>${folderName}</b>".<br/>
        Only continue if you trust this site.
      </div>
    `,
    showCancelButton: true,
    confirmButtonText: "Upload",
    cancelButtonText: "Cancel",
    reverseButtons: true,
    allowOutsideClick: false,
    allowEscapeKey: true,
    didOpen: () => {
      const el = document.querySelector(".swal2-container");
      if (el) el.style.zIndex = "250000";
    },
  });

  return res.isConfirmed;
}

/* ============================================================
   Component
============================================================ */
const FolderUpload = () => {
  const inputRef = useRef(null);
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [showPreview, setShowPreview] = useState(false);

  useEffect(() => {
    window.triggerFolderUpload = async () => {

      const confirmed = await confirmFolderUploadSwal({
        folderName: "Selected folder"
      });

      if (!confirmed) return;

      if (inputRef.current) {
        inputRef.current.setAttribute("webkitdirectory", "");
        inputRef.current.setAttribute("directory", "");
        inputRef.current.click();
      }
    };
  }, []);

  const handleFolderSelect = async (e) => {
    const files = Array.from(e.target.files).filter((f) =>
      f.name.toLowerCase().endsWith(".pdf")
    );

    if (files.length === 0) {
      await Swal.fire({
        icon: "warning",
        title: "No PDF files found",
        text: "The selected folder does not contain any PDF files.",
        confirmButtonText: "OK",
        didOpen: () => {
          const el = document.querySelector(".swal2-container");
          if (el) el.style.zIndex = "250000";
        },
      });
      return;
    }

    setSelectedFiles(files);
    setShowPreview(true);
  };

  return (
    <div>
      <input
        ref={inputRef}
        type="file"
        className="hidden"
        onChange={handleFolderSelect}
        id="folderUpload"
        webkitdirectory="true"
        mozdirectory="true"
        multiple
        accept=".pdf"
      />

      {showPreview && (
        <FolderPreviewPopup
          files={selectedFiles}
          onClose={() => setShowPreview(false)}
        />
      )}
    </div>
  );
};

export default FolderUpload;
