import useSignal from "../hooks/signals";
import { useState, useEffect, useMemo } from "react";
import { useLocation } from "react-router-dom";
import TakeoffTable from "./TakoffTable";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../database/db";
import LineTable from "./LineTable";
import CountTable from "./CountTable";
import AreaTable from "./AreaTable";
import PerimeterTable from "./PerimeterTable";
import AnnotationLineTable from "./AnnotationLineTable";
import AnnotationRectangleTable from "./AnnotationRectangleTable";
import AnnotationOvalTable from "./AnnotationOvalTable";
import AnnotationTextTable from "./AnnotationTextTable";
import AnnotationHyperlinkTable from "./AnnotationHyperlinkTable";
import { routes, projectId } from "../Constants";
import { toast } from "react-toastify";
import Swal from "sweetalert2";
import "../Css/rightbar_v2.css";
import LengthPopupDraw from "./LengthPopupDraw";
import PerimeterPopupDraw from "./PerimeterPopupDraw";
import AreaPopupDraw from "./AreaPopupDraw";
import LengthPopup from "./LengthPopup";
import PerimeterPopup from "./PerimeterPopup";
import AreaPopup from "./AreaPopup";
import OpeningPopup from "./OpeningPopup";
import OpeningPopupDraw from "./OpeningPopupDraw";
import Dexie from "dexie";
import LineRowContext from "./LineRowContext";
import AreaRowContext from "./AreaRowContext";
import PerimeterRowContext from "./PerimeterRowContext";
function RightBar() {
  const [details, setDetails] = useState(null);
  const { pathname } = useLocation();
  const signal = useSignal();
  const [isRightBarOpen, setRightBarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("takeoff");
  const [openLengthPopupDraw, setOpenLengthPopupDraw] = useState(false);
  const [openLengthPopupEdit, setOpenLengthPopupEdit] = useState(false);
  const [openPerimeterPopupDraw, setOpenPerimeterPopupDraw] = useState(false);
  const [openAreaPopupDraw, setOpenAreaPopupDraw] = useState(false);
  const [openPerimeterPopupEdit, setOpenPerimeterPopupEdit] = useState(false);
  const [openAreaPopupEdit, setOpenAreaPopupEdit] = useState(false);
  const [openOpeningPopupDraw, setOpenOpeningPopupDraw] = useState(false);
  const [openOpeningPopupEdit, setOpenOpeningPopupEdit] = useState(false);
  const [lineTemplate, setLineTemplate] = useState([]);
  const [formData, setFormData] = useState();
  const [userRole, setUserRole] = useState(null);

  const [selectedTrade, setSelectedTrade] = useState("");
  const [templateFilter, setTemplateFilter] = useState("all");
  const [templateCache, setTemplateCache] = useState({});

  const [templateContextMenu, setTemplateContextMenu] = useState({
    visible: false,
    x: 0,
    y: 0,
    item: null,
  });

  const memoizedTemplateEdit = useMemo(() => ({
    mode: "editTemplate",
    templateId: formData?.id,
    is_global: formData?.is_global ?? 0,
    template: formData,
  }), [formData?.id, formData?.is_global]);

  const toggleRightBarState = () => {
    setRightBarOpen(!isRightBarOpen); // Toggle the right bar state
  };
  const handleTabClick = (tab) => {
    setActiveTab(tab);
  };

  const [openLengthPopup, setOpenLengthPopup] = useState(false);
  const [openAreaPopup, setOpenAreaPopup] = useState(false);
  const [openPerimeterPopup, setOpenPerimeterPopup] = useState(false);
  const [takeoffFormData, setTakeoffFormData] = useState(null);
  const [takeoffMemoData, setTakeoffMemoData] = useState(null);
  const [hoveredTakeoff, setHoveredTakeoff] = useState(null);

  const [takeoffContext, setTakeoffContext] = useState({
      visible: false,
      type: "",
      details: null,
  });

  useEffect(() => {
    if (!takeoffContext.visible) return undefined;

    const closeTakeoffContext = () => {
      setTakeoffContext({
        visible: false,
        type: "",
        details: null,
      });
    };

    const handleKeyDown = (event) => {
      if (event.key === "Escape") {
        closeTakeoffContext();
      }
    };

    document.addEventListener("click", closeTakeoffContext);
    document.addEventListener("keydown", handleKeyDown);
    window.addEventListener("scroll", closeTakeoffContext, true);
    window.addEventListener("resize", closeTakeoffContext);
    window.addEventListener("blur", closeTakeoffContext);

    return () => {
      document.removeEventListener("click", closeTakeoffContext);
      document.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("scroll", closeTakeoffContext, true);
      window.removeEventListener("resize", closeTakeoffContext);
      window.removeEventListener("blur", closeTakeoffContext);
    };
  }, [takeoffContext.visible]);

  const assetPath = routes.assetPath;
  let data = useLiveQuery(async () => {
    let drawingData = await db.drawings
      .where({
        path: pathname,
      })
      .first();

    return drawingData;
  }, [pathname]);

  const getTemplateId = (lineTemplate, lineTemplateId = null) => {
    if (lineTemplateId !== null && lineTemplateId !== undefined) {
      return lineTemplateId;
    }

    if (
      typeof lineTemplate === "number" ||
      (
        typeof lineTemplate === "string" &&
        /^\d+$/.test(lineTemplate.trim())
      )
    ) {
      return Number(lineTemplate);
    }

    if (typeof lineTemplate === "object" && lineTemplate?.id) {
      return lineTemplate.id;
    }

    if (typeof lineTemplate === "string") {
      try {
        const parsed = JSON.parse(lineTemplate);

        if (parsed?.id) {
          return parsed.id;
        }
      } catch (error) {
        // El valor no era un JSON anterior.
      }
    }

    return null;
  };

  const uniqueTakeoffs = useMemo(() => {
    if (!data) return [];
    const list = [];

    // 1. Lines
    const lines = data.lines || [];
    const groupedLines = {};
    lines.forEach((item) => {
      const idUnique = item?.meta?.idUnique || "";
      const groupKey = idUnique !== "" ? idUnique : item.meta.name;
      const length1 = parseFloat(item.data?.[item.data.length - 1]?.[1] || 0);
      if (groupedLines[groupKey]) {
        groupedLines[groupKey].value += length1;
      } else {
        groupedLines[groupKey] = {
          name: item.meta.name,
          idUnique,
          value: length1,
          unit: item.data?.[item.data.length - 1]?.[2] || "ft",
          color: item.meta.stroke || "#000",
          type: "length",
          template: item.meta.lineTemplate,
          templateId: item.meta.lineTemplateId || item.meta.lineTemplate?.id,
          stroke: item.meta.stroke,
          data: item.data,
          originalItem: item,
        };
      }
    });
    Object.values(groupedLines).forEach(item => {
      item.value = parseFloat(item.value.toFixed(2));
      list.push(item);
    });

    // 2. Counts
    const counts = data.counts || [];
    const groupedCounts = {};
    counts.forEach((item, index) => {
      const name = item.meta.name;
      const val = parseInt(item.data?.[item.data.length - 1]?.[1] || 0, 10);
      const isOpening = Boolean(item.meta?.isOpening);
      const opening = item.meta?.opening || {};
      const openingIdUnique =
        item.meta?.idUnique ||
        opening.idUnique ||
        [
          "opening",
          item.meta?.lineTemplate || opening.opening_template_id || "",
          opening.affected_takeoff_type || "",
          opening.affected_takeoff_id_unique || "",
          name,
        ].join(":");
      const groupKey = isOpening ? openingIdUnique : name;

      if (groupedCounts[groupKey]) {
        groupedCounts[groupKey].value += val;
        groupedCounts[groupKey].data = groupedCounts[groupKey].data.concat(item.data || []);
      } else {
        groupedCounts[groupKey] = {
          name,
          idUnique: isOpening ? openingIdUnique : "",
          value: val,
          unit: isOpening ? "Opening" : (item.data?.[item.data.length - 1]?.[2] || "Count"),
          color: item.meta?.stroke || "red",
          type: isOpening ? "opening" : "count",
          template: isOpening ? opening : null,
          templateId: isOpening
            ? (opening.opening_template_id || item.meta?.lineTemplate || null)
            : null,
          stroke: item.meta?.stroke || "red",
          data: item.data || [],
          originalItem: item,
          opening,
          openingMatchKey: openingIdUnique,
          originalIndex: index,
        };
      }
    });
    Object.values(groupedCounts).forEach(item => {
      list.push(item);
    });

    // 3. Areas
    const areas = data.area || [];
    const groupedAreas = {};
    areas.forEach((item) => {
      const idUnique = String(item?.meta?.idUnique || "").trim();
      const groupKey = idUnique !== "" ? idUnique : item.meta.name;
      const val = parseFloat(item.data?.[0]?.[1] || 0);
      if (groupedAreas[groupKey]) {
        groupedAreas[groupKey].value += val;
        groupedAreas[groupKey].data = groupedAreas[groupKey].data.concat(item.data || []);
      } else {
        groupedAreas[groupKey] = {
          name: item.meta.name,
          idUnique,
          value: val,
          unit: item.data?.[1]?.[1] || "sq ft",
          color: item.meta.stroke || "#000",
          fill: item.meta.fill,
          type: "area",

          templateId: getTemplateId(
            item.meta?.lineTemplate,
            item.meta?.lineTemplateId
          ),

          stroke: item.meta.stroke,
          data: item.data || [],
          originalItem: item,
        };
      }
    });
    Object.values(groupedAreas).forEach(item => {
      item.value = parseFloat(item.value.toFixed(2));
      list.push(item);
    });

    // 4. Perimeters
    const perimeters = data.perimeter || [];
    const groupedPerimeters = {};
    perimeters.forEach((item) => {
      const idUnique = String(item?.meta?.idUnique || "").trim();
      const groupKey = idUnique !== "" ? idUnique : item.meta.name;
      const val = parseFloat(item.data?.[0]?.[1] || 0);
      if (groupedPerimeters[groupKey]) {
        groupedPerimeters[groupKey].value += val;
        groupedPerimeters[groupKey].data = groupedPerimeters[groupKey].data.concat(item.data || []);
      } else {
        groupedPerimeters[groupKey] = {
          name: item.meta.name,
          idUnique,
          value: val,
          unit: item.data?.[0]?.[2] || "ft",
          color: item.meta.stroke || "#000",
          type: "perimeter",

          templateId: getTemplateId(
            item.meta?.lineTemplate,
            item.meta?.lineTemplateId
          ),

          stroke: item.meta.stroke,
          data: item.data || [],
          originalItem: item,
        };
      }
    });
    Object.values(groupedPerimeters).forEach(item => {
      item.value = parseFloat(item.value.toFixed(2));
      list.push(item);
    });

    return list;
  }, [data]);

  const handleTakeoffClick = async (item) => {
    setDetails({ name: item.name, data: item.data });

    if (item.type === "count") return;

    if (item.type === "opening") {
      setTakeoffFormData({
        ...item.opening,
        name: item.name,
        takeoff_name: item.name,
        color: item.color,
        opening_template_id: item.templateId,
        opening_match_key: item.openingMatchKey,
      });
      setOpenOpeningPopupDraw(true);
      return;
    }

    try {
      const dataToSend = {
        template_name: item.name,
        template_id: item.templateId ?? null,
        idUnique: item.idUnique || "",
        type: item.type,
        projectId: projectId,
      };

      const response = await fetch(`/api/ObtenData`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${routes.__token}`,
        },
        body: JSON.stringify(dataToSend),
      });
      const resData = await response.json();

      if (resData.status === 200) {
        let resultado = resData.resultado;

        if (item.type === "length") {
          let lineTemplateParaPopup = item.template;
          let lineTemplateId = item.templateId;

          if (typeof lineTemplateParaPopup === "object" && lineTemplateParaPopup !== null) {
            lineTemplateParaPopup = JSON.stringify(lineTemplateParaPopup);
          }

          resultado = {
            ...resultado,
            name: item.name,
            idUnique: item.idUnique || "",
            lineTemplate: lineTemplateId,
            wall_length: item.value,
            total_wall_length: item.value,
          };
          setTakeoffFormData(resultado);
          setTakeoffMemoData({
            length: item.value,
            name: item.name,
            lineTemplate: lineTemplateParaPopup,
            lineTemplateId: lineTemplateId,
            idUnique: item.idUnique || "",
            mode: "viewtakeoff",
          });
          setOpenLengthPopup(true);
        } else if (item.type === "area") {
          const firstEntry = item.originalItem;
          resultado = {
            ...resultado,
            name: item.name,
            areaValue: item.value,
          };
          setTakeoffFormData(resultado);
          setTakeoffMemoData({
            area: item.value,
            name: item.name,
            perimetro: firstEntry.data?.[1]?.[1] || 0,

            lineTemplate: item.templateId,
            lineTemplateId: item.templateId,

            idUnique: item.idUnique || "",
            path: firstEntry.path || [],
            mode: "viewtakeoff",
          });
          setOpenAreaPopup(true);
        } else if (item.type === "perimeter") {
          resultado = resultado ?? {};
          resultado.name = item.name;
          resultado.PerimeterValue = item.value;

          setTakeoffFormData(resultado);
          setTakeoffMemoData({
            name: item.name,
            perimetro: item.value,

            lineTemplate: item.templateId,
            lineTemplateId: item.templateId,

            idUnique: item.idUnique || "",
            path: item.originalItem?.path || [],
            mode: "viewtakeoff",
          });
          setOpenPerimeterPopup(true);
        }
      }
    } catch (e) {
      console.error("Error fetching takeoff data on click:", e);
    }
  };
  useEffect(() => {
    let tempDataCallBack = (e) => {
      let { data } = e.detail;
      setDetails(data);
    };
    signal.listen("takeoff.temp", tempDataCallBack);

    return () => {
      setDetails(null);
      signal.unsubscribe("takeoff.temp", tempDataCallBack);
    };
  }, [pathname]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const closeMenu = () => {
      setTemplateContextMenu({
        visible: false,
        x: 0,
        y: 0,
        item: null,
      });
    };

    window.addEventListener("click", closeMenu);

    return () => {
      window.removeEventListener("click", closeMenu);
    };
  }, []);

  const fetchTemplateFullById = async (item) => {
    try {
      if (!item?.id) {
        return item;
      }

      if (templateCache[item.id]) {
        return templateCache[item.id];
      }

      let url = "";

      if (item.template_type === "length") {
        url = `/api/get-line-template-by-id/${item.id}`;
      }

      if (item.template_type === "area") {
        url = `/api/get-area-template-by-id/${item.id}`;
      }

      if (item.template_type === "perimeter") {
        url = `/api/get-perimeter-template-by-id/${item.id}`;
      }

      if (item.template_type === "opening") {
        url = `/api/get-opening-template-by-id/${item.id}`;
      }

      if (!url) {
        return item;
      }

      const response = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${routes.__token}`,
          Accept: "application/json",
        },
      });

      const data = await response.json();

      if (data?.status === 200 && data?.template) {

        setTemplateCache(prev => ({
          ...prev,
          [item.id]: data.template
        }));

        return data.template;
      }

      return item;
    } catch (error) {
      console.error("Error loading full template:", error);
      return item;
    }
  };

  const fetchTemplates = async () => {
    try {
      //const url = routes.templates;
      const url = `/api/templates-lite`;
      const response = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${routes.__token}`,
        },
      });

      if (!response.ok) throw new Error(`Error HTTP ${response.status}`);

      const data = await response.json();
      if (data && data.template) {
        //console.log(`📦 Templates cargados:`, data.template);
        setLineTemplate(data.template);
      } else {
        //console.warn("⚠️ No se encontraron templates en la respuesta.");
        setLineTemplate([]);
      }
    } catch (error) {
      console.error("❌ Error al obtener templates:", error);
      setLineTemplate([]);
    }
  };

  useEffect(() => {
    fetchTemplates();
  }, []);

  useEffect(() => {
    const fetchCurrentUser = async () => {
      try {
        const response = await fetch(`/api/user`, {
          method: "GET",
          headers: {
            Authorization: `Bearer ${routes.__token}`,
            Accept: "application/json",
          },
        });

        const data = await response.json();
        setUserRole(data?.role ?? data?.user?.role ?? null);
      } catch (error) {
        console.error("Error loading current user:", error);
      }
    };

    fetchCurrentUser();
  }, []);

  useEffect(() => {
    const handleNewTemplate = (nuevoTemplate) => {
      console.log("🧩 Nuevo template recibido:", nuevoTemplate);
      fetchTemplates();
    };

    signal.listen("template.created", handleNewTemplate);
    return () => signal.unsubscribe("template.created", handleNewTemplate);
  }, []);

  /*const handleEditTemplate = (item) => {
    if (!canManageTemplate(item)) {
      toast.warning("You cannot edit a global template.", {
        autoClose: 10000,
        pauseOnHover: true,
      });
      return;
    }
    setTemplateContextMenu({
      visible: false,
      x: 0,
      y: 0,
      item: null,
    });

    setFormData(item);

    if (item.template_type === "length") {
      setOpenLengthPopupEdit(true);
    }

    if (item.template_type === "perimeter") {
      setOpenPerimeterPopupEdit(true);
    }

    if (item.template_type === "area") {
      setOpenAreaPopupEdit(true);
    }
  };*/

  const handleEditTemplate = async (item) => {
    if (!canManageTemplate(item)) {
      toast.warning("You cannot edit a global template.", {
        autoClose: 10000,
        pauseOnHover: true,
      });
      return;
    }

    setTemplateContextMenu({
      visible: false,
      x: 0,
      y: 0,
      item: null,
    });

    const fullTemplate = await fetchTemplateFullById(item);

    setFormData(fullTemplate);

    if (fullTemplate.template_type === "length") {
      setOpenLengthPopupEdit(true);
    }

    if (fullTemplate.template_type === "perimeter") {
      setOpenPerimeterPopupEdit(true);
    }

    if (fullTemplate.template_type === "area") {
      setOpenAreaPopupEdit(true);
    }

    if (fullTemplate.template_type === "opening") {
      setOpenOpeningPopupEdit(true);
    }
  };

  const handleDeleteTemplate = (id, item = null) => {
    if (item && !canManageTemplate(item)) {
      toast.warning("You cannot delete a global template.", {
        autoClose: 10000,
        pauseOnHover: true,
      });
      return;
    }
    Swal.fire({
      title: "Are you sure?",
      text: "You won't be able to revert this!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Yes, delete it!",
      cancelButtonText: "Cancel"
    }).then(async (result) => {
      if (result.isConfirmed) {
        try {
          const response = await fetch(routes.deleteTemplate, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${routes.__token}`,
            },
            body: JSON.stringify({ id }),
          });

          if (!response.ok) throw new Error("Error deleting template");

          Swal.fire("Deleted!", "Template has been deleted.", "success");
          fetchTemplates();
        } catch (error) {
          console.error("❌ Error deleting template:", error);
          Swal.fire("Error", "Could not delete the template.", "error");
        }
      }
    });
  };

  const startSavedLengthTemplate = async (item, drawingTemplate) => {
    const dB = new Dexie("takeoff");

    dB.version(1).stores({
      measurements: "takeoff, name",
    });

    await dB.open();
    await dB.measurements.clear();

    const takeoffName = drawingTemplate?.template_name ?? item.template_name;
    //const lineTemplate = JSON.stringify(item);
    const lineTemplate = item.id;
    const color = drawingTemplate?.color ?? "#000000";

    await dB.measurements.add({
      name: takeoffName,
      takeoff: "length",
      lineTemplate: lineTemplate,
    });

    await dB.measurements.add({
      name: takeoffName,
      takeoff: "length_old",
      lineTemplate: lineTemplate,
    });

    signal.emit("takeoff", {
      type: "length",
      openPopup: true,
      template: takeoffName,
      color: color,
    });
  };

  const startSavedAreaTemplate = async (item, drawingTemplate) => {
    const dB = new Dexie("takeoff");

    dB.version(1).stores({
      measurements: "takeoff, name",
    });

    await dB.open();
    await dB.measurements.clear();

    const takeoffName = drawingTemplate?.template_name ?? item.template_name;
    //const lineTemplate = JSON.stringify(item);
    const lineTemplate = item.id;
    const color = drawingTemplate?.color ?? "#000000";

    await dB.measurements.add({
      name: takeoffName,
      takeoff: "area",
      lineTemplate: lineTemplate,
    });

    await dB.measurements.add({
      name: takeoffName,
      takeoff: "area_old",
      lineTemplate: lineTemplate,
    });

    signal.emit("takeoff", {
      type: "area",
      openPopup: true,
      template: takeoffName,
      color: color,
    });
  };

  const startSavedPerimeterTemplate = async (item, drawingTemplate) => {
    const dB = new Dexie("takeoff");

    dB.version(1).stores({
      measurements: "takeoff, name",
    });

    await dB.open();
    await dB.measurements.clear();

    const takeoffName = drawingTemplate?.template_name ?? item.template_name;
    //const lineTemplate = JSON.stringify(item);
    const lineTemplate = item.id;
    const color = drawingTemplate?.color ?? "#000000";

    await dB.measurements.add({
      name: takeoffName,
      takeoff: "perimeter",
      lineTemplate: lineTemplate,
    });

    await dB.measurements.add({
      name: takeoffName,
      takeoff: "perimeter_old",
      lineTemplate: lineTemplate,
    });

    signal.emit("takeoff", {
      type: "perimeter",
      openPopup: true,
      template: takeoffName,
      color: color,
    });
  };

  /*const handleUseTemplate = async (item) => {
    //toast.info("Use template is under work", { ...toastOptions });}
    setFormData(item);

    switch (item.template_type) {
      case "length":
        setOpenLengthPopupDraw(true);
        break;

      case "perimeter":
        setOpenPerimeterPopupDraw(true);
        break;

      case "area":
        setOpenAreaPopupDraw(true);
        break;

      case "opening":
        setOpenOpeningPopupDraw(true);
        break;

      default:
        console.warn("Tipo de template no reconocido:", item.template_type);
        break;
    }

  };*/

  const handleUseTemplate = async (item) => {
    const fullTemplate = await fetchTemplateFullById(item);
    setFormData(fullTemplate);
    setTakeoffFormData(null);

    switch (fullTemplate.template_type) {
      case "length":
        try {
          const response = await fetch(`/api/drawing-template/${item.id}`, {
            method: "GET",
            headers: {
              Authorization: `Bearer ${routes.__token}`,
              Accept: "application/json",
            },
          });

          const data = await response.json();

          if (data?.drawing_template) {
            await startSavedLengthTemplate(fullTemplate, data.drawing_template);
            return;
          }

          setOpenLengthPopupDraw(true);
        } catch (error) {
          console.error("Error checking drawing_template:", error);
          setOpenLengthPopupDraw(true);
        }
        break;

      case "perimeter":
        try {
          const response = await fetch(`/api/drawing-template/${item.id}`, {
            method: "GET",
            headers: {
              Authorization: `Bearer ${routes.__token}`,
              Accept: "application/json",
            },
          });

          const data = await response.json();

          if (data?.drawing_template) {
            await startSavedPerimeterTemplate(fullTemplate, data.drawing_template);
            return;
          }

          setOpenPerimeterPopupDraw(true);
        } catch (error) {
          console.error("Error checking drawing_template perimeter:", error);
          setOpenPerimeterPopupDraw(true);
        }
        break;

      case "area":
        try {
          const response = await fetch(`/api/drawing-template/${item.id}`, {
            method: "GET",
            headers: {
              Authorization: `Bearer ${routes.__token}`,
              Accept: "application/json",
            },
          });

          const data = await response.json();

          if (data?.drawing_template) {
            await startSavedAreaTemplate(fullTemplate, data.drawing_template);
            return;
          }

          setOpenAreaPopupDraw(true);
        } catch (error) {
          console.error("Error checking drawing_template area:", error);
          setOpenAreaPopupDraw(true);
        }
        break;

      default:
        console.warn("Tipo de template no reconocido:", item.template_type);
        break;
    }
  };

  const handleTemplateContextMenu = (e, item) => {
    e.preventDefault();
    e.stopPropagation();

    setTemplateContextMenu({
      visible: true,
      x: e.clientX,
      y: e.clientY,
      item: item,
    });
  };
  function truncateString(str, maxLength) {
    if (str.length > maxLength) {
      return str.slice(0, maxLength) + "...";
    }
    return str;
  }
  const renderTemplateIcon = (item) => {
    const stroke = item.stroke || "#2F80ED";
    switch (item.template_type) {
      case "area":
        return (
          <span
            className="area-preview"
            style={{
              borderColor: stroke,
              backgroundColor: stroke + "4a",
              display: "inline-block"
            }}
          ></span>
        );
      case "perimeter":
        return (
          <span
            className="perimeter-preview"
            style={{
              borderColor: stroke,
              display: "inline-block"
            }}
          ></span>
        );
      case "length":
      default:
        return (
          <span
            className="line-preview"
            style={{
              borderColor: stroke,
              display: "inline-block"
            }}
          ></span>
        );
    }
  };

  const renderTemplateScope = (item) => {
    const isGlobal = Number(item?.is_global ?? 0) === 1;

    return (
      <span
        className={
          isGlobal
            ? "template-scope template-scope-global"
            : "template-scope template-scope-user"
        }
        title={isGlobal ? "Global Template" : "My Template"}
      >
        <i
          className={
            isGlobal
              ? "fa-solid fa-earth-americas"
              : "fa-regular fa-user"
          }
        ></i>
      </span>
    );
  };

  const toastOptions = {
    position: "top-right",
    autoClose: 5000,
    hideProgressBar: false,
    closeOnClick: true,
    pauseOnHover: true,
    draggable: true,
    progress: 0,
  };
  //   console.log(template);
  const tradeOptions = [...new Set(lineTemplate.map(item => item.trade_name))];

  const canManageTemplate = (item) => {
    const isAdmin = Number(userRole ?? 0) === 1;
    const isGlobal = Number(item?.is_global ?? 0) === 1;

    return !isGlobal || isAdmin;
  };

  return (
    <div className={`sidebar__right ${isRightBarOpen ? "open" : "closed"}`}>
      <div className="right-btn-toggle">
        <button
          className="right-collapse-btn"
          onClick={toggleRightBarState}
          title={isRightBarOpen ? "Hide takeoff panel" : "Show takeoff panel"}
        >
          {isRightBarOpen ? (
            <i className="fa fa-angle-right" aria-hidden="true"></i>
          ) : (
            <i className="fa fa-angle-left" aria-hidden="true"></i>
          )}
        </button>
      </div>
      {templateContextMenu.visible && templateContextMenu.item && (
        <div
          className="template-context-menu"
          style={{
            top: templateContextMenu.y,
            left: templateContextMenu.x,
          }}
          onClick={(e) => e.stopPropagation()}
        >
          <button
            type="button"
            onClick={async () => {
              const item = templateContextMenu.item;

              setTemplateContextMenu({
                visible: false,
                x: 0,
                y: 0,
                item: null,
              });

              const fullTemplate = await fetchTemplateFullById(item);
              setFormData(fullTemplate);
              setTakeoffFormData(null);

              if (fullTemplate.template_type === "length") {
                setOpenLengthPopupDraw(true);
              }

              if (fullTemplate.template_type === "area") {
                setOpenAreaPopupDraw(true);
              }

              if (fullTemplate.template_type === "perimeter") {
                setOpenPerimeterPopupDraw(true);
              }

              if (fullTemplate.template_type === "opening") {
                setOpenOpeningPopupDraw(true);
              }
            }}
          >
            <i className="fa-solid fa-plus"></i> New Takeoff
          </button>
          <button
            type="button"
            onClick={() => handleEditTemplate(templateContextMenu.item)}
          >
            <i className="fa-solid fa-edit"></i> Edit
          </button>

          <button
            type="button"
            className="delete"
            onClick={() => {
              const templateId = templateContextMenu.item.id;

              setTemplateContextMenu({
                visible: false,
                x: 0,
                y: 0,
                item: null,
              });

              handleDeleteTemplate(templateId, templateContextMenu.item);
            }}
          >
            <i className="fa-solid fa-trash"></i> Delete
          </button>
        </div>
      )}

      <div className="sidebar_content">
        {!isRightBarOpen && (
          <div className="right-rail">
            <div className="right-rail-fixed">
              <button
                type="button"
                className="right-rail-btn right-rail-main"
                onClick={toggleRightBarState}
                title="Show panel"
              >
                <i className="fa-light fa-chevron-left"></i>
              </button>

              <button
                type="button"
                className={`right-rail-btn ${
                  activeTab === "takeoff" ? "active" : ""
                }`}
                onClick={() => setActiveTab("takeoff")}
                title="Takeoff"
              >
                <i className="fa-light fa-rocket"></i>
                <span>Takeoff</span>
              </button>

              <button
                type="button"
                className={`right-rail-btn ${
                  activeTab === "template" ? "active" : ""
                }`}
                onClick={() => setActiveTab("template")}
                title="Templates"
              >
                <i className="fa-light fa-table-cells"></i>
                <span>Templates</span>
              </button>

              <div className="right-rail-divider"></div>
            </div>
            <div className="right-rail-scroll">   
              {activeTab === "takeoff" &&
                uniqueTakeoffs.map((item, index) => (
                  <button
                    key={`rail-takeoff-${item.type}-${item.name}-${index}`}
                    type="button"
                    className="right-rail-mini-item"
                    style={{ borderLeftColor: item.color || "#2F80ED" }}
                    onClick={() => {
                      handleTakeoffClick(item);
                    }}
                    onMouseEnter={(e) => {
                      const rect = e.currentTarget.getBoundingClientRect();
                      setHoveredTakeoff({
                        type: "takeoff",
                        x: rect.left - 250,
                        y: rect.top,
                        name: item.name,
                        subtitle: `${item.type} • ${item.value} ${item.unit}`,
                        color: item.color || "#2F80ED",
                      });
                    }}
                    onMouseLeave={() => setHoveredTakeoff(null)}
                  >
                    {item.type === "area" && <i className="fa-light fa-square"></i>}
                    {item.type === "perimeter" && <i className="fa-light fa-vector-square"></i>}
                    {item.type === "length" && <i className="fa-light fa-arrows-left-right"></i>}
                    {item.type === "count" && <i className="fa-light fa-00"></i>}
                  </button>
                ))}

              {activeTab === "template" &&
                lineTemplate
                  .filter((item) => {
                    const tradeMatch = selectedTrade ? item.trade_name === selectedTrade : true;
                    const isGlobal = Number(item?.is_global ?? 0) === 1;

                    const scopeMatch =
                      templateFilter === "all"
                        ? true
                        : templateFilter === "global"
                          ? isGlobal
                          : !isGlobal;

                    return tradeMatch && scopeMatch;
                  })
                  .map((item) => (
                    <button
                      key={`rail-template-${item.id}`}
                      type="button"
                      className="right-rail-mini-item"
                      style={{ borderLeftColor: item.stroke || "#2F80ED" }}
                      onClick={() => {
                        setActiveTab("template");
                        handleUseTemplate(item);
                      }}
                      onMouseEnter={(e) => {
                        const rect = e.currentTarget.getBoundingClientRect();
                        setHoveredTakeoff({
                          type: "template",
                          x: rect.left - 250,
                          y: rect.top,
                          name: item.template_name,
                          subtitle: `${item.template_type} • ${item.trade_name}`,
                          color: item.stroke || "#2F80ED",
                        });
                      }}
                      onMouseLeave={() => setHoveredTakeoff(null)}
                    >
                      {item.template_type === "area" && <i className="fa-light fa-square"></i>}
                      {item.template_type === "perimeter" && <i className="fa-light fa-vector-square"></i>}
                      {item.template_type === "length" && <i className="fa-light fa-arrows-left-right"></i>}
                    </button>
                  ))}

              {hoveredTakeoff && (
                <div
                  className="right-rail-hover-card"
                  style={{
                    left: hoveredTakeoff.x,
                    top: hoveredTakeoff.y,
                  }}
                >
                  <span
                    className="right-rail-hover-color"
                    style={{ backgroundColor: hoveredTakeoff.color }}
                  ></span>

                  <div>
                    <strong>{hoveredTakeoff.name}</strong>
                    <small>{hoveredTakeoff.subtitle}</small>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}   
        <div className="w-100 d-inline-block takeoff-template-tabs expanded-only">
          <div className="tab d-inline-block">
            {/*<button
              className="right-collapse-btn"
              onClick={toggleRightBarState}
              title={isRightBarOpen ? "Hide takeoff panel" : "Show takeoff panel"}
            >
              {isRightBarOpen ? (
                <i className="fa fa-angle-right" aria-hidden="true"></i>
              ) : (
                <i className="fa fa-angle-left" aria-hidden="true"></i>
              )}
            </button> */}
            <button
              className={`tablinks ${activeTab === "takeoff" ? "active" : ""}`}
              onClick={() => handleTabClick("takeoff")}
            >
              <img src={assetPath + "images/tekeoff-icon.svg"} alt="takeoff" />
              TAKEOFF
            </button>
            <button
              className={`tablinks ${activeTab === "template" ? "active" : ""}`}
              onClick={() => handleTabClick("template")}
            >
              <img src={assetPath + "images/grid-icon.svg"} alt="template" />
              TEMPLATE
            </button>
          </div>
        </div>
        {activeTab === "takeoff" && isRightBarOpen && (
          <div className="takeoff__tab">
            <details className="tool__box details-small" open>
              <summary>
                <div className="tool__box-header">
                  <i className="fa-light fa-ruler"></i> Takeoff Details
                </div>
              </summary>
              <div className="tool__box-body">
                {details ? <TakeoffTable data={details} /> : <></>}
              </div>
            </details>
            <details className="tool__box details-full" open>
              <summary>
                <div className="tool__box-header">
                  <i className="fa-light fa-grip-lines"></i> Takeoff
                </div>
              </summary>
              <div className="tool__box-body takeoff-card-list">
                {uniqueTakeoffs.length > 0 ? (
                  uniqueTakeoffs.map((item, index) => (
                    <button
                      key={`${item.type}-${item.name}-${index}`}
                      type="button"
                      className="takeoff-card-modern"
                      onClick={() => handleTakeoffClick(item)}
                      onContextMenu={(e) => {
                          e.preventDefault();

                          setTakeoffContext({
                              visible: true,
                              type: item.type,
                              details: {
                                  ...item,
                                  x: e.clientX,
                                  y: e.clientY,
                              },
                          });
                      }}
                    >
                      <span
                        className="takeoff-card-color"
                        style={{ backgroundColor: item.color || "#2F80ED" }}
                      ></span>

                      <span className="takeoff-card-icon">
                        {item.type === "area" && <i className="fa-light fa-square"></i>}
                        {item.type === "perimeter" && <i className="fa-light fa-vector-square"></i>}
                        {item.type === "length" && <i className="fa-light fa-arrows-left-right"></i>}
                        {item.type === "count" && <i className="fa-light fa-00"></i>}
                      </span>

                      <span className="takeoff-card-info">
                        <strong>{item.name}</strong>
                        <small>{item.type}</small>
                      </span>

                      <span className="takeoff-card-value">
                        <strong>{item.value}</strong>
                        <small>{item.unit}</small>
                      </span>
                    </button>
                  ))
                ) : (
                  <div className="takeoff-empty-state">
                    <i className="fa-light fa-ruler-combined"></i>
                    <strong>No takeoffs yet</strong>
                    <span>Start measuring to see results here.</span>
                  </div>
                )}
              </div>
            </details>
          </div>
        )}
        {activeTab === "template" && isRightBarOpen && (
          <div className="template__tab">
            <details
              className="tool__box details-full"
              open={activeTab === "template"}
            >
              <summary>Templates</summary>

              {/* 🔹 Select de filtro */}
              <div className="filter-trade">
                <select
                  id="tradeSelect"
                  value={selectedTrade}
                  onChange={(e) => setSelectedTrade(e.target.value)}
                >
                  <option value="">All Trades</option>
                  {tradeOptions.map((trade, index) => (
                    <option key={index} value={trade}>
                      {trade}
                    </option>
                  ))}
                </select>
              </div>
              <div className="filter-template-type">
                <select
                  value={templateFilter}
                  onChange={(e) => setTemplateFilter(e.target.value)}
                >
                  <option value="all">All Templates</option>
                  <option value="global">Global Templates</option>
                  <option value="my">My Templates</option>
                </select>
              </div>

              <div className="tool__box-body template-card-list">
                {lineTemplate.length > 0 ? (
                  lineTemplate
                    .filter((item) => {
                      const tradeMatch = selectedTrade
                        ? item.trade_name === selectedTrade
                        : true;

                      const isGlobal = Number(item?.is_global ?? 0) === 1;

                      const scopeMatch =
                        templateFilter === "all"
                          ? true
                          : templateFilter === "global"
                            ? isGlobal
                            : !isGlobal;

                      return tradeMatch && scopeMatch;
                    })
                    .map((item) => (
                      <button
                        key={item.id}
                        type="button"
                        className="template-card-modern"
                        onClick={() => handleUseTemplate(item)}
                        onContextMenu={(e) => handleTemplateContextMenu(e, item)}
                      >
                        <span className="template-card-type">
                          {renderTemplateIcon(item)}
                        </span>

                        <span className="template-card-info">
                          <strong>{truncateString(item.template_name, 34)}</strong>
                          <small>{item.template_type} • {item.trade_name}</small>
                        </span>

                        {renderTemplateScope(item)}
                      </button>
                    ))
                ) : (
                  <div className="takeoff-empty-state">
                    <i className="fa-light fa-table-cells"></i>
                    <strong>No templates yet</strong>
                    <span>Create or import templates to start faster.</span>
                  </div>
                )}
              </div>
            </details>
          </div>
        )}
        {openPerimeterPopupDraw && (
          <PerimeterPopupDraw
            setDisplay={(isOpen) => setOpenPerimeterPopupDraw(isOpen)}
            current_data={formData}
          />
        )}
        {openLengthPopupDraw && (
          <LengthPopupDraw
            setDisplay={(isOpen) => setOpenLengthPopupDraw(isOpen)}
            current_data={formData}
          />
        )}
        {openAreaPopupDraw && (
          <AreaPopupDraw
            setDisplay={(isOpen) => setOpenAreaPopupDraw(isOpen)}
            current_data={formData}
          />
        )}
        {openOpeningPopupDraw && (
          <OpeningPopupDraw
            setDisplay={(isOpen) => setOpenOpeningPopupDraw(isOpen)}
            current_data={
              takeoffFormData?.opening_match_key ? takeoffFormData : formData
            }
          />
        )}
        {openPerimeterPopupEdit && (
          <PerimeterPopup
            setDisplay={(isOpen) => setOpenPerimeterPopupEdit(isOpen)}
            perimeterData={formData}
            takeoff={memoizedTemplateEdit}
            pathname={pathname}
          />
        )}
        {openLengthPopupEdit && (
          <LengthPopup
            setDisplay={(isOpen) => setOpenLengthPopupEdit(isOpen)}
            Current_data={formData}
            takeoff={memoizedTemplateEdit}
            pathname={pathname}
          />
        )}
        {openAreaPopupEdit && (
          <AreaPopup
            setDisplay={(isOpen) => setOpenAreaPopupEdit(isOpen)}
            areaData={formData}
            takeoff={memoizedTemplateEdit}
            pathname={pathname}
          />
        )}
        {openOpeningPopupEdit && (
          <OpeningPopup
            setDisplay={(isOpen) => setOpenOpeningPopupEdit(isOpen)}
            openingData={formData}
            takeoff={memoizedTemplateEdit}
          />
        )}
        {openLengthPopup && (
          <LengthPopup
            setDisplay={setOpenLengthPopup}
            Current_data={takeoffFormData}
            takeoff={takeoffMemoData}
            pathname={pathname}
          />
        )}

        {openAreaPopup && (
          <AreaPopup
            setDisplay={setOpenAreaPopup}
            areaData={takeoffFormData}
            takeoff={takeoffMemoData}
            pathname={pathname}
          />
        )}

        {openPerimeterPopup && (
          <PerimeterPopup
            setDisplay={setOpenPerimeterPopup}
            perimeterData={takeoffFormData}
            takeoff={takeoffMemoData}
            pathname={pathname}
          />
        )}

        {takeoffContext.visible &&
            takeoffContext.type === "length" && (
                <LineRowContext details={takeoffContext.details} />
        )}

        {takeoffContext.visible &&
            takeoffContext.type === "area" && (
                <AreaRowContext details={takeoffContext.details} />
        )}

        {takeoffContext.visible &&
            takeoffContext.type === "perimeter" && (
                <PerimeterRowContext details={takeoffContext.details} />
        )}
      </div>
    </div>
  );
}

export default RightBar;
